//! Columns, structural columns and isolated footings; beams, strip footings and the MEP runs
//! (pipes, ducts, conduits, cable trays, wires, down and earthing conductors, cabling).
//!
//! A run is a straight element from `start` to `end` in plan; its `offset` is the height over its
//! level of its `justify` line at the start, `end_offset` at the end (level when none). Its
//! section is its type's, square to its axis, so a sloped run is `depth / cos θ` deep plumb. A
//! column (and a footing, a column laid down) stands at `at` on its level, `base_offset` over it,
//! up to its `top_level` or `height` mm tall. `geom` is where the geometry is, for whoever needs it
//! (IFC export, schedules, plans, rebar).

pub mod columns;
pub mod geom;
pub mod read;
pub mod rules;
pub mod runs;
pub mod view;

use crate::json::Value;
use crate::project::Project;
use crate::session::Session;
use crate::structure::common::R;

pub use geom::{
    column_geom, column_height, column_outline, column_span, default_justify, may_stand, run_geom, run_line,
    section, type_guid, type_name, ColumnGeom, Justify, RunGeom, RunLine, Section,
};

/// Runs the commands of this part.
pub fn run(s: &mut Session, cid: &str, p: &Value) -> R<Value> {
    match cid {
        "column" => columns::column(s, cid, "column", p),
        "structural_column" => columns::column(s, cid, "structuralcolumn", p),
        "footing" => columns::footing(s, cid, p),
        _ => runs::run(s, cid, p),
    }
    .map_err(clip)
}

/// The longest a command's own refusal is (the model's rules are said whole).
const MAX_ERROR: usize = 2000;

/// A command's refusal cut to its first 2000 characters, saying how many more there were.
fn clip(e: String) -> String {
    let n = e.chars().count();
    if n <= MAX_ERROR {
        return e;
    }
    let mut out: String = e.chars().take(MAX_ERROR).collect();
    out.push_str(&format!("… ({} more characters)", n - MAX_ERROR));
    out
}

/// The model rules of this part, checked after every command.
pub fn check(pr: &Project) -> R<()> {
    rules::check(pr)
}

/// What `elements` shows of one besides its fields, added to `x`.
pub fn element_view(pr: &Project, id: u64, x: &mut Value) {
    view::element_view(pr, id, x)
}
//! `beam`, `strip_footing`, `pipe`, `duct`, `conduit`, `cable_tray`, `wire`, `down_conductor`,
//! `ground_conductor`, `cabling`: a run for each segment of a chain of points.

use super::geom::{default_justify, Justify};
use super::read::{chain_points, level_param, type_name_param};
use crate::commands::params::{opt_bool, opt_num, opt_text};
use crate::json::{Map, Value};
use crate::session::Session;
use crate::structure::common::{add_element, new_guid, type_guid, R};

/// The category a run command makes.
pub fn category_of(cid: &str) -> Option<&'static str> {
    Some(match cid {
        "beam" => "beam",
        "strip_footing" => "stripfooting",
        "pipe" => "pipe",
        "duct" => "duct",
        "conduit" => "conduit",
        "cable_tray" => "cabletray",
        "wire" => "wire",
        "down_conductor" => "downconductor",
        "ground_conductor" => "groundconductor",
        "cabling" => "cable",
        _ => return None,
    })
}

/// What a run command was asked, read and checked as the original does.
pub struct RunArgs {
    pub points: Vec<[f64; 2]>,
    pub closed: bool,
    pub level: u64,
    /// The type's name (or what was given, where the project has no such type: the model's check
    /// refuses it).
    pub type_name: String,
    pub offset: f64,
    pub end_offset: Option<f64>,
    pub justify: Justify,
    pub system: Option<String>,
}

impl RunArgs {
    /// The segments, one run each.
    pub fn segments(&self) -> Vec<([f64; 2], [f64; 2])> {
        segments(&self.points, self.closed)
    }
}

/// The segments of a chain: each point to the next, and the last back to the first when closed.
pub fn segments(points: &[[f64; 2]], closed: bool) -> Vec<([f64; 2], [f64; 2])> {
    let mut out: Vec<([f64; 2], [f64; 2])> = points.windows(2).map(|w| (w[0], w[1])).collect();
    if closed && points.len() >= 2 {
        out.push((points[points.len() - 1], points[0]));
    }
    out
}

pub fn read_args(s: &Session, cid: &str, cat: &str, p: &Value) -> R<RunArgs> {
    let pr = &s.project;
    let points = chain_points(p, cid)?;
    let closed = opt_bool(p, cid, "closed")?.unwrap_or(false);
    let level = level_param(pr, cid, p)?;
    let type_name = match opt_text(p, cid, "type")? {
        Some(t) => type_name_param(pr, &t),
        None => match crate::structure::types::default_type(pr, cat) {
            Some(t) => t,
            None => return Err(format!("{}: the model has no types for this", cid)),
        },
    };
    let offset = opt_num(p, cid, "offset")?.unwrap_or(0.0);
    let end_offset = opt_num(p, cid, "end_offset")?;
    let n = segments(&points, closed).len();
    if end_offset.is_some() && n != 1 {
        return Err(format!("{}: `end_offset` is the height of one run's end: give 2 points", cid));
    }
    let justify = match opt_text(p, cid, "justify")? {
        Some(j) => match Justify::parse(&j) {
            Some(x) => x,
            None => return Err(format!("{}: `justify` is top, centre or bottom, not `{}`", cid, j)),
        },
        None => default_justify(cat),
    };
    let system = opt_text(p, cid, "system")?.filter(|x| !x.is_empty());
    Ok(RunArgs { points, closed, level, type_name, offset, end_offset, justify, system })
}

/// A run as the file holds it.
pub fn run_json(
    cat: &str,
    type_ref: &str,
    level_guid: &str,
    a: [f64; 2],
    b: [f64; 2],
    offset: f64,
    end_offset: Option<f64>,
    justify: Justify,
    system: Option<&str>,
) -> Value {
    let mut m = Map::new();
    m.insert("guid", Value::s(&new_guid()));
    m.insert("category", Value::s(cat));
    m.insert("type", Value::s(type_ref));
    m.insert("level", Value::s(level_guid));
    m.insert("start", Value::from(a));
    m.insert("end", Value::from(b));
    m.insert("offset", Value::f(offset));
    if let Some(e) = end_offset {
        m.insert("end_offset", Value::f(e));
    }
    m.insert("justify", Value::s(justify.name()));
    if let Some(sys) = system {
        m.insert("system", Value::s(sys));
    }
    Value::Obj(m)
}

pub fn run(s: &mut Session, cid: &str, p: &Value) -> R<Value> {
    let cat = category_of(cid).ok_or_else(|| format!("{}: not supported here", cid))?;
    let a = read_args(s, cid, cat, p)?;
    let level_guid = s.project.guid_of(a.level).unwrap_or_default();
    // the type by its GUID; a name the project hasn't stays a name, which the check refuses
    let type_ref = type_guid(&s.project, cat, &a.type_name).unwrap_or_else(|| a.type_name.clone());
    let mut ids = Vec::new();
    for (x, y) in a.segments() {
        let e = run_json(cat, &type_ref, &level_guid, x, y, a.offset, a.end_offset, a.justify, a.system.as_deref());
        ids.push(Value::u(add_element(s, e)));
    }
    Ok(crate::jobj! {"ids" => Value::Arr(ids)})
}

//! Where a run and a column are: a run's centre line and section, a column's base, top and plan.
//! What IFC export, schedules, plans and rebar ask of a member, from the element as the file holds it.

use super::read::{element_by_guid, lib_by_guid, parse_guid};
use crate::json::Value;
use crate::project::Project;
use crate::structure::common::{type_kind, type_of, types_of};

/// Within this (mm) in plan a run's ends are one over the other: it stands.
pub const TOL: f64 = 1.0;

/// The steepest a beam or a strip footing may slope, degrees.
pub const MAX_SLOPE: f64 = 75.0;

/// A member's section, from its type: `width` across by `depth` deep, or round (`width` across).
#[derive(Clone, Debug, PartialEq)]
pub struct Section {
    pub width: f64,
    pub depth: f64,
    pub round: bool,
    /// The material's GUID (a run type's; a column type has none).
    pub material: Option<String>,
}

/// The line of a run's section its heights are given at.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Justify {
    Top,
    Centre,
    Bottom,
}

impl Justify {
    pub fn parse(s: &str) -> Option<Justify> {
        match s.to_lowercase().as_str() {
            "top" => Some(Justify::Top),
            "centre" | "center" => Some(Justify::Centre),
            "bottom" => Some(Justify::Bottom),
            _ => None,
        }
    }
    pub fn name(self) -> &'static str {
        match self {
            Justify::Top => "top",
            Justify::Centre => "centre",
            Justify::Bottom => "bottom",
        }
    }
    /// IFC's cardinal point of the line: top 8, middle 5, bottom 2.
    pub fn cardinal_point(self) -> u32 {
        match self {
            Justify::Top => 8,
            Justify::Centre => 5,
            Justify::Bottom => 2,
        }
    }
}

/// The justification a category's runs take unless told: a beam's and a strip footing's top,
/// any other's middle.
pub fn default_justify(cat: &str) -> Justify {
    match cat {
        "beam" | "stripfooting" => Justify::Top,
        _ => Justify::Centre,
    }
}

/// Whether a run of this category may stand upright (a riser): all but beams and strip footings.
pub fn may_stand(cat: &str) -> bool {
    !matches!(cat, "beam" | "stripfooting")
}

/// The type an element names (its `type`: a GUID of the category's library kind, or a name):
/// its name, if the project has a type of that name.
pub fn type_name(pr: &Project, e: &Value) -> Option<String> {
    let cat = e.get("category")?.as_str()?;
    let t = e.get("type")?.as_str()?;
    let types = types_of(pr, cat)?;
    if parse_guid(t).is_some() {
        if let Some(id) = lib_by_guid(pr, t) {
            let le = pr.library.get(&id)?;
            if le.get("kind").and_then(|k| k.as_str()) == Some(type_kind(cat).as_str()) {
                let n = le.get("name")?.as_str()?;
                return if types.contains(n) { Some(n.to_string()) } else { None };
            }
        }
    }
    if types.contains(t) {
        Some(t.to_string())
    } else {
        None
    }
}

/// The GUID of the type an element is of.
pub fn type_guid(pr: &Project, e: &Value) -> Option<String> {
    let cat = e.get("category")?.as_str()?;
    let name = type_name(pr, e)?;
    pr.lib_guid(&type_kind(cat), &name)
}

/// A type's section, as `types` holds it.
pub fn section_of_type(t: &Value) -> Section {
    let width = t.get("width").and_then(|x| x.as_f64()).unwrap_or(0.0);
    let round = t.get("round").and_then(|x| x.as_bool()).unwrap_or(false);
    let depth = t.get("depth").and_then(|x| x.as_f64()).unwrap_or(width);
    let material = t.get("material").and_then(|x| x.as_str()).map(|s| s.to_string());
    Section { width, depth, round, material }
}

/// The section of a run or a column, from its type.
pub fn section(pr: &Project, e: &Value) -> Option<Section> {
    let cat = e.get("category")?.as_str()?;
    let name = type_name(pr, e)?;
    Some(section_of_type(type_of(pr, cat, &name)?))
}

/// The level an element stands on (its `level`), when it is one.
pub fn level_of_element(pr: &Project, e: &Value, key: &str) -> Option<u64> {
    let g = e.get(key)?.as_str()?;
    let id = element_by_guid(pr, g)?;
    if pr.category(id) == Some("level") {
        Some(id)
    } else {
        None
    }
}

pub fn elevation(pr: &Project, level: u64) -> f64 {
    pr.el(level).and_then(|e| e.get("elevation")).and_then(|x| x.as_f64()).unwrap_or(0.0)
}

fn f(e: &Value, k: &str) -> Option<f64> {
    e.get(k).and_then(|x| x.as_f64())
}

fn pt(e: &Value, k: &str) -> Option<[f64; 2]> {
    let a = e.get(k)?.as_arr()?;
    Some([a.first()?.as_f64()?, a.get(1)?.as_f64()?])
}

/// A run's line where its heights are given: plan ends and their heights over its level.
#[derive(Clone, Debug, PartialEq)]
pub struct RunLine {
    pub start: [f64; 2],
    pub end: [f64; 2],
    /// `offset` and `end_offset` (the same when it has none), mm over the level.
    pub offset: f64,
    pub end_offset: f64,
    pub justify: Justify,
}

impl RunLine {
    /// Its length in plan.
    pub fn plan_length(&self) -> f64 {
        let dx = self.end[0] - self.start[0];
        let dy = self.end[1] - self.start[1];
        (dx * dx + dy * dy).sqrt()
    }
    /// How far its end is over its start.
    pub fn rise(&self) -> f64 {
        self.end_offset - self.offset
    }
    /// Its length along the slope.
    pub fn length(&self) -> f64 {
        let dx = self.end[0] - self.start[0];
        let dy = self.end[1] - self.start[1];
        let dz = self.rise();
        (dx * dx + dy * dy + dz * dz).sqrt()
    }
    /// Its ends are one over the other (within `TOL` in plan).
    pub fn stands(&self) -> bool {
        self.plan_length() <= TOL
    }
    /// Its slope from the horizontal, degrees (90 when it stands).
    pub fn slope_degrees(&self) -> f64 {
        self.rise().abs().atan2(self.plan_length()).to_degrees()
    }
}

/// The line a run's heights are given at, from the element.
pub fn run_line(e: &Value) -> Option<RunLine> {
    let start = pt(e, "start")?;
    let end = pt(e, "end")?;
    let offset = f(e, "offset").unwrap_or(0.0);
    let end_offset = f(e, "end_offset").unwrap_or(offset);
    let cat = e.get("category").and_then(|c| c.as_str()).unwrap_or("");
    let justify = e
        .get("justify")
        .and_then(|j| j.as_str())
        .and_then(Justify::parse)
        .unwrap_or_else(|| default_justify(cat));
    Some(RunLine { start, end, offset, end_offset, justify })
}

/// A run in the model: its centre line (absolute heights), its section, its length.
#[derive(Clone, Debug, PartialEq)]
pub struct RunGeom {
    pub line: RunLine,
    pub section: Section,
    /// The elevation of its level.
    pub elevation: f64,
    /// The centre line's ends, [x, y, z] with z absolute (the level's elevation added).
    pub axis: [[f64; 3]; 2],
    /// Along the slope, mm.
    pub length: f64,
    /// Half its section's depth measured plumb (depth / 2 / cos θ; 0 when it stands).
    pub half: f64,
    pub stands: bool,
}

/// How far below (or above) the justify line the centre line is, plumb: half the depth over the
/// cosine of the slope, or none for a run that stands.
pub fn plumb_half(line: &RunLine, sec: &Section) -> f64 {
    if line.stands() {
        return 0.0;
    }
    let h = line.plan_length();
    sec.depth / 2.0 * (line.length() / h)
}

/// The centre line's height at a point of the justify line.
pub fn centre_height(z: f64, justify: Justify, half: f64) -> f64 {
    match justify {
        Justify::Top => z - half,
        Justify::Centre => z,
        Justify::Bottom => z + half,
    }
}

/// A run's geometry, where its type and level are the model's.
pub fn run_geom(pr: &Project, e: &Value) -> Option<RunGeom> {
    let line = run_line(e)?;
    let section = section(pr, e)?;
    let elevation = level_of_element(pr, e, "level").map(|l| self::elevation(pr, l)).unwrap_or(0.0);
    Some(run_geom_of(line, section, elevation))
}

impl RunGeom {
    /// The way the run goes (a unit vector along its centre line) and the way its section's
    /// width lies (a unit vector across it, level: to the left of the line in plan, or east for
    /// one that stands); its depth lies along the first crossed with the second. As IFC writes a
    /// run: an extrusion along the first, its profile's x the second.
    pub fn frame(&self) -> ([f64; 3], [f64; 3]) {
        let a = self.axis[0];
        let b = self.axis[1];
        let d = [b[0] - a[0], b[1] - a[1], b[2] - a[2]];
        let len = (d[0] * d[0] + d[1] * d[1] + d[2] * d[2]).sqrt();
        let along = if len > 0.0 { [d[0] / len, d[1] / len, d[2] / len] } else { [0.0, 0.0, 1.0] };
        let h = (d[0] * d[0] + d[1] * d[1]).sqrt();
        let across = if self.stands || h == 0.0 { [1.0, 0.0, 0.0] } else { [-d[1] / h, d[0] / h, 0.0] };
        (along, across)
    }
    /// The centre line's start, its height over the run's level.
    pub fn start_over_level(&self) -> [f64; 3] {
        let a = self.axis[0];
        [a[0], a[1], a[2] - self.elevation]
    }
}

pub fn run_geom_of(line: RunLine, section: Section, elevation: f64) -> RunGeom {
    let half = plumb_half(&line, &section);
    let z0 = centre_height(elevation + line.offset, line.justify, half);
    let z1 = centre_height(elevation + line.end_offset, line.justify, half);
    let axis = [[line.start[0], line.start[1], z0], [line.end[0], line.end[1], z1]];
    let length = line.length();
    let stands = line.stands();
    RunGeom { line, section, elevation, axis, length, half, stands }
}

/// A column, a structural column or an isolated footing: where it stands and how high.
#[derive(Clone, Debug, PartialEq)]
pub struct ColumnGeom {
    pub at: [f64; 2],
    /// Degrees its width runs at, counter-clockwise from east.
    pub angle: f64,
    /// Absolute heights of its base and its top.
    pub base: f64,
    pub top: f64,
    pub section: Section,
}

impl ColumnGeom {
    pub fn height(&self) -> f64 {
        self.top - self.base
    }
}

/// The height a column has: from its base up to its top level, else to its own `height` over
/// its base (top less base, as the original works it out).
pub fn column_height(pr: &Project, e: &Value) -> Option<f64> {
    let (base, top) = column_span(pr, e)?;
    Some(top - base)
}

/// A column's top level, where it has one that is a level.
pub fn top_level_of(pr: &Project, e: &Value) -> Option<u64> {
    match e.get("top_level") {
        Some(Value::Str(_)) => level_of_element(pr, e, "top_level"),
        _ => None,
    }
}

/// A column's base and top, absolute.
pub fn column_span(pr: &Project, e: &Value) -> Option<(f64, f64)> {
    let level = level_of_element(pr, e, "level")?;
    let base = elevation(pr, level) + f(e, "base_offset").unwrap_or(0.0);
    let top = match top_level_of(pr, e) {
        Some(t) => elevation(pr, t),
        None => base + f(e, "height").unwrap_or(0.0),
    };
    Some((base, top))
}

pub fn column_geom(pr: &Project, e: &Value) -> Option<ColumnGeom> {
    let at = pt(e, "at")?;
    let angle = f(e, "angle").unwrap_or(0.0);
    let (base, top) = column_span(pr, e)?;
    let section = section(pr, e)?;
    Some(ColumnGeom { at, angle, base, top, section })
}

/// The corners of a rectangular column's plan, counter-clockwise (its width along `angle`).
pub fn column_outline(g: &ColumnGeom) -> Vec<[f64; 2]> {
    let (s, c) = g.angle.to_radians().sin_cos();
    let hw = g.section.width / 2.0;
    let hd = g.section.depth / 2.0;
    [[-hw, -hd], [hw, -hd], [hw, hd], [-hw, hd]]
        .iter()
        .map(|p| [g.at[0] + p[0] * c - p[1] * s, g.at[1] + p[0] * s + p[1] * c])
        .collect()
}
//! Reading the members' parameters as the original does: points of a chain, levels by name, id,
//! GUID or plan view, types by name or GUID.

use crate::commands::params::{get, mm_of};
use crate::json::Value;
use crate::project::Project;
use crate::structure::common::R;
use std::collections::HashMap;

/// A GUID as the original reads one: hyphenated (8-4-4-4-12 hex digits, any case), maybe in
/// braces, with whitespace round it; lowercase.
pub fn parse_guid(s: &str) -> Option<String> {
    let t = s.trim();
    let t = match t.strip_prefix('{') {
        Some(inner) => inner.strip_suffix('}')?,
        None => t,
    };
    let b = t.as_bytes();
    if b.len() != 36 {
        return None;
    }
    for (i, c) in b.iter().enumerate() {
        let dash = i == 8 || i == 13 || i == 18 || i == 23;
        if dash {
            if *c != b'-' {
                return None;
            }
        } else if !c.is_ascii_hexdigit() {
            return None;
        }
    }
    Some(t.to_ascii_lowercase())
}

/// A GUID as a file holds it, lowercase; anything that isn't one as it is.
pub fn norm_ref(s: &str) -> String {
    parse_guid(s).unwrap_or_else(|| s.to_string())
}

/// The model's elements by GUID (as the file holds them, any case).
pub fn guid_index(pr: &Project) -> HashMap<String, u64> {
    let mut m = HashMap::with_capacity(pr.elements.len());
    for (id, e) in &pr.elements {
        if let Some(g) = e.get("guid").and_then(|g| g.as_str()) {
            m.entry(norm_ref(g)).or_insert(*id);
        }
    }
    m
}

/// An element by its GUID, any case, in braces or not.
pub fn element_by_guid(pr: &Project, g: &str) -> Option<u64> {
    let want = parse_guid(g)?;
    if let Some(id) = pr.find_guid(&want) {
        return Some(id);
    }
    pr.elements
        .iter()
        .find(|(_, e)| e.get("guid").and_then(|x| x.as_str()).map(norm_ref).as_deref() == Some(want.as_str()))
        .map(|(id, _)| *id)
}

/// The library entry with this GUID, any case.
pub fn lib_by_guid(pr: &Project, g: &str) -> Option<u64> {
    let want = parse_guid(g)?;
    if let Some(id) = pr.lib_find_guid(&want) {
        return Some(id);
    }
    pr.library
        .iter()
        .find(|(_, e)| e.get("guid").and_then(|x| x.as_str()).map(norm_ref).as_deref() == Some(want.as_str()))
        .map(|(id, _)| *id)
}

// ---------------------------------------------------------------- levels

fn elevation(pr: &Project, id: u64) -> f64 {
    pr.el(id).and_then(|e| e.get("elevation")).and_then(|x| x.as_f64()).unwrap_or(0.0)
}

fn name_of(pr: &Project, id: u64) -> String {
    pr.el(id).and_then(|e| e.get("name")).and_then(|x| x.as_str()).unwrap_or("").to_string()
}

/// The levels from the lowest up, ties by id.
pub fn levels(pr: &Project) -> Vec<u64> {
    let mut v: Vec<(f64, u64)> = pr.ids_of("level").into_iter().map(|id| (elevation(pr, id), id)).collect();
    v.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal).then(a.1.cmp(&b.1)));
    v.into_iter().map(|(_, id)| id).collect()
}

/// The lowest level, where a member goes without one.
pub fn default_level(pr: &Project, cmd: &str) -> R<u64> {
    levels(pr).first().copied().ok_or_else(|| format!("{}: the model has no levels", cmd))
}

/// The level a column on `level` goes up to: the lowest more than a millimetre above it.
pub fn level_above(pr: &Project, level: u64) -> Option<u64> {
    let e = elevation(pr, level);
    levels(pr).into_iter().find(|l| elevation(pr, *l) > e + 1.0)
}

/// The level of a level, or of a plan view.
fn level_of(pr: &Project, id: u64) -> Option<u64> {
    match pr.category(id)? {
        "level" => Some(id),
        "planview" => {
            let g = pr.el(id)?.get("level")?.as_str()?.to_string();
            let l = element_by_guid(pr, &g)?;
            if pr.category(l) == Some("level") {
                Some(l)
            } else {
                None
            }
        }
        _ => None,
    }
}

/// An id the way the original reads one in a number: a whole number, not negative.
fn id_of_num(x: f64) -> Option<u64> {
    if x.is_finite() && x >= 0.0 && x.fract() == 0.0 && x < 18446744073709551616.0 {
        Some(x as u64)
    } else {
        None
    }
}

/// A level given by name, id or GUID, or a plan view (its level).
pub fn level_ref(pr: &Project, cmd: &str, key: &str, v: &Value) -> R<u64> {
    let not = || format!("{}: `{}`: {} is not a level or a plan view", cmd, key, v.to_compact());
    match v {
        Value::Num(n) => {
            let id = id_of_num(n.as_f64()).ok_or_else(not)?;
            level_of(pr, id).ok_or_else(not)
        }
        Value::Str(s) => {
            let t = s.trim();
            if !t.is_empty() && t.bytes().all(|b| b.is_ascii_digit()) {
                if let Ok(id) = t.parse::<u64>() {
                    return level_of(pr, id).ok_or_else(not);
                }
            }
            if parse_guid(s).is_some() {
                if let Some(id) = element_by_guid(pr, s) {
                    return level_of(pr, id).ok_or_else(not);
                }
            }
            let ls = levels(pr);
            for id in &ls {
                if name_of(pr, *id) == *s {
                    return Ok(*id);
                }
            }
            for id in pr.ids_of("planview") {
                if name_of(pr, id) == *s {
                    if let Some(l) = level_of(pr, id) {
                        return Ok(l);
                    }
                }
            }
            let names: Vec<String> = ls.iter().map(|l| name_of(pr, *l)).collect();
            Err(format!("{}: no level or plan view named `{}` (the levels are: {})", cmd, s, names.join(", ")))
        }
        _ => Err(not()),
    }
}

/// The `level` of a command: the one given, else the lowest.
pub fn level_param(pr: &Project, cmd: &str, p: &Value) -> R<u64> {
    match get(p, "level") {
        Some(v) => level_ref(pr, cmd, "level", v),
        None => default_level(pr, cmd),
    }
}

// ---------------------------------------------------------------- points

/// A point [x, y] in mm within the model's reach.
pub fn point_of(v: &Value) -> Option<[f64; 2]> {
    let a = v.as_arr()?;
    if a.len() != 2 {
        return None;
    }
    Some([mm_of(&a[0])?, mm_of(&a[1])?])
}

/// `points` of a chain: a list of at least two points.
pub fn chain_points(p: &Value, cmd: &str) -> R<Vec<[f64; 2]>> {
    let a = match get(p, "points").and_then(|v| v.as_arr()) {
        Some(a) => a,
        None => return Err(format!("{}: `points` [[x, y], …] is required", cmd)),
    };
    let mut pts = Vec::with_capacity(a.len());
    for x in a {
        match point_of(x) {
            Some(pt) => pts.push(pt),
            None => return Err(format!("{}: `points`: {} is not a point [x, y] in mm", cmd, x.to_compact())),
        }
    }
    if pts.len() < 2 {
        return Err(format!("{}: `points` needs at least 2 points", cmd));
    }
    Ok(pts)
}

// ---------------------------------------------------------------- types

/// The name a `type` parameter means: a library entry's name where it is that entry's GUID,
/// else the text itself.
pub fn type_name_param(pr: &Project, s: &str) -> String {
    if parse_guid(s).is_some() {
        if let Some(id) = lib_by_guid(pr, s) {
            if let Some(n) = pr.library.get(&id).and_then(|e| e.get("name")).and_then(|n| n.as_str()) {
                return n.to_string();
            }
        }
    }
    s.to_string()
}

//! `column`, `structural_column` and `footing`: a member standing at a point, of a type's plan.

use super::read::{level_above, level_param, level_ref, type_name_param};
use crate::commands::params::{get, opt_num, opt_text, req_point};
use crate::json::{Map, Value};
use crate::session::Session;
use crate::structure::common::{add_element, new_guid, type_guid, R};

/// A column's height when it goes up to no level.
pub const DEFAULT_HEIGHT: f64 = 3000.0;

/// A footing's thickness unless told.
pub const DEFAULT_THICKNESS: f64 = 400.0;

/// A column, a structural column or a footing as the file holds it.
pub fn column_json(
    cat: &str,
    type_ref: &str,
    level_guid: &str,
    at: [f64; 2],
    angle: f64,
    top_level: Option<&str>,
    height: f64,
    base_offset: f64,
) -> Value {
    let mut m = Map::new();
    m.insert("guid", Value::s(&new_guid()));
    m.insert("category", Value::s(cat));
    m.insert("type", Value::s(type_ref));
    m.insert("level", Value::s(level_guid));
    m.insert("at", Value::from(at));
    m.insert("angle", Value::f(angle));
    m.insert("top_level", top_level.map(Value::s).unwrap_or(Value::Null));
    m.insert("height", Value::f(height));
    m.insert("base_offset", Value::f(base_offset));
    Value::Obj(m)
}

fn type_param(s: &Session, cid: &str, cat: &str, p: &Value) -> R<String> {
    match opt_text(p, cid, "type")? {
        Some(t) => Ok(type_name_param(&s.project, &t)),
        None => match crate::structure::types::default_type(&s.project, cat) {
            Some(t) => Ok(t),
            None => Err(format!("{}: the model has no types for this", cid)),
        },
    }
}

/// `column` and `structural_column`.
pub fn column(s: &mut Session, cid: &str, cat: &str, p: &Value) -> R<Value> {
    let at = req_point(p, cid, "at")?;
    let level = level_param(&s.project, cid, p)?;
    let type_name = type_param(s, cid, cat, p)?;
    let angle = opt_num(p, cid, "angle")?.unwrap_or(0.0);
    let height = opt_num(p, cid, "height")?;
    let top_level = match get(p, "top_level") {
        Some(v) => Some(level_ref(&s.project, cid, "top_level", v)?),
        None => None,
    };
    let base_offset = opt_num(p, cid, "base_offset")?.unwrap_or(0.0);
    let pr = &s.project;
    // up to the level given, else (without a height) the next one up
    let top = match (top_level, height) {
        (Some(t), _) => Some(t),
        (None, Some(_)) => None,
        (None, None) => level_above(pr, level),
    };
    let level_guid = pr.guid_of(level).unwrap_or_default();
    let top_guid = top.and_then(|t| pr.guid_of(t));
    let type_ref = type_guid(pr, cat, &type_name).unwrap_or(type_name);
    let e = column_json(
        cat,
        &type_ref,
        &level_guid,
        at,
        angle,
        top_guid.as_deref(),
        height.unwrap_or(DEFAULT_HEIGHT),
        base_offset,
    );
    let id = add_element(s, e);
    Ok(crate::jobj! {"id" => id})
}

/// `footing`: an isolated pad, `thickness` thick, its top `offset` over its level.
pub fn footing(s: &mut Session, cid: &str, p: &Value) -> R<Value> {
    let cat = "footing";
    let at = req_point(p, cid, "at")?;
    let level = level_param(&s.project, cid, p)?;
    let type_name = type_param(s, cid, cat, p)?;
    let angle = opt_num(p, cid, "angle")?.unwrap_or(0.0);
    let thickness = opt_num(p, cid, "thickness")?.unwrap_or(DEFAULT_THICKNESS);
    if thickness <= 0.0 {
        return Err(format!("{}: `thickness` must be above zero, got {}", cid, thickness));
    }
    let offset = opt_num(p, cid, "offset")?.unwrap_or(0.0);
    let pr = &s.project;
    let level_guid = pr.guid_of(level).unwrap_or_default();
    let type_ref = type_guid(pr, cat, &type_name).unwrap_or(type_name);
    let e = column_json(cat, &type_ref, &level_guid, at, angle, None, thickness, offset - thickness);
    let id = add_element(s, e);
    Ok(crate::jobj! {"id" => id})
}
//! The model's rules for runs and columns, as the original checks them after every command and
//! when it opens a file: element by element in id order, each one's rules in turn.

use super::geom::{may_stand, run_line, MAX_SLOPE, TOL};
use super::read::{guid_index, lib_by_guid, norm_ref, parse_guid};
use crate::commands::params::MAX_MM;
use crate::json::Value;
use crate::project::Project;
use crate::structure::common::{is_run, type_kind, types_of, COLUMN_CATS, R};
use std::collections::HashMap;

struct Ctx<'a> {
    pr: &'a Project,
    guids: HashMap<String, u64>,
}

pub fn check(pr: &Project) -> R<()> {
    let mut ctx: Option<Ctx> = None;
    for (id, e) in &pr.elements {
        let cat = match e.get("category").and_then(|c| c.as_str()) {
            Some(c) => c,
            None => continue,
        };
        let run = is_run(cat);
        if !run && !COLUMN_CATS.contains(&cat) {
            continue;
        }
        let c = ctx.get_or_insert_with(|| Ctx { pr, guids: guid_index(pr) });
        if run {
            check_run(c, *id, cat, e)?;
        } else {
            check_column(c, *id, cat, e)?;
        }
    }
    Ok(())
}

/// The type an element names must be one of its category's.
fn check_type(c: &Ctx, id: u64, cat: &str, e: &Value) -> R<()> {
    let pr = c.pr;
    let types = types_of(pr, cat);
    let raw = match e.get("type") {
        Some(Value::Str(s)) => s.clone(),
        Some(v) => v.to_compact(),
        None => String::new(),
    };
    // a GUID of one of the category's types stands for its name
    let mut shown = raw.clone();
    if parse_guid(&raw).is_some() {
        if let Some(lid) = lib_by_guid(pr, &raw) {
            let le = &pr.library[&lid];
            if le.get("kind").and_then(|k| k.as_str()) == Some(type_kind(cat).as_str()) {
                if let Some(n) = le.get("name").and_then(|n| n.as_str()) {
                    shown = n.to_string();
                }
            }
        }
    }
    if types.map(|t| t.contains(&shown)).unwrap_or(false) {
        return Ok(());
    }
    let mut names: Vec<&String> = types.map(|t| t.keys().collect()).unwrap_or_default();
    names.sort();
    let names: Vec<&str> = names.iter().map(|s| s.as_str()).collect();
    Err(format!("{} {}: type `{}` doesn't exist (there are: {})", cat, id, shown, names.join(", ")))
}

/// A reference to a level (`level`, `top_level`) must be one.
fn check_level_ref(c: &Ctx, id: u64, cat: &str, v: Option<&Value>) -> R<()> {
    let shown = match v {
        Some(Value::Str(s)) => match c.guids.get(&norm_ref(s)) {
            Some(target) => {
                if c.pr.category(*target) == Some("level") {
                    return Ok(());
                }
                target.to_string()
            }
            None => s.clone(),
        },
        Some(v) => v.to_compact(),
        None => "null".to_string(),
    };
    Err(format!("{} {}: level {} doesn't exist", cat, id, shown))
}

/// A number the model can hold: within 1000 km.
fn usable(cat: &str, id: u64, what: &str, x: Option<f64>) -> R<()> {
    match x {
        Some(v) if !(v.is_finite() && v.abs() <= MAX_MM) => {
            Err(format!("{} {} {}: {} is not a usable number", cat, id, what, v))
        }
        _ => Ok(()),
    }
}

fn num(e: &Value, k: &str) -> Option<f64> {
    e.get(k).and_then(|x| x.as_f64())
}

fn coord(e: &Value, k: &str, i: usize) -> Option<f64> {
    e.get(k).and_then(|p| p.as_arr()).and_then(|a| a.get(i)).and_then(|x| x.as_f64())
}

fn check_run(c: &Ctx, id: u64, cat: &str, e: &Value) -> R<()> {
    check_type(c, id, cat, e)?;
    check_level_ref(c, id, cat, e.get("level"))?;
    usable(cat, id, "start x", coord(e, "start", 0))?;
    usable(cat, id, "start y", coord(e, "start", 1))?;
    usable(cat, id, "end x", coord(e, "end", 0))?;
    usable(cat, id, "end y", coord(e, "end", 1))?;
    usable(cat, id, "offset", num(e, "offset"))?;
    usable(cat, id, "end_offset", num(e, "end_offset"))?;
    if let Some(sys) = e.get("system").and_then(|s| s.as_str()) {
        if sys.chars().count() > 256 {
            return Err(format!("{} {}: system is longer than 256 characters", cat, id));
        }
    }
    let line = match run_line(e) {
        Some(l) => l,
        None => return Ok(()),
    };
    let len = line.length();
    if len <= TOL {
        return Err(format!("{} {}: too short ({} mm)", cat, id, len));
    }
    if !may_stand(cat) {
        if line.stands() {
            return Err(format!(
                "{} {}: its ends are one over the other; a {} runs along, and what stands is a column",
                cat, id, cat
            ));
        }
        let slope = line.slope_degrees();
        if slope > MAX_SLOPE {
            return Err(format!(
                "{} {}: it slopes {:.1}°, more than the {}° a {} may; what stands is a column",
                cat, id, slope, MAX_SLOPE, cat
            ));
        }
    }
    Ok(())
}

fn check_column(c: &Ctx, id: u64, cat: &str, e: &Value) -> R<()> {
    check_type(c, id, cat, e)?;
    check_level_ref(c, id, cat, e.get("level"))?;
    usable(cat, id, "x", coord(e, "at", 0))?;
    usable(cat, id, "y", coord(e, "at", 1))?;
    usable(cat, id, "angle", num(e, "angle"))?;
    usable(cat, id, "base_offset", num(e, "base_offset"))?;
    let connected = matches!(e.get("top_level"), Some(v) if !v.is_null());
    let height = num(e, "height").unwrap_or(0.0);
    if connected {
        check_level_ref(c, id, cat, e.get("top_level"))?;
    } else {
        usable(cat, id, "height", Some(height))?;
        if height <= 0.0 {
            return Err(format!("{} {} height must be above zero, got {}", cat, id, height));
        }
    }
    let pr = c.pr;
    let elev = |key: &str| -> f64 {
        e.get(key)
            .and_then(|g| g.as_str())
            .and_then(|g| c.guids.get(&norm_ref(g)))
            .and_then(|l| pr.el(*l))
            .and_then(|l| l.get("elevation"))
            .and_then(|x| x.as_f64())
            .unwrap_or(0.0)
    };
    let base = elev("level") + num(e, "base_offset").unwrap_or(0.0);
    let top = if connected { elev("top_level") } else { base + height };
    if top <= base + TOL {
        return Err(format!("{} {}: its top must be above its base", cat, id));
    }
    Ok(())
}
//! What `elements` shows of a run or a column besides its fields: its type by name and GUID, its
//! section, a run's centre line and length, a column's height.

use super::geom::{column_height, run_geom, section, type_guid, type_name};
use crate::json::Value;
use crate::project::Project;
use crate::structure::common::is_run;

/// Rounded to the hundredth of a millimetre, as `elements` shows a run's line.
pub fn round2(x: f64) -> f64 {
    (x * 100.0).round() / 100.0
}

pub fn element_view(pr: &Project, _id: u64, x: &mut Value) {
    let e = x.clone();
    let cat = e.get("category").and_then(|c| c.as_str()).unwrap_or("").to_string();
    let name = type_name(pr, &e);
    let guid = type_guid(pr, &e);
    let sec = section(pr, &e);
    if let Some(n) = &name {
        x.set("type", Value::s(n));
    }
    if let Some(g) = &guid {
        x.set("type_guid", Value::s(g));
    }
    if let Some(s) = &sec {
        x.set("width", Value::f(s.width));
        x.set("depth", Value::f(s.depth));
        x.set("round", Value::Bool(s.round));
    }
    if is_run(&cat) {
        if let Some(g) = run_geom(pr, &e) {
            let axis: Vec<Value> = g
                .axis
                .iter()
                .map(|p| Value::Arr(p.iter().map(|c| Value::f(round2(*c))).collect()))
                .collect();
            x.set("axis", Value::Arr(axis));
            x.set("length", Value::f(round2(g.length)));
        }
    } else {
        if let Some(h) = column_height(pr, &e) {
            x.set("height", Value::f(h));
        }
        if cat == "column" || cat == "structuralcolumn" {
            if x.get("room_bounding").is_none() {
                x.set("room_bounding", Value::Bool(true));
            }
        }
    }
}

//! Reading a command's parameters, with the errors the commands give.

use crate::json::Value;

pub type R<T> = Result<T, String>;

pub fn get<'a>(p: &'a Value, key: &str) -> Option<&'a Value> {
    match p.get(key) {
        Some(Value::Null) | None => None,
        Some(v) => Some(v),
    }
}

pub fn has(p: &Value, key: &str) -> bool {
    get(p, key).is_some()
}

/// Present in the object, even as null.
pub fn given(p: &Value, key: &str) -> bool {
    p.get(key).is_some()
}

pub fn num_of(v: &Value) -> Option<f64> {
    match v {
        Value::Num(n) => Some(n.as_f64()),
        _ => None,
    }
}

/// The largest length a command takes, in mm (1000 km).
pub const MAX_MM: f64 = 1e9;

/// A length in mm, within the model's reach.
pub fn mm_of(v: &Value) -> Option<f64> {
    let x = num_of(v)?;
    if x.is_finite() && x.abs() <= MAX_MM {
        Some(x)
    } else {
        None
    }
}

pub fn req_num(p: &Value, cmd: &str, key: &str) -> R<f64> {
    match get(p, key) {
        None => Err(format!("{}: `{}` in mm is required", cmd, key)),
        Some(v) => mm_of(v).ok_or_else(|| format!("{}: `{}` must be a number in mm, got {}", cmd, key, v.to_compact())),
    }
}

pub fn opt_num(p: &Value, cmd: &str, key: &str) -> R<Option<f64>> {
    match get(p, key) {
        None => Ok(None),
        Some(v) => mm_of(v)
            .map(Some)
            .ok_or_else(|| format!("{}: `{}` must be a number in mm, got {}", cmd, key, v.to_compact())),
    }
}

/// A number in some unit other than mm (degrees, percent…).
pub fn opt_num_unit(p: &Value, cmd: &str, key: &str, unit: &str) -> R<Option<f64>> {
    match get(p, key) {
        None => Ok(None),
        Some(v) => num_of(v)
            .map(Some)
            .ok_or_else(|| format!("{}: `{}` must be a number{}, got {}", cmd, key, unit, v.to_compact())),
    }
}

pub fn opt_text(p: &Value, cmd: &str, key: &str) -> R<Option<String>> {
    match get(p, key) {
        None => Ok(None),
        Some(Value::Str(s)) if s.chars().count() <= 256 => Ok(Some(s.clone())),
        Some(v) => Err(format!("{}: `{}` must be text of at most 256 characters, got {}", cmd, key, v.to_compact())),
    }
}

pub fn opt_bool(p: &Value, cmd: &str, key: &str) -> R<Option<bool>> {
    match get(p, key) {
        None => Ok(None),
        Some(Value::Bool(b)) => Ok(Some(*b)),
        Some(v) => Err(format!("{}: `{}` must be true or false, got {}", cmd, key, v.to_compact())),
    }
}

pub fn point_of(v: &Value) -> Option<[f64; 2]> {
    let a = v.as_arr()?;
    if a.len() != 2 {
        return None;
    }
    Some([mm_of(&a[0])?, mm_of(&a[1])?])
}

pub fn point3_of(v: &Value) -> Option<[f64; 3]> {
    let a = v.as_arr()?;
    if a.len() != 3 {
        return None;
    }
    Some([mm_of(&a[0])?, mm_of(&a[1])?, mm_of(&a[2])?])
}

pub fn req_point(p: &Value, cmd: &str, key: &str) -> R<[f64; 2]> {
    match get(p, key) {
        None => Err(format!("{}: `{}` [x, y] is required", cmd, key)),
        Some(v) => point_of(v).ok_or_else(|| format!("{}: `{}` must be a point [x, y] in mm, got {}", cmd, key, v.to_compact())),
    }
}

pub fn opt_point(p: &Value, cmd: &str, key: &str) -> R<Option<[f64; 2]>> {
    match get(p, key) {
        None => Ok(None),
        Some(v) => point_of(v)
            .map(Some)
            .ok_or_else(|| format!("{}: `{}` must be a point [x, y] in mm, got {}", cmd, key, v.to_compact())),
    }
}

/// A list of points; anything but a list of points reads as missing.
pub fn points_of(v: &Value) -> Option<Vec<[f64; 2]>> {
    let a = v.as_arr()?;
    a.iter().map(point_of).collect()
}

pub fn req_points(p: &Value, cmd: &str, key: &str) -> R<Vec<[f64; 2]>> {
    match get(p, key).and_then(points_of) {
        None => Err(format!("{}: `{}` [[x, y], …] is required", cmd, key)),
        Some(v) => Ok(v),
    }
}

pub fn opt_points(p: &Value, cmd: &str, key: &str) -> R<Option<Vec<[f64; 2]>>> {
    match get(p, key) {
        None => Ok(None),
        Some(v) => match points_of(v) {
            Some(pts) => Ok(Some(pts)),
            None => Err(format!("{}: `{}` [[x, y], …] is required", cmd, key)),
        },
    }
}

/// An element id: a number, or a GUID or an id in a string.
pub fn id_of(v: &Value) -> Option<u64> {
    match v {
        Value::Num(n) => {
            let f = n.as_f64();
            if f >= 0.0 && f.fract() == 0.0 {
                Some(f as u64)
            } else {
                None
            }
        }
        Value::Str(s) => s.trim().parse::<u64>().ok(),
        _ => None,
    }
}

//! Where a run and a column are: a run's centre line and section, a column's base, top and plan.
//! What IFC export, schedules, plans and rebar ask of a member, from the element as the file holds it.

use super::read::{element_by_guid, lib_by_guid, parse_guid};
use crate::json::Value;
use crate::project::Project;
use crate::structure::common::{type_kind, type_of, types_of};

/// Within this (mm) in plan a run's ends are one over the other: it stands.
pub const TOL: f64 = 1.0;

/// The steepest a beam or a strip footing may slope, degrees.
pub const MAX_SLOPE: f64 = 75.0;

/// A member's section, from its type: `width` across by `depth` deep, or round (`width` across).
#[derive(Clone, Debug, PartialEq)]
pub struct Section {
    pub width: f64,
    pub depth: f64,
    pub round: bool,
    /// The material's GUID (a run type's; a column type has none).
    pub material: Option<String>,
}

/// The line of a run's section its heights are given at.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Justify {
    Top,
    Centre,
    Bottom,
}

impl Justify {
    pub fn parse(s: &str) -> Option<Justify> {
        match s.to_lowercase().as_str() {
            "top" => Some(Justify::Top),
            "centre" | "center" => Some(Justify::Centre),
            "bottom" => Some(Justify::Bottom),
            _ => None,
        }
    }
    pub fn name(self) -> &'static str {
        match self {
            Justify::Top => "top",
            Justify::Centre => "centre",
            Justify::Bottom => "bottom",
        }
    }
    /// IFC's cardinal point of the line: top 8, middle 5, bottom 2.
    pub fn cardinal_point(self) -> u32 {
        match self {
            Justify::Top => 8,
            Justify::Centre => 5,
            Justify::Bottom => 2,
        }
    }
}

/// The justification a category's runs take unless told: a beam's and a strip footing's top,
/// any other's middle.
pub fn default_justify(cat: &str) -> Justify {
    match cat {
        "beam" | "stripfooting" => Justify::Top,
        _ => Justify::Centre,
    }
}

/// Whether a run of this category may stand upright (a riser): all but beams and strip footings.
pub fn may_stand(cat: &str) -> bool {
    !matches!(cat, "beam" | "stripfooting")
}

/// The type an element names (its `type`: a GUID of the category's library kind, or a name):
/// its name, if the project has a type of that name.
pub fn type_name(pr: &Project, e: &Value) -> Option<String> {
    let cat = e.get("category")?.as_str()?;
    let t = e.get("type")?.as_str()?;
    let types = types_of(pr, cat)?;
    if parse_guid(t).is_some() {
        if let Some(id) = lib_by_guid(pr, t) {
            let le = pr.library.get(&id)?;
            if le.get("kind").and_then(|k| k.as_str()) == Some(type_kind(cat).as_str()) {
                let n = le.get("name")?.as_str()?;
                return if types.contains(n) { Some(n.to_string()) } else { None };
            }
        }
    }
    if types.contains(t) {
        Some(t.to_string())
    } else {
        None
    }
}

/// The GUID of the type an element is of.
pub fn type_guid(pr: &Project, e: &Value) -> Option<String> {
    let cat = e.get("category")?.as_str()?;
    let name = type_name(pr, e)?;
    pr.lib_guid(&type_kind(cat), &name)
}

/// A type's section, as `types` holds it.
pub fn section_of_type(t: &Value) -> Section {
    let width = t.get("width").and_then(|x| x.as_f64()).unwrap_or(0.0);
    let round = t.get("round").and_then(|x| x.as_bool()).unwrap_or(false);
    let depth = t.get("depth").and_then(|x| x.as_f64()).unwrap_or(width);
    let material = t.get("material").and_then(|x| x.as_str()).map(|s| s.to_string());
    Section { width, depth, round, material }
}

/// The section of a run or a column, from its type.
pub fn section(pr: &Project, e: &Value) -> Option<Section> {
    let cat = e.get("category")?.as_str()?;
    let name = type_name(pr, e)?;
    Some(section_of_type(type_of(pr, cat, &name)?))
}

/// The level an element stands on (its `level`), when it is one.
pub fn level_of_element(pr: &Project, e: &Value, key: &str) -> Option<u64> {
    let g = e.get(key)?.as_str()?;
    let id = element_by_guid(pr, g)?;
    if pr.category(id) == Some("level") {
        Some(id)
    } else {
        None
    }
}

pub fn elevation(pr: &Project, level: u64) -> f64 {
    pr.el(level).and_then(|e| e.get("elevation")).and_then(|x| x.as_f64()).unwrap_or(0.0)
}

fn f(e: &Value, k: &str) -> Option<f64> {
    e.get(k).and_then(|x| x.as_f64())
}

fn pt(e: &Value, k: &str) -> Option<[f64; 2]> {
    let a = e.get(k)?.as_arr()?;
    Some([a.first()?.as_f64()?, a.get(1)?.as_f64()?])
}

/// A run's line where its heights are given: plan ends and their heights over its level.
#[derive(Clone, Debug, PartialEq)]
pub struct RunLine {
    pub start: [f64; 2],
    pub end: [f64; 2],
    /// `offset` and `end_offset` (the same when it has none), mm over the level.
    pub offset: f64,
    pub end_offset: f64,
    pub justify: Justify,
}

impl RunLine {
    /// Its length in plan.
    pub fn plan_length(&self) -> f64 {
        let dx = self.end[0] - self.start[0];
        let dy = self.end[1] - self.start[1];
        (dx * dx + dy * dy).sqrt()
    }
    /// How far its end is over its start.
    pub fn rise(&self) -> f64 {
        self.end_offset - self.offset
    }
    /// Its length along the slope.
    pub fn length(&self) -> f64 {
        let dx = self.end[0] - self.start[0];
        let dy = self.end[1] - self.start[1];
        let dz = self.rise();
        (dx * dx + dy * dy + dz * dz).sqrt()
    }
    /// Its ends are one over the other (within `TOL` in plan).
    pub fn stands(&self) -> bool {
        self.plan_length() <= TOL
    }
    /// Its slope from the horizontal, degrees (90 when it stands).
    pub fn slope_degrees(&self) -> f64 {
        self.rise().abs().atan2(self.plan_length()).to_degrees()
    }
}

/// The line a run's heights are given at, from the element.
pub fn run_line(e: &Value) -> Option<RunLine> {
    let start = pt(e, "start")?;
    let end = pt(e, "end")?;
    let offset = f(e, "offset").unwrap_or(0.0);
    let end_offset = f(e, "end_offset").unwrap_or(offset);
    let cat = e.get("category").and_then(|c| c.as_str()).unwrap_or("");
    let justify = e
        .get("justify")
        .and_then(|j| j.as_str())
        .and_then(Justify::parse)
        .unwrap_or_else(|| default_justify(cat));
    Some(RunLine { start, end, offset, end_offset, justify })
}

/// A run in the model: its centre line (absolute heights), its section, its length.
#[derive(Clone, Debug, PartialEq)]
pub struct RunGeom {
    pub line: RunLine,
    pub section: Section,
    /// The elevation of its level.
    pub elevation: f64,
    /// The centre line's ends, [x, y, z] with z absolute (the level's elevation added).
    pub axis: [[f64; 3]; 2],
    /// Along the slope, mm.
    pub length: f64,
    /// Half its section's depth measured plumb (depth / 2 / cos θ; 0 when it stands).
    pub half: f64,
    pub stands: bool,
}

/// How far below (or above) the justify line the centre line is, plumb: half the depth over the
/// cosine of the slope, or none for a run that stands.
pub fn plumb_half(line: &RunLine, sec: &Section) -> f64 {
    if line.stands() {
        return 0.0;
    }
    let h = line.plan_length();
    sec.depth / 2.0 * (line.length() / h)
}

/// The centre line's height at a point of the justify line.
pub fn centre_height(z: f64, justify: Justify, half: f64) -> f64 {
    match justify {
        Justify::Top => z - half,
        Justify::Centre => z,
        Justify::Bottom => z + half,
    }
}

/// A run's geometry, where its type and level are the model's.
pub fn run_geom(pr: &Project, e: &Value) -> Option<RunGeom> {
    let line = run_line(e)?;
    let section = section(pr, e)?;
    let elevation = level_of_element(pr, e, "level").map(|l| self::elevation(pr, l)).unwrap_or(0.0);
    Some(run_geom_of(line, section, elevation))
}

impl RunGeom {
    /// The way the run goes (a unit vector along its centre line) and the way its section's
    /// width lies (a unit vector across it, level: to the left of the line in plan, or east for
    /// one that stands); its depth lies along the first crossed with the second. As IFC writes a
    /// run: an extrusion along the first, its profile's x the second.
    pub fn frame(&self) -> ([f64; 3], [f64; 3]) {
        let a = self.axis[0];
        let b = self.axis[1];
        let d = [b[0] - a[0], b[1] - a[1], b[2] - a[2]];
        let len = (d[0] * d[0] + d[1] * d[1] + d[2] * d[2]).sqrt();
        let along = if len > 0.0 { [d[0] / len, d[1] / len, d[2] / len] } else { [0.0, 0.0, 1.0] };
        let h = (d[0] * d[0] + d[1] * d[1]).sqrt();
        let across = if self.stands || h == 0.0 { [1.0, 0.0, 0.0] } else { [-d[1] / h, d[0] / h, 0.0] };
        (along, across)
    }
    /// The centre line's start, its height over the run's level.
    pub fn start_over_level(&self) -> [f64; 3] {
        let a = self.axis[0];
        [a[0], a[1], a[2] - self.elevation]
    }
}

pub fn run_geom_of(line: RunLine, section: Section, elevation: f64) -> RunGeom {
    let half = plumb_half(&line, &section);
    let z0 = centre_height(elevation + line.offset, line.justify, half);
    let z1 = centre_height(elevation + line.end_offset, line.justify, half);
    let axis = [[line.start[0], line.start[1], z0], [line.end[0], line.end[1], z1]];
    let length = line.length();
    let stands = line.stands();
    RunGeom { line, section, elevation, axis, length, half, stands }
}

/// A column, a structural column or an isolated footing: where it stands and how high.
#[derive(Clone, Debug, PartialEq)]
pub struct ColumnGeom {
    pub at: [f64; 2],
    /// Degrees its width runs at, counter-clockwise from east.
    pub angle: f64,
    /// Absolute heights of its base and its top.
    pub base: f64,
    pub top: f64,
    pub section: Section,
}

impl ColumnGeom {
    pub fn height(&self) -> f64 {
        self.top - self.base
    }
}

/// The height a column has: from its base up to its top level, else to its own `height` over
/// its base (top less base, as the original works it out).
pub fn column_height(pr: &Project, e: &Value) -> Option<f64> {
    let (base, top) = column_span(pr, e)?;
    Some(top - base)
}

/// A column's top level, where it has one that is a level.
pub fn top_level_of(pr: &Project, e: &Value) -> Option<u64> {
    match e.get("top_level") {
        Some(Value::Str(_)) => level_of_element(pr, e, "top_level"),
        _ => None,
    }
}

/// A column's base and top, absolute.
pub fn column_span(pr: &Project, e: &Value) -> Option<(f64, f64)> {
    let level = level_of_element(pr, e, "level")?;
    let base = elevation(pr, level) + f(e, "base_offset").unwrap_or(0.0);
    let top = match top_level_of(pr, e) {
        Some(t) => elevation(pr, t),
        None => base + f(e, "height").unwrap_or(0.0),
    };
    Some((base, top))
}

pub fn column_geom(pr: &Project, e: &Value) -> Option<ColumnGeom> {
    let at = pt(e, "at")?;
    let angle = f(e, "angle").unwrap_or(0.0);
    let (base, top) = column_span(pr, e)?;
    let section = section(pr, e)?;
    Some(ColumnGeom { at, angle, base, top, section })
}

/// The corners of a rectangular column's plan, counter-clockwise (its width along `angle`).
pub fn column_outline(g: &ColumnGeom) -> Vec<[f64; 2]> {
    let (s, c) = g.angle.to_radians().sin_cos();
    let hw = g.section.width / 2.0;
    let hd = g.section.depth / 2.0;
    [[-hw, -hd], [hw, -hd], [hw, hd], [-hw, hd]]
        .iter()
        .map(|p| [g.at[0] + p[0] * c - p[1] * s, g.at[1] + p[0] * s + p[1] * c])
        .collect()
}
//! Reading the members' parameters as the original does: points of a chain, levels by name, id,
//! GUID or plan view, types by name or GUID.

use crate::commands::params::{get, mm_of};
use crate::json::Value;
use crate::project::Project;
use crate::structure::common::R;
use std::collections::HashMap;

/// A GUID as the original reads one: hyphenated (8-4-4-4-12 hex digits, any case), maybe in
/// braces, with whitespace round it; lowercase.
pub fn parse_guid(s: &str) -> Option<String> {
    let t = s.trim();
    let t = match t.strip_prefix('{') {
        Some(inner) => inner.strip_suffix('}')?,
        None => t,
    };
    let b = t.as_bytes();
    if b.len() != 36 {
        return None;
    }
    for (i, c) in b.iter().enumerate() {
        let dash = i == 8 || i == 13 || i == 18 || i == 23;
        if dash {
            if *c != b'-' {
                return None;
            }
        } else if !c.is_ascii_hexdigit() {
            return None;
        }
    }
    Some(t.to_ascii_lowercase())
}

/// A GUID as a file holds it, lowercase; anything that isn't one as it is.
pub fn norm_ref(s: &str) -> String {
    parse_guid(s).unwrap_or_else(|| s.to_string())
}

/// The model's elements by GUID (as the file holds them, any case).
pub fn guid_index(pr: &Project) -> HashMap<String, u64> {
    let mut m = HashMap::with_capacity(pr.elements.len());
    for (id, e) in &pr.elements {
        if let Some(g) = e.get("guid").and_then(|g| g.as_str()) {
            m.entry(norm_ref(g)).or_insert(*id);
        }
    }
    m
}

/// An element by its GUID, any case, in braces or not.
pub fn element_by_guid(pr: &Project, g: &str) -> Option<u64> {
    let want = parse_guid(g)?;
    if let Some(id) = pr.find_guid(&want) {
        return Some(id);
    }
    pr.elements
        .iter()
        .find(|(_, e)| e.get("guid").and_then(|x| x.as_str()).map(norm_ref).as_deref() == Some(want.as_str()))
        .map(|(id, _)| *id)
}

/// The library entry with this GUID, any case.
pub fn lib_by_guid(pr: &Project, g: &str) -> Option<u64> {
    let want = parse_guid(g)?;
    if let Some(id) = pr.lib_find_guid(&want) {
        return Some(id);
    }
    pr.library
        .iter()
        .find(|(_, e)| e.get("guid").and_then(|x| x.as_str()).map(norm_ref).as_deref() == Some(want.as_str()))
        .map(|(id, _)| *id)
}

// ---------------------------------------------------------------- levels

fn elevation(pr: &Project, id: u64) -> f64 {
    pr.el(id).and_then(|e| e.get("elevation")).and_then(|x| x.as_f64()).unwrap_or(0.0)
}

fn name_of(pr: &Project, id: u64) -> String {
    pr.el(id).and_then(|e| e.get("name")).and_then(|x| x.as_str()).unwrap_or("").to_string()
}

/// The levels from the lowest up, ties by id.
pub fn levels(pr: &Project) -> Vec<u64> {
    let mut v: Vec<(f64, u64)> = pr.ids_of("level").into_iter().map(|id| (elevation(pr, id), id)).collect();
    v.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal).then(a.1.cmp(&b.1)));
    v.into_iter().map(|(_, id)| id).collect()
}

/// The lowest level, where a member goes without one.
pub fn default_level(pr: &Project, cmd: &str) -> R<u64> {
    levels(pr).first().copied().ok_or_else(|| format!("{}: the model has no levels", cmd))
}

/// The level a column on `level` goes up to: the lowest more than a millimetre above it.
pub fn level_above(pr: &Project, level: u64) -> Option<u64> {
    let e = elevation(pr, level);
    levels(pr).into_iter().find(|l| elevation(pr, *l) > e + 1.0)
}

/// The level of a level, or of a plan view.
fn level_of(pr: &Project, id: u64) -> Option<u64> {
    match pr.category(id)? {
        "level" => Some(id),
        "planview" => {
            let g = pr.el(id)?.get("level")?.as_str()?.to_string();
            let l = element_by_guid(pr, &g)?;
            if pr.category(l) == Some("level") {
                Some(l)
            } else {
                None
            }
        }
        _ => None,
    }
}

/// An id the way the original reads one in a number: a whole number, not negative.
fn id_of_num(x: f64) -> Option<u64> {
    if x.is_finite() && x >= 0.0 && x.fract() == 0.0 && x < 18446744073709551616.0 {
        Some(x as u64)
    } else {
        None
    }
}

/// A level given by name, id or GUID, or a plan view (its level).
pub fn level_ref(pr: &Project, cmd: &str, key: &str, v: &Value) -> R<u64> {
    let not = || format!("{}: `{}`: {} is not a level or a plan view", cmd, key, v.to_compact());
    match v {
        Value::Num(n) => {
            let id = id_of_num(n.as_f64()).ok_or_else(not)?;
            level_of(pr, id).ok_or_else(not)
        }
        Value::Str(s) => {
            let t = s.trim();
            if !t.is_empty() && t.bytes().all(|b| b.is_ascii_digit()) {
                if let Ok(id) = t.parse::<u64>() {
                    return level_of(pr, id).ok_or_else(not);
                }
            }
            if parse_guid(s).is_some() {
                if let Some(id) = element_by_guid(pr, s) {
                    return level_of(pr, id).ok_or_else(not);
                }
            }
            let ls = levels(pr);
            for id in &ls {
                if name_of(pr, *id) == *s {
                    return Ok(*id);
                }
            }
            for id in pr.ids_of("planview") {
                if name_of(pr, id) == *s {
                    if let Some(l) = level_of(pr, id) {
                        return Ok(l);
                    }
                }
            }
            let names: Vec<String> = ls.iter().map(|l| name_of(pr, *l)).collect();
            Err(format!("{}: no level or plan view named `{}` (the levels are: {})", cmd, s, names.join(", ")))
        }
        _ => Err(not()),
    }
}

/// The `level` of a command: the one given, else the lowest.
pub fn level_param(pr: &Project, cmd: &str, p: &Value) -> R<u64> {
    match get(p, "level") {
        Some(v) => level_ref(pr, cmd, "level", v),
        None => default_level(pr, cmd),
    }
}

// ---------------------------------------------------------------- points

/// A point [x, y] in mm within the model's reach.
pub fn point_of(v: &Value) -> Option<[f64; 2]> {
    let a = v.as_arr()?;
    if a.len() != 2 {
        return None;
    }
    Some([mm_of(&a[0])?, mm_of(&a[1])?])
}

/// `points` of a chain: a list of at least two points.
pub fn chain_points(p: &Value, cmd: &str) -> R<Vec<[f64; 2]>> {
    let a = match get(p, "points").and_then(|v| v.as_arr()) {
        Some(a) => a,
        None => return Err(format!("{}: `points` [[x, y], …] is required", cmd)),
    };
    let mut pts = Vec::with_capacity(a.len());
    for x in a {
        match point_of(x) {
            Some(pt) => pts.push(pt),
            None => return Err(format!("{}: `points`: {} is not a point [x, y] in mm", cmd, x.to_compact())),
        }
    }
    if pts.len() < 2 {
        return Err(format!("{}: `points` needs at least 2 points", cmd));
    }
    Ok(pts)
}

// ---------------------------------------------------------------- types

/// The name a `type` parameter means: a library entry's name where it is that entry's GUID,
/// else the text itself.
pub fn type_name_param(pr: &Project, s: &str) -> String {
    if parse_guid(s).is_some() {
        if let Some(id) = lib_by_guid(pr, s) {
            if let Some(n) = pr.library.get(&id).and_then(|e| e.get("name")).and_then(|n| n.as_str()) {
                return n.to_string();
            }
        }
    }
    s.to_string()
}

//! `column`, `structural_column` and `footing`: a member standing at a point, of a type's plan.

use super::read::{level_above, level_param, level_ref, type_name_param};
use crate::commands::params::{get, opt_num, opt_text, req_point};
use crate::json::{Map, Value};
use crate::session::Session;
use crate::structure::common::{add_element, new_guid, type_guid, R};

/// A column's height when it goes up to no level.
pub const DEFAULT_HEIGHT: f64 = 3000.0;

/// A footing's thickness unless told.
pub const DEFAULT_THICKNESS: f64 = 400.0;

/// A column, a structural column or a footing as the file holds it.
pub fn column_json(
    cat: &str,
    type_ref: &str,
    level_guid: &str,
    at: [f64; 2],
    angle: f64,
    top_level: Option<&str>,
    height: f64,
    base_offset: f64,
) -> Value {
    let mut m = Map::new();
    m.insert("guid", Value::s(&new_guid()));
    m.insert("category", Value::s(cat));
    m.insert("type", Value::s(type_ref));
    m.insert("level", Value::s(level_guid));
    m.insert("at", Value::from(at));
    m.insert("angle", Value::f(angle));
    m.insert("top_level", top_level.map(Value::s).unwrap_or(Value::Null));
    m.insert("height", Value::f(height));
    m.insert("base_offset", Value::f(base_offset));
    Value::Obj(m)
}

fn type_param(s: &Session, cid: &str, cat: &str, p: &Value) -> R<String> {
    match opt_text(p, cid, "type")? {
        Some(t) => Ok(type_name_param(&s.project, &t)),
        None => match crate::structure::types::default_type(&s.project, cat) {
            Some(t) => Ok(t),
            None => Err(format!("{}: the model has no types for this", cid)),
        },
    }
}

/// `column` and `structural_column`.
pub fn column(s: &mut Session, cid: &str, cat: &str, p: &Value) -> R<Value> {
    let at = req_point(p, cid, "at")?;
    let level = level_param(&s.project, cid, p)?;
    let type_name = type_param(s, cid, cat, p)?;
    let angle = opt_num(p, cid, "angle")?.unwrap_or(0.0);
    let height = opt_num(p, cid, "height")?;
    let top_level = match get(p, "top_level") {
        Some(v) => Some(level_ref(&s.project, cid, "top_level", v)?),
        None => None,
    };
    let base_offset = opt_num(p, cid, "base_offset")?.unwrap_or(0.0);
    let pr = &s.project;
    // up to the level given, else (without a height) the next one up
    let top = match (top_level, height) {
        (Some(t), _) => Some(t),
        (None, Some(_)) => None,
        (None, None) => level_above(pr, level),
    };
    let level_guid = pr.guid_of(level).unwrap_or_default();
    let top_guid = top.and_then(|t| pr.guid_of(t));
    let type_ref = type_guid(pr, cat, &type_name).unwrap_or(type_name);
    let e = column_json(
        cat,
        &type_ref,
        &level_guid,
        at,
        angle,
        top_guid.as_deref(),
        height.unwrap_or(DEFAULT_HEIGHT),
        base_offset,
    );
    let id = add_element(s, e);
    Ok(crate::jobj! {"id" => id})
}

/// `footing`: an isolated pad, `thickness` thick, its top `offset` over its level.
pub fn footing(s: &mut Session, cid: &str, p: &Value) -> R<Value> {
    let cat = "footing";
    let at = req_point(p, cid, "at")?;
    let level = level_param(&s.project, cid, p)?;
    let type_name = type_param(s, cid, cat, p)?;
    let angle = opt_num(p, cid, "angle")?.unwrap_or(0.0);
    let thickness = opt_num(p, cid, "thickness")?.unwrap_or(DEFAULT_THICKNESS);
    if thickness <= 0.0 {
        return Err(format!("{}: `thickness` must be above zero, got {}", cid, thickness));
    }
    let offset = opt_num(p, cid, "offset")?.unwrap_or(0.0);
    let pr = &s.project;
    let level_guid = pr.guid_of(level).unwrap_or_default();
    let type_ref = type_guid(pr, cat, &type_name).unwrap_or(type_name);
    let e = column_json(cat, &type_ref, &level_guid, at, angle, None, thickness, offset - thickness);
    let id = add_element(s, e);
    Ok(crate::jobj! {"id" => id})
}
//! The model's rules for runs and columns, as the original checks them after every command and
//! when it opens a file: element by element in id order, each one's rules in turn.

use super::geom::{may_stand, run_line, MAX_SLOPE, TOL};
use super::read::{guid_index, lib_by_guid, norm_ref, parse_guid};
use crate::commands::params::MAX_MM;
use crate::json::Value;
use crate::project::Project;
use crate::structure::common::{is_run, type_kind, types_of, COLUMN_CATS, R};
use std::collections::HashMap;

struct Ctx<'a> {
    pr: &'a Project,
    guids: HashMap<String, u64>,
}

pub fn check(pr: &Project) -> R<()> {
    let mut ctx: Option<Ctx> = None;
    for (id, e) in &pr.elements {
        let cat = match e.get("category").and_then(|c| c.as_str()) {
            Some(c) => c,
            None => continue,
        };
        let run = is_run(cat);
        if !run && !COLUMN_CATS.contains(&cat) {
            continue;
        }
        let c = ctx.get_or_insert_with(|| Ctx { pr, guids: guid_index(pr) });
        if run {
            check_run(c, *id, cat, e)?;
        } else {
            check_column(c, *id, cat, e)?;
        }
    }
    Ok(())
}

/// The type an element names must be one of its category's.
fn check_type(c: &Ctx, id: u64, cat: &str, e: &Value) -> R<()> {
    let pr = c.pr;
    let types = types_of(pr, cat);
    let raw = match e.get("type") {
        Some(Value::Str(s)) => s.clone(),
        Some(v) => v.to_compact(),
        None => String::new(),
    };
    // a GUID of one of the category's types stands for its name
    let mut shown = raw.clone();
    if parse_guid(&raw).is_some() {
        if let Some(lid) = lib_by_guid(pr, &raw) {
            let le = &pr.library[&lid];
            if le.get("kind").and_then(|k| k.as_str()) == Some(type_kind(cat).as_str()) {
                if let Some(n) = le.get("name").and_then(|n| n.as_str()) {
                    shown = n.to_string();
                }
            }
        }
    }
    if types.map(|t| t.contains(&shown)).unwrap_or(false) {
        return Ok(());
    }
    let mut names: Vec<&String> = types.map(|t| t.keys().collect()).unwrap_or_default();
    names.sort();
    let names: Vec<&str> = names.iter().map(|s| s.as_str()).collect();
    Err(format!("{} {}: type `{}` doesn't exist (there are: {})", cat, id, shown, names.join(", ")))
}

/// A reference to a level (`level`, `top_level`) must be one.
fn check_level_ref(c: &Ctx, id: u64, cat: &str, v: Option<&Value>) -> R<()> {
    let shown = match v {
        Some(Value::Str(s)) => match c.guids.get(&norm_ref(s)) {
            Some(target) => {
                if c.pr.category(*target) == Some("level") {
                    return Ok(());
                }
                target.to_string()
            }
            None => s.clone(),
        },
        Some(v) => v.to_compact(),
        None => "null".to_string(),
    };
    Err(format!("{} {}: level {} doesn't exist", cat, id, shown))
}

/// A number the model can hold: within 1000 km.
fn usable(cat: &str, id: u64, what: &str, x: Option<f64>) -> R<()> {
    match x {
        Some(v) if !(v.is_finite() && v.abs() <= MAX_MM) => {
            Err(format!("{} {} {}: {} is not a usable number", cat, id, what, v))
        }
        _ => Ok(()),
    }
}

fn num(e: &Value, k: &str) -> Option<f64> {
    e.get(k).and_then(|x| x.as_f64())
}

fn coord(e: &Value, k: &str, i: usize) -> Option<f64> {
    e.get(k).and_then(|p| p.as_arr()).and_then(|a| a.get(i)).and_then(|x| x.as_f64())
}

fn check_run(c: &Ctx, id: u64, cat: &str, e: &Value) -> R<()> {
    check_type(c, id, cat, e)?;
    check_level_ref(c, id, cat, e.get("level"))?;
    usable(cat, id, "start x", coord(e, "start", 0))?;
    usable(cat, id, "start y", coord(e, "start", 1))?;
    usable(cat, id, "end x", coord(e, "end", 0))?;
    usable(cat, id, "end y", coord(e, "end", 1))?;
    usable(cat, id, "offset", num(e, "offset"))?;
    usable(cat, id, "end_offset", num(e, "end_offset"))?;
    if let Some(sys) = e.get("system").and_then(|s| s.as_str()) {
        if sys.chars().count() > 256 {
            return Err(format!("{} {}: system is longer than 256 characters", cat, id));
        }
    }
    let line = match run_line(e) {
        Some(l) => l,
        None => return Ok(()),
    };
    let len = line.length();
    if len <= TOL {
        return Err(format!("{} {}: too short ({} mm)", cat, id, len));
    }
    if !may_stand(cat) {
        if line.stands() {
            return Err(format!(
                "{} {}: its ends are one over the other; a {} runs along, and what stands is a column",
                cat, id, cat
            ));
        }
        let slope = line.slope_degrees();
        if slope > MAX_SLOPE {
            return Err(format!(
                "{} {}: it slopes {:.1}°, more than the {}° a {} may; what stands is a column",
                cat, id, slope, MAX_SLOPE, cat
            ));
        }
    }
    Ok(())
}

fn check_column(c: &Ctx, id: u64, cat: &str, e: &Value) -> R<()> {
    check_type(c, id, cat, e)?;
    check_level_ref(c, id, cat, e.get("level"))?;
    usable(cat, id, "x", coord(e, "at", 0))?;
    usable(cat, id, "y", coord(e, "at", 1))?;
    usable(cat, id, "angle", num(e, "angle"))?;
    usable(cat, id, "base_offset", num(e, "base_offset"))?;
    let connected = matches!(e.get("top_level"), Some(v) if !v.is_null());
    let height = num(e, "height").unwrap_or(0.0);
    if connected {
        check_level_ref(c, id, cat, e.get("top_level"))?;
    } else {
        usable(cat, id, "height", Some(height))?;
        if height <= 0.0 {
            return Err(format!("{} {} height must be above zero, got {}", cat, id, height));
        }
    }
    let pr = c.pr;
    let elev = |key: &str| -> f64 {
        e.get(key)
            .and_then(|g| g.as_str())
            .and_then(|g| c.guids.get(&norm_ref(g)))
            .and_then(|l| pr.el(*l))
            .and_then(|l| l.get("elevation"))
            .and_then(|x| x.as_f64())
            .unwrap_or(0.0)
    };
    let base = elev("level") + num(e, "base_offset").unwrap_or(0.0);
    let top = if connected { elev("top_level") } else { base + height };
    if top <= base + TOL {
        return Err(format!("{} {}: its top must be above its base", cat, id));
    }
    Ok(())
}
//! What `elements` shows of a run or a column besides its fields: its type by name and GUID, its
//! section, a run's centre line and length, a column's height.

use super::geom::{column_height, run_geom, section, type_guid, type_name};
use crate::json::Value;
use crate::project::Project;
use crate::structure::common::is_run;

/// Rounded to the hundredth of a millimetre, as `elements` shows a run's line.
pub fn round2(x: f64) -> f64 {
    (x * 100.0).round() / 100.0
}

pub fn element_view(pr: &Project, _id: u64, x: &mut Value) {
    let e = x.clone();
    let cat = e.get("category").and_then(|c| c.as_str()).unwrap_or("").to_string();
    let name = type_name(pr, &e);
    let guid = type_guid(pr, &e);
    let sec = section(pr, &e);
    if let Some(n) = &name {
        x.set("type", Value::s(n));
    }
    if let Some(g) = &guid {
        x.set("type_guid", Value::s(g));
    }
    if let Some(s) = &sec {
        x.set("width", Value::f(s.width));
        x.set("depth", Value::f(s.depth));
        x.set("round", Value::Bool(s.round));
    }
    if is_run(&cat) {
        if let Some(g) = run_geom(pr, &e) {
            let axis: Vec<Value> = g
                .axis
                .iter()
                .map(|p| Value::Arr(p.iter().map(|c| Value::f(round2(*c))).collect()))
                .collect();
            x.set("axis", Value::Arr(axis));
            x.set("length", Value::f(round2(g.length)));
        }
    } else {
        if let Some(h) = column_height(pr, &e) {
            x.set("height", Value::f(h));
        }
        if cat == "column" || cat == "structuralcolumn" {
