#!/usr/bin/env python3
"""Run reinforce cases on the original and print, per layer, the first path point of each bar
(or a chosen coordinate). usage: stations.py [-f file] [-i index] [-k coord] case..."""
import sys, subprocess, tempfile, os, json, shutil
exe = '/workspace/executable'
args = sys.argv[1:]; files = []; idx = 0; coord = None; full = False
while args and args[0].startswith('-'):
    if args[0] == '-f': files.append(args[1]); args = args[2:]
    elif args[0] == '-i': idx = int(args[1]); args = args[2:]
    elif args[0] == '-k': coord = int(args[1]); args = args[2:]
    elif args[0] == '-p': full = True; args = args[1:]
    elif args[0] == '-m': exe = '/workspace/.claude/worktrees/agent-add01394c801ae7f2/target/release/bimcraft-cli'; args = args[1:]
    else: break
for case in args:
    d = tempfile.mkdtemp()
    for f in files: shutil.copy(f, d)
    cl = [exe, 'run'] + ([os.path.basename(files[0])] if files else [])
    for c in case.split(' ;; '): cl += ['--cmd', c]
    cl += ['--save', 'out.bimcraft']
    p = subprocess.run(cl, cwd=d, capture_output=True, text=True)
    print('CASE', case)
    if p.stderr: print('  ERR', p.stderr.strip())
    else:
        print('  OUT', [l for l in p.stdout.split('\n') if l][-2][:300])
        j = json.load(open(os.path.join(d, 'out.bimcraft')))
        layers = {}
        for k, v in j['elements'].items():
            if v.get('category') == 'rebar':
                layers.setdefault(v.get('layer'), []).append(v)
        for l, vs in layers.items():
            if full:
                for v in vs: print('  ', l, json.dumps(v['path']))
            else:
                pts = [v['path'][idx] if coord is None else v['path'][idx][coord] for v in vs]
                print('  ', l, len(vs), json.dumps(pts))
    shutil.rmtree(d)

