input.content:
//! `reinforce`: bars by rules for beams, columns, footings and floors. The engineer says how many
//! bars, how thick and how far apart; this lays them out in the host's own frame inside the
//! cover and checks that what is asked fits, saying what to change. Each bar is a `rebar`
//! element of the host on a `layer`; reinforcing again replaces the bars that have a layer and
//! leaves the ones drawn by hand.
//!
//! The order the original reads and checks things in (the first that fails is the refusal): the
//! `preset` (its parameters, given ones replacing them key by key), the hosts (each element,
//! then each one's level), the preset's kind against each host, `grade`, `grade_stirrup` and
//! `clearance`, the `check` (`aggressiveness`, `check`, `fck`), and then host by host (a refusal
//! naming the host where there are several) its cover, its kind and what its kind takes.

pub mod beam;
pub mod column;
pub mod de;
pub mod floor;
pub mod footing;
pub mod geom;
pub mod norm;
pub mod shapes;

use crate::commands::params::get;
use crate::json::{Map, Value};
use crate::project::Project;
use crate::session::Session;
use crate::structure::common::{add_element, R};
use crate::structure::rebar::{self, read_ref, resolve_ref, ElemRef, MAX_BARS, MAX_BARS_ALL, MAX_HOSTS};
use geom::V3;

const CMD: &str = "reinforce";

/// The most a length may be, mm.
pub const MAX_MM: f64 = 1e9;
/// The thinnest and thickest bar.
pub const MIN_D: f64 = 3.0;
pub const MAX_D: f64 = 100.0;
/// The most bars in a row, or of a column's face.
pub const MAX_COUNT: u64 = 1000;

/// A bar laid out: its path (absolute heights), diameter, grade and layer.
#[derive(Clone, Debug)]
pub struct Bar {
    pub path: Vec<V3>,
    pub diameter: f64,
    pub grade: String,
    pub layer: String,
}

/// A host being armed.
pub struct Host {
    pub id: u64,
    pub cat: String,
    pub level: u64,
    pub elevation: f64,
}

/// `grade`, `grade_stirrup` and `clearance`, read once for all hosts.
pub struct Common {
    pub grade: String,
    pub grade_stirrup: String,
    pub clearance: Option<f64>,
}

impl Common {
    /// The least gap between bars of these diameters: the one given, else the thickest of them
    /// and at least 20 mm.
    pub fn clearance_for(&self, ds: &[f64]) -> f64 {
        match self.clearance {
            Some(c) => c,
            None => ds.iter().fold(20.0f64, |a, b| a.max(*b)),
        }
    }
}

/// The cover of each face, mm.
#[derive(Clone, Copy, Debug)]
pub struct Cover {
    pub top: f64,
    pub bottom: f64,
    pub sides: f64,
}

/// What arming one host needs.
pub struct Ctx<'a> {
    pub pr: &'a Project,
    pub host: &'a Host,
    pub e: &'a Value,
    pub params: &'a Map,
    pub common: &'a Common,
    pub cover: Cover,
}

/// What a host is armed with: its bars, and what the check reads of them.
pub struct Armed {
    pub bars: Vec<Bar>,
    pub info: norm::Info,
}

/// The `check` asked for: the aggressiveness class and the concrete's strength.
#[derive(Clone, Copy, Debug)]
pub struct Check {
    pub aggressiveness: Option<u64>,
    pub fck: Option<f64>,
}

/// The kind of host a category is, as presets name them.
pub fn kind_of(cat: &str) -> &str {
    match cat {
        "beam" => "beam",
        "column" | "structuralcolumn" => "column",
        "footing" => "footing",
        "floor" => "floor",
        other => other,
    }
}

fn err(msg: String) -> String {
    format!("{}: {}", CMD, msg)
}

/// A length a parameter gives: a number over 0 and up to 1000 km.
pub fn positive(what: &str, x: f64) -> R<f64> {
    if x > 0.0 && x <= MAX_MM {
        Ok(x)
    } else {
        Err(format!("`{}` must be over 0 and up to 1000000000 mm, got {}", what, x))
    }
}

/// A length a parameter gives that may be 0: up to 1000 km.
pub fn not_negative(what: &str, x: f64) -> R<f64> {
    if x >= 0.0 && x <= MAX_MM {
        Ok(x)
    } else {
        Err(format!("`{}` {} mm must be 0 or more, up to 1000000000", what, x))
    }
}

/// A bar's diameter: 3 to 100 mm.
pub fn diameter(what: &str, d: f64) -> R<f64> {
    if (MIN_D..=MAX_D).contains(&d) {
        Ok(d)
    } else {
        Err(format!("`{}` diameter {} mm isn't between 3 and 100 mm", what, d))
    }
}

/// A spacing of bars of a diameter: more than the diameter, up to 1000 km.
pub fn spacing(what: &str, s: f64, d: f64) -> R<f64> {
    if s > d && s <= MAX_MM {
        Ok(s)
    } else {
        Err(format!("`{}` spacing {} mm must be more than the {} mm diameter, and up to 1000000000", what, s, d))
    }
}

/// A count of bars: 1 to 1000.
pub fn count(what: &str, n: u64) -> R<usize> {
    if (1..=MAX_COUNT).contains(&n) {
        Ok(n as usize)
    } else {
        Err(format!("`{}` count {} isn't 1 to 1000", what, n))
    }
}

/// The value of one of the host's parameters by its name, where it is a number.
fn host_param(pr: &Project, e: &Value, name: &str) -> Option<f64> {
    let ps = e.get("params")?.as_obj()?;
    for (k, v) in ps.iter() {
        if crate::styles::parameters::param_of_key(pr, k).as_deref() == Some(name) {
            if let Some(x) = v.as_f64() {
                return Some(x);
            }
        }
    }
    None
}

/// The cover of each face: what `cover` says (a number for all, or {top, bottom, sides}), else
/// the host's `Cobrimento` or `ConcreteCover` parameter; face by face.
fn read_cover(pr: &Project, e: &Value, params: &Map) -> R<Cover> {
    let faces: [Option<f64>; 3] = match params.get("cover") {
        None | Some(Value::Null) => [None, None, None],
        Some(Value::Num(n)) => {
            let x = n.as_f64();
            [Some(x), Some(x), Some(x)]
        }
        Some(v) => match de::de_struct(v, &shapes::FACES) {
            Ok(m) => [de::f(&m, "top"), de::f(&m, "bottom"), de::f(&m, "sides")],
            Err(_) => return Err("`cover`: data did not match any variant of untagged enum CoverArg".into()),
        },
    };
    let fallback = host_param(pr, e, "Cobrimento").or_else(|| host_param(pr, e, "ConcreteCover"));
    let mut out = [0.0; 3];
    for (i, name) in ["top", "bottom", "sides"].iter().enumerate() {
        let x = match faces[i].or(fallback) {
            Some(x) => x,
            None => {
                return Err(format!(
                    "no cover for the {}: give `cover` in mm (a number, or top, bottom and sides), or give the host a Cobrimento parameter",
                    name
                ))
            }
        };
        out[i] = positive("cover", x)?;
    }
    Ok(Cover { top: out[0], bottom: out[1], sides: out[2] })
}

/// The parameters of a kind, as the "isn't a parameter" refusal lists them.
fn kind_params(kind: &str) -> &'static [&'static str] {
    match kind {
        "beam" => &["cover", "grade", "grade_stirrup", "clearance", "bottom", "top", "stirrup", "skin", "anchor"],
        "column" => &["cover", "grade", "grade_stirrup", "clearance", "bars", "stirrup", "ties", "anchor"],
        "footing" => &["cover", "grade", "clearance", "mesh"],
        "floor" => &["cover", "grade", "clearance", "bottom", "top"],
        _ => &[],
    }
}

/// What every command takes whatever the host.
const GENERAL: &[&str] = &["host", "hosts", "check", "aggressiveness", "fck"];

/// Refuses a key the host's kind doesn't take (the first in sorted order).
pub fn check_keys(params: &Map, kind: &str) -> R<()> {
    let allowed = kind_params(kind);
    let mut keys: Vec<&String> = params.keys().collect();
    keys.sort();
    for k in keys {
        if GENERAL.contains(&k.as_str()) || allowed.contains(&k.as_str()) {
            continue;
        }
        if kind == "footing" && k == "grade_stirrup" {
            continue;
        }
        if kind == "floor" && k == "grade_stirrup" {
            continue;
        }
        let list = allowed.to_vec();
        let (last, rest) = list.split_last().unwrap();
        return Err(format!("`{}` isn't a parameter of a {}; it takes {} and {}", k, kind, rest.join(", "), last));
    }
    Ok(())
}

/// One of a kind's parameters read as its serde type: None when left out or null.
pub fn read_struct(params: &Map, key: &str, shape: &de::Shape) -> R<Option<Map>> {
    match params.get(key) {
        None | Some(Value::Null) => Ok(None),
        Some(v) => de::de_struct(v, shape).map(Some).map_err(|e| format!("`{}`: {}", key, e)),
    }
}

fn read_hosts(pr: &Project, params: &Map) -> R<Vec<u64>> {
    let host = params.get("host").filter(|v| !v.is_null());
    let hosts = params.get("hosts").filter(|v| !v.is_null());
    let ids: Vec<u64> = match (host, hosts) {
        (Some(_), Some(_)) => return Err(err("give `host` or `hosts`, not both".into())),
        (None, None) => return Err(err("`host` (an element) or `hosts` (a list of them) is required".into())),
        (Some(v), None) => {
            let r = read_ref(v)
                .ok_or_else(|| err(format!("`host` must be an element id or GUID, got {}", v.to_compact())))?;
            vec![resolve_ref(pr, &r).ok_or_else(|| err(format!("no element {}", r.text())))?]
        }
        (None, Some(v)) => {
            let a = match v.as_arr() {
                Some(a) if !a.is_empty() && a.len() <= MAX_HOSTS => a,
                _ => return Err(err("`hosts` is a list of 1 to 1000 elements".into())),
            };
            let mut out = Vec::with_capacity(a.len());
            for x in a {
                let r: ElemRef =
                    read_ref(x).ok_or_else(|| err(format!("{} is not an element id or GUID", x.to_compact())))?;
                out.push(resolve_ref(pr, &r).ok_or_else(|| err(format!("no element {}", r.text())))?);
            }
            out
        }
    };
    let mut seen: Vec<u64> = Vec::with_capacity(ids.len());
    for id in ids {
        if !seen.contains(&id) {
            seen.push(id);
        }
    }
    Ok(seen)
}

fn read_common(params: &Map) -> R<Common> {
    let text = |key: &str| -> R<Option<String>> {
        match params.get(key) {
            None | Some(Value::Null) => Ok(None),
            Some(v) => {
                let s = de::de_str(v).map_err(|e| err(format!("`{}`: {}", key, e)))?;
                if s.trim().is_empty() {
                    return Err(err("a `grade` can't be blank".into()));
                }
                Ok(Some(s))
            }
        }
    };
    let grade = text("grade")?.unwrap_or_else(|| rebar::DEFAULT_GRADE.to_string());
    let grade_stirrup = text("grade_stirrup")?.unwrap_or_else(|| grade.clone());
    let clearance = match params.get("clearance") {
        None | Some(Value::Null) => None,
        Some(v) => {
            let c = de::de_f64(v).map_err(|e| err(format!("`clearance`: {}", e)))?;
            Some(positive("clearance", c).map_err(err)?)
        }
    };
    Ok(Common { grade, grade_stirrup, clearance })
}

/// Whether a `check` names NBR 6118 (its letters and digits, in any case, begin so).
fn is_nbr(s: &str) -> bool {
    let t: String = s.chars().filter(|c| c.is_alphanumeric()).flat_map(|c| c.to_lowercase()).collect();
    t.starts_with("nbr6118")
}

fn read_check(params: &Map) -> R<Option<Check>> {
    let field = |key: &str| params.get(key).filter(|v| !v.is_null());
    let aggressiveness = match field("aggressiveness") {
        None => None,
        Some(v) => Some(de::de_u8(v).map_err(|e| err(format!("`aggressiveness`: {}", e)))?),
    };
    let check = match field("check") {
        None => None,
        Some(v) => Some(de::de_str(v).map_err(|e| err(format!("`check`: {}", e)))?),
    };
    let fck = match field("fck") {
        None => None,
        Some(v) => Some(de::de_f64(v).map_err(|e| err(format!("`fck`: {}", e)))?),
    };
    if let Some(c) = &check {
        if !is_nbr(c) {
            return Err(err(format!(
                "`check` {} isn't one this knows: it is \"NBR 6118\"",
                Value::s(c).to_compact()
            )));
        }
    }
    if check.is_none() {
        if aggressiveness.is_some() || fck.is_some() {
            return Err(err("`aggressiveness` and `fck` go with `check`: give `check` \"NBR 6118\"".into()));
        }
        return Ok(None);
    }
    if let Some(a) = aggressiveness {
        if !(1..=4).contains(&a) {
            return Err(err("`aggressiveness` is the class 1 to 4 (I to IV)".into()));
        }
    }
    if let Some(f) = fck {
        if !(10.0..=100.0).contains(&f) {
            return Err(err("`fck` is the concrete's strength in MPa, 10 to 100".into()));
        }
    }
    Ok(Some(Check { aggressiveness, fck }))
}

/// Arms one host: its cover, its kind, and its kind's bars.
fn arm(pr: &Project, host: &Host, params: &Map, common: &Common) -> R<Armed> {
    let e = pr.el(host.id).ok_or_else(|| format!("no element {}", host.id))?;
    let cover = read_cover(pr, e, params)?;
    let ctx = Ctx { pr, host, e, params, common, cover };
    match host.cat.as_str() {
        "beam" => beam::arm(&ctx),
        "column" | "structuralcolumn" => column::arm(&ctx),
        "footing" => footing::arm(&ctx),
        "floor" => floor::arm(&ctx),
        other => Err(format!("a {} can't be armed: a beam, a column, a footing or a floor can", other)),
    }
}

pub fn run(s: &mut Session, cid: &str, p0: &Value) -> R<Value> {
    let _ = cid;
    let p = crate::structure::types::names_for_guids(&s.project, p0);
    let pr = &s.project;
    let mut params: Map = p.as_obj().cloned().unwrap_or_default();
    // the preset's parameters, those given replacing them key by key
    let mut preset: Option<(String, String)> = None;
    match get(&p, "preset") {
        None => {}
        Some(Value::Str(name)) if name.chars().count() <= 256 => {
            let e = pr
                .section(crate::styles::presets::SECTION)
                .and_then(|m| m.get(name))
                .ok_or_else(|| err(format!("there's no reinforcement preset `{}`", name)))?;
            let kind = e.get("kind").and_then(|k| k.as_str()).unwrap_or("").to_string();
            let mut merged = e.get("params").and_then(|x| x.as_obj()).cloned().unwrap_or_default();
            for (k, v) in params.items.iter() {
                if k != "preset" {
                    merged.insert(k, v.clone());
                }
            }
            params = merged;
            preset = Some((name.clone(), kind));
        }
        Some(v) => {
            return Err(err(format!("`preset` must be text of at most 256 characters, got {}", v.to_compact())))
        }
    }
    let ids = read_hosts(pr, &params)?;
    let mut hosts: Vec<Host> = Vec::with_capacity(ids.len());
    for id in &ids {
        let e = &pr.elements[id];
        let level = rebar::level_of(pr, e).ok_or_else(|| err("that element has no level".into()))?;
        let elevation = pr.el(level).and_then(|l| l.get("elevation")).and_then(|x| x.as_f64()).unwrap_or(0.0);
        let cat = e.get("category").and_then(|c| c.as_str()).unwrap_or("").to_string();
        hosts.push(Host { id: *id, cat, level, elevation });
    }
    if let Some((name, kind)) = &preset {
        for h in &hosts {
            if kind_of(&h.cat) != kind.as_str() {
                return Err(err(format!("preset `{}` is for a {}, and {} is a {}", name, kind, h.id, h.cat)));
            }
        }
    }
    let common = read_common(&params)?;
    let check = read_check(&params)?;
    let many = hosts.len() > 1;
    let mut armed: Vec<Armed> = Vec::with_capacity(hosts.len());
    let mut total = 0usize;
    for h in &hosts {
        let a = arm(pr, h, &params, &common).map_err(|e| {
            if many {
                err(format!("{} (for the {} {})", e, h.cat, h.id))
            } else {
                err(e)
            }
        })?;
        total += a.bars.len();
        if total > MAX_BARS_ALL {
            return Err(err(format!(
                "that is more than the {} bars a command makes for all its hosts: widen a spacing or arm fewer hosts",
                MAX_BARS_ALL
            )));
        }
        armed.push(a);
    }
    let mut notes: Vec<Value> = Vec::new();
    if let Some(c) = &check {
        for (h, a) in hosts.iter().zip(armed.iter()) {
            for n in norm::notes(pr, h, &a.info, c) {
                notes.push(Value::s(&if many { format!("{} {}: {}", h.cat, h.id, n) } else { n }));
            }
        }
    }
    // the bars made before by this command (those on a layer) go
    let mut removed = 0usize;
    for h in &hosts {
        let g = pr.guid_of(h.id).unwrap_or_default();
        let old: Vec<u64> = rebar::bars_of_host(pr, &g)
            .into_iter()
            .filter(|b| {
                pr.el(*b).and_then(|e| e.get("layer")).and_then(|l| l.as_str()).map(|l| !l.is_empty()).unwrap_or(false)
            })
            .collect();
        removed += old.len();
        for b in old {
            s.project.elements.remove(&b);
        }
    }
    let mut out_ids: Vec<Value> = Vec::new();
    let mut weight = 0.0;
    for (h, a) in hosts.iter().zip(armed.into_iter()) {
        let level_guid = s.project.guid_of(h.level).unwrap_or_default();
        let host_guid = s.project.guid_of(h.id).map(|g| crate::structure::members::read::norm_ref(&g));
        for b in a.bars {
            let path: Vec<[f64; 3]> = b.path.iter().map(|q| [q[0], q[1], q[2] - h.elevation]).collect();
            weight += rebar::weight_kg(b.diameter, rebar::length(&path));
            let e = rebar::bar_json(&level_guid, host_guid.as_deref(), &path, b.diameter, &b.grade, Some(&b.layer));
            out_ids.push(Value::u(add_element(s, e)));
        }
    }
    let _ = MAX_BARS;
    Ok(crate::jobj! {
        "count" => out_ids.len(),
        "hosts" => hosts.len(),
        "ids" => Value::Arr(out_ids),
        "notes" => Value::Arr(notes),
        "removed" => removed,
        "weight_kg" => rebar::round3(weight),
    })
}

/// The model rules of this part, checked after every command (a bar's own are `rebar`'s).
pub fn check(pr: &Project) -> R<()> {
    let _ = pr;
    Ok(())
}

//! A beam's bars: `bottom` and `top` rows (hooks; some bottom bars bent up), `stirrup`s (closer
//! at the ends, hooked), `skin` bars up each side, `anchor`s past the ends. Laid out in the
//! beam's frame: along its centre line from its start, across it (level, to the left), up
//! square to both; its section's centre at the origin.

use super::de::{self, any, f, sub, u};
use super::geom::{gaps, spread, station_count, stations, unit, Frame, TOL};
use super::shapes::{BEAM_ANCHOR, PITCH, ROW, STIRRUP};
use super::{check_keys, count, diameter, norm, not_negative, positive, read_struct, spacing, Armed, Bar, Ctx};
use crate::json::{Map, Value};
use crate::structure::common::R;
use crate::structure::members::geom::run_geom;
use crate::structure::rebar::MAX_BARS;

/// A row's hooks at the start and at the end, read from `hook`: a length for both, or
/// {start, end}.
pub fn legs(what: &str, ends: (&str, &str), v: Option<&Value>) -> R<(f64, f64)> {
    let bad = || format!("`{}` must be a length in mm, or {{{}, {}}}", what, ends.0, ends.1);
    match v {
        None | Some(Value::Null) => Ok((0.0, 0.0)),
        Some(Value::Num(n)) => {
            let x = not_negative(what, n.as_f64())?;
            Ok((x, x))
        }
        Some(Value::Obj(m)) => {
            let mut a = 0.0;
            let mut b = 0.0;
            for (k, x) in m.iter() {
                let val = match x {
                    Value::Null => 0.0,
                    Value::Num(n) => n.as_f64(),
                    _ => return Err(bad()),
                };
                if k == ends.0 {
                    a = val;
                } else if k == ends.1 {
                    b = val;
                } else {
                    return Err(bad());
                }
            }
            let a = not_negative(&format!("{} {}", what, ends.0), a)?;
            let b = not_negative(&format!("{} {}", what, ends.1), b)?;
            Ok((a, b))
        }
        Some(_) => Err(bad()),
    }
}

/// The bars a row's `bent` takes: `k` of the `m` inner ones, evenly (indices into the inner).
pub fn picks(m: usize, k: usize) -> Vec<usize> {
    if k == 0 || m == 0 {
        return Vec::new();
    }
    if k == 1 {
        return vec![(m - 1) / 2];
    }
    (0..k).map(|i| ((i as f64) * ((m - 1) as f64) / ((k - 1) as f64)).round() as usize).collect()
}

/// A row of bars as read.
struct Row {
    n: usize,
    d: f64,
    hooks: (f64, f64),
    /// count, angle, top
    bent: Option<(usize, f64, f64)>,
    /// Across, where each bar is.
    at: Vec<f64>,
    /// Up, where the row is.
    u: f64,
}

pub fn arm(ctx: &Ctx) -> R<Armed> {
    let pr = ctx.pr;
    let g = run_geom(pr, ctx.e).ok_or_else(|| "the beam has no section".to_string())?;
    if g.section.round {
        return Err("a round beam isn't reinforced yet; a rectangular one is".into());
    }
    let params = ctx.params;
    let bottom = read_struct(params, "bottom", &ROW)?;
    let top = read_struct(params, "top", &ROW)?;
    let stirrup = read_struct(params, "stirrup", &STIRRUP)?;
    let skin = read_struct(params, "skin", &PITCH)?;
    let anchor = read_struct(params, "anchor", &BEAM_ANCHOR)?;
    check_keys(params, "beam")?;
    if bottom.is_none() && top.is_none() && stirrup.is_none() {
        return Err("nothing to reinforce with: give `bottom` or `top` bars, or a `stirrup`".into());
    }
    let cv = ctx.cover;
    let ds = match &stirrup {
        Some(m) => diameter("stirrup", f(m, "diameter").unwrap_or(0.0))?,
        None => 0.0,
    };
    let w = g.section.width;
    let h = g.section.depth;
    let hw = w / 2.0;
    let hh = h / 2.0;
    let inner_w = w - 2.0 * cv.sides - 2.0 * ds;
    let inner_h = h - cv.top - cv.bottom - 2.0 * ds;
    if inner_w <= 0.0 || inner_h <= 0.0 {
        return Err("the section is too narrow or too shallow for that cover and stirrup".into());
    }
    // the frame: along the centre line, across it level, up square to both
    let a0 = g.axis[0];
    let a1 = g.axis[1];
    let dv = [a1[0] - a0[0], a1[1] - a0[1], a1[2] - a0[2]];
    let len = (dv[0] * dv[0] + dv[1] * dv[1] + dv[2] * dv[2]).sqrt();
    let along = [dv[0] / len, dv[1] / len, dv[2] / len];
    let hz = (dv[0] * dv[0] + dv[1] * dv[1]).sqrt();
    let across = [-dv[1] / hz, dv[0] / hz, 0.0];
    let up = super::geom::cross(along, across);
    let fr = Frame { o: a0, along, across, up };
    // how far the bars run: past the ends by the anchors, else a cover short of them
    let (t0, t1) = {
        let st = anchor.as_ref().and_then(|m| f(m, "start"));
        let en = anchor.as_ref().and_then(|m| f(m, "end"));
        let t0 = match st {
            Some(x) => -not_negative("anchor start", x)?,
            None => cv.sides,
        };
        let t1 = match en {
            Some(x) => len + not_negative("anchor end", x)?,
            None => len - cv.sides,
        };
        (t0, t1)
    };
    let clear = |ds_: &[f64]| ctx.common.clearance_for(ds_);
    // the rows
    let read_row = |m: &Map, name: &str, is_top: bool| -> R<Row> {
        let d = diameter(name, f(m, "diameter").unwrap_or(0.0))?;
        let n = count(name, u(m, "count").unwrap_or(0))?;
        let a = hw - cv.sides - ds - d / 2.0;
        if a < 0.0 {
            return Err(format!(
                "the section is too narrow for the {} bars of {} mm with that cover and stirrup",
                name, d
            ));
        }
        if inner_h < d {
            return Err(format!("a {} mm {} bar doesn't fit inside the stirrup, {:.1} mm deep", d, name, inner_h));
        }
        let hooks = legs(&format!("{} hook", name), ("start", "end"), any(m, "hook"))?;
        for hk in [hooks.0, hooks.1] {
            if hk > inner_h - d / 2.0 + TOL {
                return Err(format!(
                    "a {} hook of {} mm doesn't fit inside the stirrup, which is {:.1} mm deep from the bars",
                    name, hk, inner_h
                ));
            }
        }
        let u_row = if is_top { hh - cv.top - ds - d / 2.0 } else { -(hh - cv.bottom - ds - d / 2.0) };
        let mut bent = None;
        if let Some(b) = sub(m, "bent") {
            if is_top {
                return Err("only bottom bars are bent up: put `bent` in `bottom`".into());
            }
            let k = u(b, "count").unwrap_or(0);
            let most = n as i64 - 2;
            if k < 1 || k as i64 > most {
                return Err(format!(
                    "`bent` count {} must be 1 to {}: the two bars at the corners stay straight to hold the stirrups, and the bottom row has {}",
                    k, most, n
                ));
            }
            let angle = f(b, "angle").unwrap_or(45.0);
            if !(15.0..=75.0).contains(&angle) {
                return Err(format!("`bent` angle {} degrees isn't between 15 and 75", angle));
            }
            let tp = match f(b, "top") {
                Some(x) => positive("bent top", x)?,
                None => (t1 - t0) / 5.0,
            };
            let zt = hh - cv.top - ds - d / 2.0;
            let rise = zt - u_row;
            if rise <= TOL {
                return Err(format!(
                    "there's no room to bend a bar of {} mm up: it can't rise from the bottom to the top inside the stirrup",
                    d
                ));
            }
            let run = rise / angle.to_radians().tan();
            let each = tp + run;
            if 2.0 * each > t1 - t0 {
                return Err(format!(
                    "the bent bars meet in the middle: each end takes {:.0} mm of the {:.0} mm: give a shorter `top` or a steeper `angle`",
                    each,
                    t1 - t0
                ));
            }
            bent = Some((k as usize, angle, tp));
        }
        let at = spread(-a, a, n);
        if n > 1 {
            let gap = (at[1] - at[0]) - d;
            let gap = (2.0 * a) / (n - 1) as f64 - d + 0.0 * gap;
            let c = clear(&[d]);
            if gap < c - TOL {
                return Err(format!(
                    "{} {} bars of {} mm leave {:.1} mm between them, less than the {} mm clearance: use fewer or thinner bars",
                    n, name, d, gap, c
                ));
            }
        }
        Ok(Row { n, d, hooks, bent, at, u: u_row })
    };
    let brow = match &bottom {
        Some(m) => Some(read_row(m, "bottom", false)?),
        None => None,
    };
    let trow = match &top {
        Some(m) => Some(read_row(m, "top", true)?),
        None => None,
    };
    // a bent-up bar running along the top must keep clear of the top bars
    if let (Some(b), Some(t)) = (&brow, &trow) {
        if let Some((k, _, _)) = b.bent {
            let zt = hh - cv.top - ds - b.d / 2.0;
            let inner: Vec<usize> = (1..b.n - 1).collect();
            let c = clear(&[b.d, t.d]);
            for j in picks(inner.len(), k) {
                let ab = b.at[inner[j]];
                for at in &t.at {
                    let da = ab - at;
                    let du = zt - t.u;
                    let gap = (da * da + du * du).sqrt() - (b.d + t.d) / 2.0;
                    if gap < c - TOL {
                        return Err(format!(
                            "a bent-up bar meets a top bar: {:.1} mm between them, less than the {} mm clearance: bend up other bars or use fewer top bars",
                            gap, c
                        ));
                    }
                }
            }
        }
    }
    // skin bars up each side, between the rows
    let skin_rows = match &skin {
        Some(m) => {
            let dk = diameter("skin", f(m, "diameter").unwrap_or(0.0))?;
            let sp = spacing("skin", f(m, "spacing").unwrap_or(0.0), dk)?;
            let ub = match &brow {
                Some(r) => r.u,
                None => -(hh - cv.bottom - ds),
            };
            let ut = match &trow {
                Some(r) => r.u,
                None => hh - cv.top - ds,
            };
            let n = gaps(ut - ub, sp);
            let ak = hw - cv.sides - ds - dk / 2.0;
            let step = (ut - ub) / n as f64;
            let us: Vec<f64> = (1..n).map(|i| ub + step * i as f64).collect();
            Some((dk, ak, us))
        }
        None => None,
    };
    // the stirrups
    let mut st_stations: Vec<f64> = Vec::new();
    let mut st_hook = 0.0;
    if let Some(m) = &stirrup {
        let sp = spacing("stirrup", f(m, "spacing").unwrap_or(0.0), ds)?;
        if let Some(hk) = f(m, "hook") {
            st_hook = not_negative("hook", hk)?;
        }
        let ends = match sub(m, "ends") {
            Some(e) => {
                let l = f(e, "length").unwrap_or(0.0);
                if !(l > 0.0) {
                    return Err(format!("`ends` length {} mm must be over 0", l));
                }
                let esp = spacing("ends", f(e, "spacing").unwrap_or(0.0), ds)?;
                Some((l, esp))
            }
            None => None,
        };
        let s0 = cv.sides + ds / 2.0;
        let s1 = len - (cv.sides + ds / 2.0);
        let mut cnt = 0.0;
        let zones: Vec<(f64, f64, f64)> = match ends {
            Some((l, esp)) => {
                let a = s0 + l;
                let b = s1 - l;
                if b - a > TOL {
                    vec![(s0, a, esp), (a, b, sp), (b, s1, esp)]
                } else {
                    vec![(s0, s1, esp)]
                }
            }
            None => vec![(s0, s1, sp)],
        };
        for (a, b, s) in &zones {
            cnt += station_count(*a, *b, *s);
        }
        if cnt > (MAX_BARS + 10) as f64 {
            return Err(format!(
                "that is more than the {} bars a command makes: widen a spacing or use fewer bars",
                MAX_BARS
            ));
        }
        for (i, (a, b, s)) in zones.iter().enumerate() {
            let pts = stations(*a, *b, *s);
            let skip = if i == 0 { 0 } else { 1 };
            st_stations.extend(pts.into_iter().skip(skip));
        }
    }
    // the bars
    let gb = ctx.common.grade.clone();
    let gs = ctx.common.grade_stirrup.clone();
    let mut bars: Vec<Bar> = Vec::new();
    let mut bent_bars: Vec<Bar> = Vec::new();
    let straight = |r: &Row, a: f64, up_sign: f64| -> Vec<[f64; 3]> {
        let mut p = Vec::with_capacity(4);
        if r.hooks.0 > 0.0 {
            p.push(fr.at(t0, a, r.u + up_sign * r.hooks.0));
        }
        p.push(fr.at(t0, a, r.u));
        p.push(fr.at(t1, a, r.u));
        if r.hooks.1 > 0.0 {
            p.push(fr.at(t1, a, r.u + up_sign * r.hooks.1));
        }
        p
    };
    if let Some(r) = &brow {
        let chosen: Vec<usize> = match r.bent {
            Some((k, _, _)) => picks(r.n - 2, k).into_iter().map(|j| j + 1).collect(),
            None => Vec::new(),
        };
        for (i, a) in r.at.iter().enumerate() {
            if chosen.contains(&i) {
                let (_, angle, tp) = r.bent.unwrap();
                let zt = hh - cv.top - ds - r.d / 2.0;
                let run = (zt - r.u) / angle.to_radians().tan();
                let path = vec![
                    fr.at(t0, *a, zt),
                    fr.at(t0 + tp, *a, zt),
                    fr.at(t0 + tp + run, *a, r.u),
                    fr.at(t1 - tp - run, *a, r.u),
                    fr.at(t1 - tp, *a, zt),
                    fr.at(t1, *a, zt),
                ];
                bent_bars.push(Bar { path, diameter: r.d, grade: gb.clone(), layer: "bent".into() });
            } else {
                bars.push(Bar { path: straight(r, *a, 1.0), diameter: r.d, grade: gb.clone(), layer: "bottom".into() });
            }
        }
    }
    bars.extend(bent_bars);
    if let Some(r) = &trow {
        for a in &r.at {
            bars.push(Bar { path: straight(r, *a, -1.0), diameter: r.d, grade: gb.clone(), layer: "top".into() });
        }
    }
    if let Some((dk, ak, us)) = &skin_rows {
        for uu in us {
            for a in [-*ak, *ak] {
                let path = vec![fr.at(t0, a, *uu), fr.at(t1, a, *uu)];
                bars.push(Bar { path, diameter: *dk, grade: gb.clone(), layer: "skin".into() });
            }
        }
    }
    if stirrup.is_some() {
        let sa = hw - cv.sides - ds / 2.0;
        let su = hh - cv.top - ds / 2.0;
        let sb = -(hh - cv.bottom - ds / 2.0);
        let dir = unit(super::geom::sub(across, up));
        for t in &st_stations {
            let c0 = fr.at(*t, -sa, su);
            let c1 = fr.at(*t, sa, su);
            let c2 = fr.at(*t, sa, sb);
            let c3 = fr.at(*t, -sa, sb);
            let mut path = Vec::with_capacity(7);
            let tail = [c0[0] + dir[0] * st_hook, c0[1] + dir[1] * st_hook, c0[2] + dir[2] * st_hook];
            if st_hook > 0.0 {
                path.push(tail);
            }
            path.extend([c0, c1, c2, c3, c0]);
            if st_hook > 0.0 {
                path.push(tail);
            }
            bars.push(Bar { path, diameter: ds, grade: gs.clone(), layer: "stirrup".into() });
        }
    }
    if bars.len() > MAX_BARS {
        return Err(format!(
            "that is more than the {} bars a command makes: widen a spacing or use fewer bars",
            MAX_BARS
        ));
    }
    let _ = de::s;
    let info = norm::Info::default();
    Ok(Armed { bars, info })
}

