61	/// `n` places evenly from `a` to `b`, the first at `a` and the last at `b`; one is in the middle.
62	pub fn spread(a: f64, b: f64, n: usize) -> Vec<f64> {
63	    if n == 0 {
64	        return Vec::new();
65	    }
66	    if n == 1 {
67	        return vec![(a + b) / 2.0];
68	    }
69	    let m = (n - 1) as f64;
70	    (0..n).map(|i| a + (b - a) * i as f64 / m).collect()
71	}
72	
73	/// How many gaps at most `spacing` apart a length takes.
74	pub fn gaps(length: f64, spacing: f64) -> usize {
75	    let n = (length / spacing).ceil();
76	    if n < 1.0 {
77	        1
78	    } else {
79	        n as usize
80	    }
81	}
