83	/// Stations from `a` to `b` at most `spacing` apart, evenly: the first at `a`, the last at `b`.
84	pub fn stations(a: f64, b: f64, spacing: f64) -> Vec<f64> {
85	    let n = gaps(b - a, spacing);
86	    (0..=n).map(|i| a + (b - a) * i as f64 / n as f64).collect()
87	}
88	
89	/// How many stations `stations` gives, without making them (a guard against huge counts).
90	pub fn station_count(a: f64, b: f64, spacing: f64) -> f64 {
91	    ((b - a) / spacing).ceil().max(1.0) + 1.0
92	}

