#!/usr/bin/env python3
"""Make random beam projects with the original and random reinforce cases for them.
usage: gen_beams.py SEED NCASES -> writes /tmp/rebar-agent/gb_SEED.bimcraft and gb_SEED.txt"""
import sys, json, random, subprocess, os, tempfile, shutil
seed = int(sys.argv[1]); ncases = int(sys.argv[2])
R = random.Random(seed)
def rnd(a, b, nd=None):
    x = R.uniform(a, b)
    if nd is None: nd = R.choice([0, 0, 1, 2, 3])
    return round(x, nd)
cmds = []
# levels with odd elevations
cmds.append('level {"name":"LA","elevation":%s}' % rnd(-2000, 9000))
cmds.append('level {"name":"LB","elevation":%s}' % rnd(-2000, 9000))
types = []
for i in range(4):
    w = rnd(120, 700); d = rnd(200, 1200)
    name = 'T%d %s x %s' % (i, w, d)
    types.append(name)
    cmds.append('type ' + json.dumps({"category": "beam", "name": name, "width": w, "depth": d}))
nbeams = 6
for i in range(nbeams):
    p0 = [rnd(-5000, 5000), rnd(-5000, 5000)]
    ang = R.uniform(0, 6.283)
    import math
    L = rnd(1500, 9000)
    p1 = [round(p0[0] + L * math.cos(ang), R.choice([0, 1, 3])), round(p0[1] + L * math.sin(ang), R.choice([0, 1, 3]))]
    b = {"points": [p0, p1], "type": R.choice(types), "level": R.choice(["Level 1", "Level 2", "LA", "LB"])}
    r = R.random()
    if r < 0.3:
        b["offset"] = rnd(-500, 500)
    elif r < 0.6:
        b["offset"] = rnd(-300, 300); b["end_offset"] = rnd(-800, 800)
    if R.random() < 0.4:
        b["justify"] = R.choice(["top", "centre", "bottom"])
    cmds.append('beam ' + json.dumps(b))
d = tempfile.mkdtemp()
cl = ['/workspace/executable', 'run']
for c in cmds: cl += ['--cmd', c]
cl += ['--save', 'in.bimcraft']
p = subprocess.run(cl, cwd=d, capture_output=True, text=True)
if p.returncode != 0:
    print('build failed', p.stderr); sys.exit(1)
out = '/tmp/rebar-agent/gb_%d.bimcraft' % seed
shutil.copy(os.path.join(d, 'in.bimcraft'), out)
shutil.rmtree(d)
j = json.load(open(out))
beams = [int(k) for k, v in j['elements'].items() if v['category'] == 'beam']
cases = []
def row():
    r = {"count": R.choice([1, 2, 2, 3, 4, 5, 6]), "diameter": R.choice([6.3, 8, 10, 12.5, 16, 20, 25, rnd(5, 32)])}
    if R.random() < 0.3:
        r["hook"] = R.choice([rnd(0, 300), {"start": rnd(0, 300)}, {"end": rnd(0, 300)}, {"start": rnd(0, 300), "end": rnd(0, 300)}])
    return r
for i in range(ncases):
    p = {"host": R.choice(beams)}
    rc = R.random()
    if rc < 0.6:
        p["cover"] = R.choice([20, 25, 30, 40, rnd(15, 50)])
    else:
        p["cover"] = {"top": rnd(15, 50), "bottom": rnd(15, 50), "sides": rnd(15, 50)}
    if R.random() < 0.8:
        p["bottom"] = row()
        if R.random() < 0.3 and p["bottom"]["count"] >= 3:
            b = {"count": R.randint(1, p["bottom"]["count"] - 2)}
            if R.random() < 0.5: b["angle"] = R.choice([30, 45, 60, rnd(15, 75)])
            if R.random() < 0.4: b["top"] = rnd(200, 2000)
            p["bottom"]["bent"] = b
    if R.random() < 0.6:
        p["top"] = row()
    if R.random() < 0.7:
        s = {"diameter": R.choice([5, 6.3, 8, rnd(4, 10)]), "spacing": R.choice([100, 150, 200, rnd(80, 400)])}
        if R.random() < 0.3:
            s["ends"] = {"length": rnd(200, 2000), "spacing": rnd(50, 200)}
        if R.random() < 0.3:
            s["hook"] = rnd(0, 120)
        p["stirrup"] = s
    if R.random() < 0.3:
        p["skin"] = {"diameter": R.choice([6.3, 8, 10]), "spacing": rnd(80, 300)}
    if R.random() < 0.3:
        a = {}
        if R.random() < 0.7: a["start"] = rnd(0, 500)
        if R.random() < 0.7: a["end"] = rnd(0, 500)
        p["anchor"] = a
    if R.random() < 0.15:
        p["clearance"] = rnd(5, 40)
    if R.random() < 0.1:
        p["grade"] = "CA-60"
    if R.random() < 0.1:
        p["grade_stirrup"] = "CA-25"
    cases.append('reinforce ' + json.dumps(p))
open('/tmp/rebar-agent/gb_%d.txt' % seed, 'w').write('@file %s\n' % out + '\n'.join(cases) + '\n')
print('ok', out, len(cases))

