keys = [k for k in data] if len(sys.argv) < 2 else [(sys.argv[1], int(sys.argv[2]))]
def norm3(v, how):
    if how == 'sqrt': l = math.sqrt(v[0]*v[0]+v[1]*v[1]+v[2]*v[2])
    elif how == 'hypot': l = math.hypot(math.hypot(v[0], v[1]), v[2])
    elif how == 'hypot3': l = math.hypot(v[0], v[1], v[2])
    return l
def cross(a, b):
    return [a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0]]
space = dict(L=['sqrt', 'hypot', 'hypot3'], al=['div', 'mulinv'], ac=['dv_sqrt', 'dv_hypot', 'al_unit_sqrt', 'al_unit_hypot', 'zxal_unit', 'zxal_raw'],
             up=['cross', 'ucross_sqrt', 'ucross_hypot'], pt=['lr', 'nest'])
results = {}
for combo in itertools.product(*space.values()):
    V = dict(zip(space, combo))
    ok = tot = 0
    for key in keys:
        e, elev, t, bars = data[key]
        w, h = t['width'], t['depth']
        s, en = e['start'], e['end']; off = e.get('offset', 0.0); eoff = e.get('end_offset', off); just = e.get('justify', 'top')
        dx = en[0]-s[0]; dy = en[1]-s[1]
        plan = math.sqrt(dx*dx+dy*dy); rz = eoff-off; length = math.sqrt(dx*dx+dy*dy+rz*rz)
        half = h/2.0*(length/plan)
        ch = lambda z: z - half if just == 'top' else (z if just == 'centre' else z + half)
        z0 = ch(elev+off); z1 = ch(elev+eoff)
        dv = [dx, dy, z1-z0]
        L = norm3(dv, V['L'])
        al = [dv[i]/L for i in range(3)] if V['al'] == 'div' else [dv[i]*(1.0/L) for i in range(3)]
        if V['ac'] == 'dv_sqrt':
            hz = math.sqrt(dx*dx+dy*dy); ac = [-dy/hz, dx/hz, 0.0]
        elif V['ac'] == 'dv_hypot':
            hz = math.hypot(dx, dy); ac = [-dy/hz, dx/hz, 0.0]
        elif V['ac'] == 'al_unit_sqrt':
            n = math.sqrt(al[0]*al[0]+al[1]*al[1]); ac = [-al[1]/n, al[0]/n, 0.0]
        elif V['ac'] == 'al_unit_hypot':
            n = math.hypot(al[0], al[1]); ac = [-al[1]/n, al[0]/n, 0.0]
        elif V['ac'] == 'zxal_unit':
            c = cross([0.0, 0.0, 1.0], al); n = math.sqrt(c[0]*c[0]+c[1]*c[1]+c[2]*c[2]); ac = [c[0]/n, c[1]/n, c[2]/n]
        else:
            ac = cross([0.0, 0.0, 1.0], al)
        up = cross(al, ac)
        if V['up'] == 'ucross_sqrt':
            n = math.sqrt(up[0]**2+up[1]**2+up[2]**2); up = [x/n for x in up]
        elif V['up'] == 'ucross_hypot':
            n = math.hypot(up[0], up[1], up[2]); up = [x/n for x in up]
        o = [s[0], s[1], z0 - elev]
        c = 30.0; hh = h/2; hw = w/2
        def at(tt, a, u):
            if V['pt'] == 'lr':
                return [o[i] + al[i]*tt + ac[i]*a + up[i]*u for i in range(3)]
            return [o[i] + (al[i]*tt + ac[i]*a + up[i]*u) for i in range(3)]
        exp = []
        for name, d, n in (('b', 12.5, 3), ('t', 6.3, 2)):
            a = hw - c - d/2
            ats = [-a + (2*a)*i/(n-1) for i in range(n)]
            u = -(hh - c - d/2) if name == 'b' else hh - c - d/2
            for aa in ats:
                exp.append([at(c, aa, u), at(L - c, aa, u)])
        for b, ex in zip(bars, exp):
            for p1, p2 in zip(b, ex):
                for x, y in zip(p1, p2):
                    tot += 1; ok += (x == y)
    results[tuple(combo)] = (ok, tot)
