        def axis_pt(tt):
            o = b['a0']
            if ap == 'oalt': return [o[i] + al[i]*tt for i in range(3)]
            if ap == 'lerp':
                f = tt / L
                return [o[i] * (1.0 - f) + b['a1'][i] * f for i in range(3)]
            if ap == 'dvfrac':
                f = tt / L
                return [o[i] + dv[i] * f for i in range(3)]
            if ap == 'dvfrac2':
