#!/usr/bin/env python3
"""Make random column projects with the original and random reinforce cases for them.
usage: gen_cols.py SEED NCASES -> /tmp/rebar-agent/gc_SEED.bimcraft and gc_SEED.txt"""
import sys, json, random, subprocess, os, tempfile, shutil, math
seed = int(sys.argv[1]); ncases = int(sys.argv[2])
R = random.Random(seed)
def rnd(a, b, nd=None):
    x = R.uniform(a, b)
    if nd is None: nd = R.choice([0, 0, 1, 2, 3])
    return round(x, nd)
cmds = []
cmds.append('level {"name":"LA","elevation":%s}' % rnd(-2000, 9000))
cmds.append('level {"name":"LB","elevation":%s}' % rnd(-2000, 9000))
rect, rnds = [], []
for i in range(3):
    w = rnd(200, 800); d = rnd(200, 900)
    name = 'C%d %s x %s' % (i, w, d)
    rect.append(name)
    cmds.append('type ' + json.dumps({"category": "structuralcolumn", "name": name, "width": w, "depth": d}))
for i in range(2):
    w = rnd(250, 800)
    name = 'R%d %s' % (i, w)
    rnds.append(name)
    cmds.append('type ' + json.dumps({"category": "structuralcolumn", "name": name, "width": w, "round": True}))
for i in range(8):
    c = {"at": [rnd(-5000, 5000), rnd(-5000, 5000)], "type": R.choice(rect + rnds + ["Concrete 300 x 300", "Concrete Round 400"]),
         "level": R.choice(["Level 1", "Level 2", "LA", "LB"])}
    if R.random() < 0.6: c["angle"] = rnd(-180, 180)
    if R.random() < 0.5: c["height"] = rnd(1500, 4500)
    if R.random() < 0.3: c["base_offset"] = rnd(-300, 300)
    cmds.append(R.choice(['structural_column ', 'column ']) + json.dumps(c))
d = tempfile.mkdtemp()
cl = ['/workspace/executable', 'run']
for c in cmds: cl += ['--cmd', c]
cl += ['--save', 'in.bimcraft']
p = subprocess.run(cl, cwd=d, capture_output=True, text=True)
if p.returncode != 0:
    print('build failed', p.stderr); sys.exit(1)
out = '/tmp/rebar-agent/gc_%d.bimcraft' % seed
shutil.copy(os.path.join(d, 'in.bimcraft'), out)
shutil.rmtree(d)
j = json.load(open(out))
cols = []
for k, v in j['elements'].items():
    if v['category'] in ('column', 'structuralcolumn'):
        cols.append(int(k))
types = {}
for sec in ('column', 'structural_column'):
    for n, t in j['types'][sec].items(): types[n] = t
def is_round(cid):
    e = j['elements'][str(cid)]
    tn = [v['name'] for v in j['library'].values() if v['guid'] == e['type']][0]
    return types[tn]['round']
cases = []
for i in range(ncases):
    cid = R.choice(cols)
    p = {"host": cid}
    if R.random() < 0.6:
        p["cover"] = R.choice([20, 25, 30, 40, rnd(15, 50)])
    else:
        p["cover"] = {"top": rnd(15, 50), "bottom": rnd(15, 50), "sides": rnd(15, 50)}
    if R.random() < 0.9:
        b = {"diameter": R.choice([10, 12.5, 16, 20, 25, rnd(8, 32)])}
        if is_round(cid):
            b["count"] = R.randint(3, 12)
        else:
            if R.random() < 0.8: b["x"] = R.randint(2, 5)
            if R.random() < 0.8: b["y"] = R.randint(2, 5)
        if R.random() < 0.3:
            b["hook"] = R.choice([rnd(0, 200), {"below": rnd(0, 200)}, {"above": rnd(0, 200)}, {"below": rnd(0, 200), "above": rnd(0, 200)}])
        if R.random() < 0.25:
            jg = {"by": rnd(5, 60), "from_top": rnd(300, 1200)}
            if R.random() < 0.4: jg["slope"] = rnd(1, 10)
            b["jog"] = jg
        p["bars"] = b
    if R.random() < 0.75:
        s = {"diameter": R.choice([5, 6.3, 8, rnd(4, 10)]), "spacing": R.choice([100, 150, 200, rnd(80, 400)])}
        if R.random() < 0.3:
            s["ends"] = {"length": rnd(200, 1200), "spacing": rnd(50, 200)}
        if R.random() < 0.3:
            s["hook"] = rnd(0, 120)
        p["stirrup"] = s
        if R.random() < 0.3 and not is_round(cid):
            t = {"diameter": R.choice([5, 6.3, 8])}
            if R.random() < 0.5: t["hook"] = rnd(0, 80)
            p["ties"] = t
    if R.random() < 0.25:
        a = {}
        if R.random() < 0.7: a["below"] = rnd(0, 800)
        if R.random() < 0.7: a["above"] = rnd(0, 800)
        p["anchor"] = a
    if R.random() < 0.15:
        p["clearance"] = rnd(5, 40)
    if R.random() < 0.1:
        p["grade_stirrup"] = "CA-60"
    cases.append('reinforce ' + json.dumps(p))
open('/tmp/rebar-agent/gc_%d.txt' % seed, 'w').write('@file %s\n' % out + '\n'.join(cases) + '\n')
print('ok', out, len(cases))

