"""A Python model of the original's column bars, with switchable arithmetic, compared to cached runs."""
import json, math, pickle, sys, itertools
sys.path.insert(0, '/tmp/rebar-agent')
import beam_lib as B
CACHE = {}
def load(f):
    if f not in CACHE: CACHE[f] = json.load(open(f))
    return CACHE[f]
def col_geom(j0, e):
    elev = [v for v in j0['elements'].values() if v['guid'] == e['level']][0]['elevation']
    tname = [v['name'] for v in j0['library'].values() if v['guid'] == e['type']][0]
    sec = 'structural_column' if e['category'] == 'structuralcolumn' else 'column'
    t = j0['types'][sec][tname]
    base = elev + e.get('base_offset', 0.0)
    if e.get('top_level'):
        top = [v for v in j0['elements'].values() if v['guid'] == e['top_level']][0]['elevation']
    else:
        top = base + e.get('height', 0.0)
    return elev, t, base, top
def spread(a, b, n):
    if n == 1: return [(a + b) / 2]
    return [a + (b - a) * i / (n - 1) for i in range(n)]
def stations(a, b, sp):
    n = max(1, math.ceil((b - a) / sp))
    return [a + (b - a) * i / n for i in range(n + 1)]
def legs(v):
    if v is None: return (0.0, 0.0)
    if isinstance(v, (int, float)): return (float(v), float(v))
    return (float(v.get('below') or 0.0), float(v.get('above') or 0.0))
def hooked(loop, hk):
    if not hk or hk <= 0: return loop
    c0 = loop[0]; c1 = loop[1]; cl = loop[-2]
    e1 = B.normalize([c1[i] - c0[i] for i in range(3)]); e2 = B.normalize([cl[i] - c0[i] for i in range(3)])
    dd = B.normalize([e1[i] + e2[i] for i in range(3)])
    tail = [c0[i] + dd[i] * hk for i in range(3)]
    return [tail] + loop + [tail]
def model(e, j0, p, V):
    elev, t, base, top = col_geom(j0, e)
    w = t['width']; dp = w if t['round'] else t['depth']; rnd = t['round']
    hw = w / 2; hd = dp / 2
    cv = p['cover']; ct, cb, cs = (cv['top'], cv['bottom'], cv['sides']) if isinstance(cv, dict) else (cv, cv, cv)
    stp = p.get('stirrup'); ds = stp['diameter'] if stp else 0.0
    H = top - base
    an = p.get('anchor') or {}
    t0 = -an['below'] if an.get('below') is not None else cb
    t1 = H + an['above'] if an.get('above') is not None else H - ct
    ang = e.get('angle', 0.0)
    if V['rad'] == 'rust': th = ang * (math.pi / 180.0)
    else: th = math.radians(ang)
    s, c = math.sin(th), math.cos(th)
    ac = [c, s, 0.0]
    if V['ac'] == 'norm': ac = B.normalize(ac)
    up = [-ac[1], ac[0], 0.0] if V['up'] == 'perp' else B.cross([0.0, 0.0, 1.0], ac)
    F = dict(o=[e['at'][0], e['at'][1], base - elev], al=[0.0, 0.0, 1.0], ac=ac, up=up)
    at = lambda tt, a, b: B.at(F, tt, a, b)
    out = []
    xin, yin = [], []
    bp = p.get('bars')
    if bp:
        d = bp['diameter']
        hs, he = legs(bp.get('hook'))
        jog = bp.get('jog')
        places = []
        if rnd:
            n = bp['count']; r = hw - cs - ds - d / 2
            for i in range(n):
                phi = 2 * math.pi * i / n if V['phi'] == 1 else (i * (2 * math.pi / n) if V['phi'] == 2 else math.tau * i / n)
                ps, pc = math.sin(phi), math.cos(phi)
                places.append(dict(a=r * pc, b=r * ps, leg=(-pc, -ps), jog=(-pc, -ps), r=r, pc=pc, ps=ps))
        else:
            nx = bp.get('x', 2); ny = bp.get('y', 2)
            a = hw - cs - ds - d / 2; b = hd - cs - ds - d / 2
            xs = spread(-a, a, nx); ys = spread(-b, b, ny)
            for sb, bb in ((-1.0, -b), (1.0, b)):
                for i, xa in enumerate(xs):
                    corner = i == 0 or i == nx - 1
                    sa = 1.0 if xa < 0 else -1.0
                    places.append(dict(a=xa, b=bb, leg=(0.0, -sb), jog=(sa, -sb) if corner else (0.0, -sb)))
            for sa, aa in ((1.0, -a), (-1.0, a)):
                for yb in ys[1:ny - 1]:
                    places.append(dict(a=aa, b=yb, leg=(sa, 0.0), jog=(sa, 0.0)))
            xin = xs[1:nx - 1]; yin = ys[1:ny - 1]
        for pl in places:
            path = []
            if hs > 0:
                if V['leg'] == 'add': path.append(at(t0, pl['a'] + pl['leg'][0] * hs, pl['b'] + pl['leg'][1] * hs))
                elif rnd: path.append(at(t0, (pl['r'] - hs) * pl['pc'], (pl['r'] - hs) * pl['ps']))
                else: path.append(at(t0, pl['a'] + pl['leg'][0] * hs, pl['b'] + pl['leg'][1] * hs))
            path.append(at(t0, pl['a'], pl['b']))
            ta, tb = pl['a'], pl['b']
            if jog:
                by = jog['by']; j0 = H - jog['from_top']; j1 = j0 + by * jog.get('slope', 6.0)
                if V['jog'] == 'add' or not rnd:
                    ja = pl['a'] + pl['jog'][0] * by; jb = pl['b'] + pl['jog'][1] * by
                else:
                    ja = (pl['r'] - by) * pl['pc']; jb = (pl['r'] - by) * pl['ps']
                path.append(at(j0, pl['a'], pl['b'])); path.append(at(j1, ja, jb))
                ta, tb = ja, jb
            path.append(at(t1, ta, tb))
            if he > 0:
                if V['leg'] == 'add' or not rnd: path.append(at(t1, ta + pl['leg'][0] * he, tb + pl['leg'][1] * he))
                else:
                    rr = (pl['r'] - (jog['by'] if jog else 0.0))
                    path.append(at(t1, (rr - he) * pl['pc'], (rr - he) * pl['ps']))
            out.append(path)
    if stp:
        s0 = cb + ds / 2; s1 = H - (cb * 0 + ct + ds / 2)
        sp = stp['spacing']; ends = stp.get('ends')
        if ends:
            l = ends['length']; esp = ends['spacing']; a_ = s0 + l; b_ = s1 - l
            if b_ - a_ > 1.0:
                ts = stations(s0, a_, esp) + stations(a_, b_, sp)[1:-1] + stations(b_, s1, esp)
            else:
                ts = stations(s0, s1, min(esp, sp))
        else:
            ts = stations(s0, s1, sp)
        tie = p.get('ties')
        if V['sb'] == 'in': sb_ = (hd - cs - ds) + ds / 2
        else: sb_ = hd - cs - ds / 2
        if V['sa'] == 'in': sa_ = (hw - cs - ds) + ds / 2
        else: sa_ = hw - cs - ds / 2
        ia = hw - cs - ds; ib = hd - cs - ds
        for tt in ts:
            if rnd:
                rs = hw - cs - ds / 2
                loop = []
                for k in range(24):
                    phi = 2 * math.pi * k / 24 if V['phi'] == 1 else (k * (2 * math.pi / 24) if V['phi'] == 2 else math.tau * k / 24)
                    loop.append(at(tt, rs * math.cos(phi), rs * math.sin(phi)))
                loop.append(loop[0])
            else:
                c0 = at(tt, -sa_, sb_)
                loop = [c0, at(tt, sa_, sb_), at(tt, sa_, -sb_), at(tt, -sa_, -sb_), c0]
            out.append(hooked(loop, stp.get('hook')))
            if tie:
                th_ = tie.get('hook') or 0.0
                k = 0.7071067811865476
                for xa in xin:
                    path = []
                    if th_ > 0: path.append(at(tt, xa + th_ * k, -ib + th_ * k))
                    path += [at(tt, xa, -ib), at(tt, xa, ib)]
                    if th_ > 0: path.append(at(tt, xa - th_ * k, ib - th_ * k))
                    out.append(path)
                for yb in yin:
                    path = []
                    if th_ > 0: path.append(at(tt, -ia + th_ * k, yb + th_ * k))
                    path += [at(tt, -ia, yb), at(tt, ia, yb)]
                    if th_ > 0: path.append(at(tt, ia - th_ * k, yb - th_ * k))
                    out.append(path)
    return out
def compare(V, results, filt=None):
    ok = tot = 0
    stats = {}
    for f, line, res in results:
        if res['stderr'] or 'bars' not in res: continue
        p = json.loads(line.split(' ', 1)[1])
        j0 = load(f); e = j0['elements'][str(p['host'])]
        try:
            mine = model(e, j0, p, V)
        except Exception as ex:
            mine = None
        orig = [b['path'] for b in res['bars']]
        tot += 1
        if mine == orig: ok += 1
        elif mine and len(mine) == len(orig):
            for bi, (mb, ob) in enumerate(zip(mine, orig)):
                if mb != ob:
                    lay = res['bars'][bi].get('layer')
                    if len(mb) != len(ob): k = (lay, 'npts')
                    else:
                        k = None
                        for pi, (p1, p2) in enumerate(zip(mb, ob)):
                            for kk in range(3):
                                if p1[kk] != p2[kk] and k is None: k = (lay, pi, kk)
                    stats[k] = stats.get(k, 0) + 1
                    break
        else:
            stats['count'] = stats.get('count', 0) + 1
    return ok, tot, stats
if __name__ == '__main__':
    results = pickle.load(open(sys.argv[1], 'rb'))
    space = dict(rad=['rust', 'py'], ac=['raw', 'norm'], up=['perp', 'cross'], phi=[1, 2, 3], leg=['add', 'radial'], jog=['add', 'radial'], sb=['in', 'out'], sa=['in', 'out'])
    best = []
    for combo in itertools.product(*space.values()):
        V = dict(zip(space, combo))
        ok, tot, st = compare(V, results)
        best.append((ok, tot, V, st))
    best.sort(key=lambda r: -r[0])
    for r in best[:8]:
        print(r[0], r[1], r[2])
    print(sorted(best[0][3].items(), key=lambda kv: -kv[1])[:20])

