#!/usr/bin/env python3
"""Random footing projects (built with the original) and reinforce cases.
usage: gen_foot.py SEED NCASES -> /tmp/rebar-agent/gf_SEED.bimcraft and gf_SEED.txt"""
import sys, json, random, subprocess, os, tempfile, shutil
seed = int(sys.argv[1]); ncases = int(sys.argv[2])
R = random.Random(seed)
def rnd(a, b, nd=None):
    x = R.uniform(a, b)
    if nd is None: nd = R.choice([0, 0, 1, 2, 3])
    return round(x, nd)
cmds = ['level {"name":"LA","elevation":%s}' % rnd(-3000, 3000)]
names = []
for i in range(3):
    w = rnd(600, 3000); d = rnd(600, 3000)
    n = 'F%d %s x %s' % (i, w, d); names.append(n)
    cmds.append('type ' + json.dumps({"category": "footing", "name": n, "width": w, "depth": d}))
for i in range(2):
    w = rnd(600, 3000)
    n = 'FR%d %s' % (i, w); names.append(n)
    cmds.append('type ' + json.dumps({"category": "footing", "name": n, "width": w, "round": True}))
for i in range(8):
    f = {"at": [rnd(-5000, 5000), rnd(-5000, 5000)], "type": R.choice(names + ["Footing 1200 x 1200"]), "level": R.choice(["Level 1", "Level 2", "LA"])}
    if R.random() < 0.6: f["angle"] = rnd(-180, 180)
    if R.random() < 0.6: f["thickness"] = rnd(250, 1200)
    if R.random() < 0.5: f["offset"] = rnd(-800, 300)
    cmds.append('footing ' + json.dumps(f))
d = tempfile.mkdtemp()
cl = ['/workspace/executable', 'run']
for c in cmds: cl += ['--cmd', c]
cl += ['--save', 'in.bimcraft']
p = subprocess.run(cl, cwd=d, capture_output=True, text=True)
if p.returncode != 0:
    print('build failed', p.stderr); sys.exit(1)
out = '/tmp/rebar-agent/gf_%d.bimcraft' % seed
shutil.copy(os.path.join(d, 'in.bimcraft'), out); shutil.rmtree(d)
j = json.load(open(out))
fts = [int(k) for k, v in j['elements'].items() if v['category'] == 'footing']
cases = []
for i in range(ncases):
    p = {"host": R.choice(fts)}
    if R.random() < 0.6: p["cover"] = R.choice([30, 40, 50, 75, rnd(20, 80)])
    else: p["cover"] = {"top": rnd(20, 80), "bottom": rnd(20, 80), "sides": rnd(20, 80)}
    m = {}
    if R.random() < 0.85: m["x"] = {"diameter": R.choice([8, 10, 12.5, 16, 20, rnd(6, 25)]), "spacing": R.choice([100, 150, 200, rnd(60, 400)])}
    if R.random() < 0.7: m["y"] = {"diameter": R.choice([8, 10, 12.5, 16, 20, rnd(6, 25)]), "spacing": R.choice([100, 150, 200, rnd(60, 400)])}
    if R.random() < 0.4: m["hook"] = rnd(0, 300)
    p["mesh"] = m
    if R.random() < 0.15: p["clearance"] = rnd(5, 40)
    if R.random() < 0.1: p["grade"] = "CA-60"
    cases.append('reinforce ' + json.dumps(p))
open('/tmp/rebar-agent/gf_%d.txt' % seed, 'w').write('@file %s\n' % out + '\n'.join(cases) + '\n')
print('ok', out, len(cases))

