                                        v1 = fz(zt - elev); v2 = fz(zt) - elev
                                        cands[(un, tn_n, z0n, cn, zn, fn, 'e1')] = v1
                                        cands[(un, tn_n, z0n, cn, zn, fn, 'e2')] = v2
                                    else:
                                        cands[(un, tn_n, z0n, cn, zn, fn, '-')] = fz(zt)
            for k, v in cands.items():
                sc_ = score.setdefault(k, [0, 0]); sc_[1] += 1; sc_[0] += (v == z)
