     NOTE NBR 6118 7.4.7.2: the footing's sides cover of 40 mm is under the 50 mm that Table 7.2 gives for class IV
CASE reinforce {"host":100002,"cover":40,"mesh":{"x":{"diameter":10,"spacing":300},"y":{"diameter":5,"spacing":400}},"check":"NBR 6118","fck":40}
     (no notes)
CASE reinforce {"host":100002,"cover":40,"mesh":{"x":{"diameter":100,"spacing":300}},"check":"NBR 6118","fck":20}
