1	//! `reinforce`: bars by rules for beams, columns, footings and floors. The engineer says how many
2	//! bars, how thick and how far apart; this lays them out in the host's own frame inside the
3	//! cover and checks that what is asked fits, saying what to change. Each bar is a `rebar`
4	//! element of the host on a `layer`; reinforcing again replaces the bars that have a layer and
5	//! leaves the ones drawn by hand.
6	//!
7	//! The order the original reads and checks things in (the first that fails is the refusal): the
8	//! `preset` (its parameters, given ones replacing them key by key), the hosts (each element,
9	//! then each one's level), the preset's kind against each host, `grade`, `grade_stirrup` and
10	//! `clearance`, the `check` (`aggressiveness`, `check`, `fck`), and then host by host (a refusal
11	//! naming the host where there are several) its cover, its kind and what its kind takes.
12	
13	pub mod beam;
14	pub mod column;
15	pub mod de;
16	pub mod floor;
17	pub mod footing;
18	pub mod geom;
19	pub mod norm;
20	pub mod shapes;
21	pub mod stir;
22	
23	use crate::commands::params::get;
24	use crate::json::{Map, Value};
25	use crate::project::Project;
26	use crate::session::Session;
27	use crate::structure::common::{add_element, R};
28	use crate::structure::rebar::{self, read_ref, resolve_ref, ElemRef, MAX_BARS, MAX_BARS_ALL, MAX_HOSTS};
29	use geom::V3;
30	
31	const CMD: &str = "reinforce";
32	
33	/// The most a length may be, mm.
34	pub const MAX_MM: f64 = 1e9;
35	/// The thinnest and thickest bar.
36	pub const MIN_D: f64 = 3.0;
37	pub const MAX_D: f64 = 100.0;
38	/// The most bars in a row, or of a column's face.
39	pub const MAX_COUNT: u64 = 1000;
40	
41	/// A bar laid out: its path (heights over the host's level), diameter, grade and layer.
42	#[derive(Clone, Debug)]
43	pub struct Bar {
44	    pub path: Vec<V3>,
45	    pub diameter: f64,
46	    pub grade: String,
47	    pub layer: String,
48	}
49	
50	/// A host being armed.
51	pub struct Host {
52	    pub id: u64,
53	    pub cat: String,
54	    pub level: u64,
55	    pub elevation: f64,
56	}
57	
58	/// `grade`, `grade_stirrup` and `clearance`, read once for all hosts.
59	pub struct Common {
60	    pub grade: String,
61	    pub grade_stirrup: String,
62	    pub clearance: Option<f64>,
63	}
64	
65	impl Common {
66	    /// The least gap between bars of these diameters: the one given, else the thickest of them
67	    /// and at least 20 mm.
68	    pub fn clearance_for(&self, ds: &[f64]) -> f64 {
69	        match self.clearance {
70	            Some(c) => c,
71	            None => ds.iter().fold(20.0f64, |a, b| a.max(*b)),
72	        }
73	    }
74	}
75	
76	/// The cover of each face, mm.
77	#[derive(Clone, Copy, Debug)]
78	pub struct Cover {
79	    pub top: f64,
80	    pub bottom: f64,
81	    pub sides: f64,
82	}
83	
84	/// What arming one host needs.
85	pub struct Ctx<'a> {
86	    pub pr: &'a Project,
87	    pub host: &'a Host,
88	    pub e: &'a Value,
89	    pub params: &'a Map,
90	    pub common: &'a Common,
91	    pub cover: Cover,
92	}
93	
94	/// What a host is armed with: its bars, and what the check reads of them.
95	pub struct Armed {
96	    pub bars: Vec<Bar>,
97	    pub info: norm::Info,
98	}
99	
100	/// The `check` asked for: the aggressiveness class and the concrete's strength.
101	#[derive(Clone, Copy, Debug)]
102	pub struct Check {
103	    pub aggressiveness: Option<u64>,
104	    pub fck: Option<f64>,
105	}
106	
107	/// The kind of host a category is, as presets name them.
108	pub fn kind_of(cat: &str) -> &str {
109	    match cat {
110	        "beam" => "beam",
111	        "column" | "structuralcolumn" => "column",
112	        "footing" => "footing",
113	        "floor" => "floor",
114	        other => other,
115	    }
116	}
117	
118	fn err(msg: String) -> String {
119	    format!("{}: {}", CMD, msg)
120	}
121	
122	/// A length a parameter gives: a number over 0 and up to 1000 km.
123	pub fn positive(what: &str, x: f64) -> R<f64> {
124	    if x > 0.0 && x <= MAX_MM {
125	        Ok(x)
126	    } else {
127	        Err(format!("`{}` must be over 0 and up to 1000000000 mm, got {}", what, x))
128	    }
129	}
130	
131	/// A length a parameter gives that may be 0: up to 1000 km.
132	pub fn not_negative(what: &str, x: f64) -> R<f64> {
133	    if x >= 0.0 && x <= MAX_MM {
134	        Ok(x)
135	    } else {
136	        Err(format!("`{}` {} mm must be 0 or more, up to 1000000000", what, x))
137	    }
138	}
139	
140	/// A bar's diameter: 3 to 100 mm.
141	pub fn diameter(what: &str, d: f64) -> R<f64> {
142	    if (MIN_D..=MAX_D).contains(&d) {
143	        Ok(d)
144	    } else {
145	        Err(format!("`{}` diameter {} mm isn't between 3 and 100 mm", what, d))
146	    }
147	}
148	
149	/// A spacing of bars of a diameter: more than the diameter, up to 1000 km.
150	pub fn spacing(what: &str, s: f64, d: f64) -> R<f64> {
151	    if s > d && s <= MAX_MM {
152	        Ok(s)
153	    } else {
154	        Err(format!("`{}` spacing {} mm must be more than the {} mm diameter, and up to 1000000000", what, s, d))
155	    }
156	}
157	
158	/// A count of bars: 1 to 1000.
159	pub fn count(what: &str, n: u64) -> R<usize> {
160	    if (1..=MAX_COUNT).contains(&n) {
161	        Ok(n as usize)
162	    } else {
163	        Err(format!("`{}` count {} isn't 1 to 1000", what, n))
164	    }
165	}
166	
167	/// The value of one of the host's parameters by its name, where it is a number.
168	fn host_param(pr: &Project, e: &Value, name: &str) -> Option<f64> {
169	    let ps = e.get("params")?.as_obj()?;
170	    for (k, v) in ps.iter() {
171	        if crate::styles::parameters::param_of_key(pr, k).as_deref() == Some(name) {
172	            if let Some(x) = v.as_f64() {
173	                return Some(x);
174	            }
175	        }
176	    }
177	    None
178	}
179	
180	/// The cover of each face: what `cover` says (a number for all, or {top, bottom, sides}), else
181	/// the host's `Cobrimento` or `ConcreteCover` parameter; face by face.
182	fn read_cover(pr: &Project, e: &Value, params: &Map) -> R<Cover> {
183	    let faces: [Option<f64>; 3] = match params.get("cover") {
184	        None | Some(Value::Null) => [None, None, None],
185	        Some(Value::Num(n)) => {
186	            let x = n.as_f64();
187	            [Some(x), Some(x), Some(x)]
188	        }
189	        Some(v) => match de::de_struct(v, &shapes::FACES) {
190	            Ok(m) => [de::f(&m, "top"), de::f(&m, "bottom"), de::f(&m, "sides")],
191	            Err(_) => return Err("`cover`: data did not match any variant of untagged enum CoverArg".into()),
192	        },
193	    };
194	    let fallback = host_param(pr, e, "Cobrimento").or_else(|| host_param(pr, e, "ConcreteCover"));
195	    let mut out = [0.0; 3];
196	    for (i, name) in ["top", "bottom", "sides"].iter().enumerate() {
197	        let x = match faces[i].or(fallback) {
198	            Some(x) => x,
199	            None => {
200	                return Err(format!(
201	                    "no cover for the {}: give `cover` in mm (a number, or top, bottom and sides), or give the host a Cobrimento parameter",
202	                    name
203	                ))
204	            }
205	        };
206	        out[i] = positive("cover", x)?;
207	    }
208	    Ok(Cover { top: out[0], bottom: out[1], sides: out[2] })
209	}
210	
211	/// The parameters of a kind, as the "isn't a parameter" refusal lists them.
212	fn kind_params(kind: &str) -> &'static [&'static str] {
213	    match kind {
214	        "beam" => &["cover", "grade", "grade_stirrup", "clearance", "bottom", "top", "stirrup", "skin", "anchor"],
215	        "column" => &["cover", "grade", "grade_stirrup", "clearance", "bars", "stirrup", "ties", "anchor"],
216	        "footing" => &["cover", "grade", "clearance", "mesh"],
217	        "floor" => &["cover", "grade", "clearance", "bottom", "top"],
218	        _ => &[],
219	    }
220	}
221	
222	/// What every command takes whatever the host.
223	const GENERAL: &[&str] = &["host", "hosts", "check", "aggressiveness", "fck"];
224	
225	/// Refuses a key the host's kind doesn't take (the first in sorted order).
226	pub fn check_keys(params: &Map, kind: &str) -> R<()> {
227	    let allowed = kind_params(kind);
228	    let mut keys: Vec<&String> = params.keys().collect();
229	    keys.sort();
230	    for k in keys {
231	        if GENERAL.contains(&k.as_str()) || allowed.contains(&k.as_str()) {
232	            continue;
233	        }
234	        if kind == "footing" && k == "grade_stirrup" {
235	            continue;
236	        }
237	        if kind == "floor" && k == "grade_stirrup" {
238	            continue;
239	        }
240	        let list = allowed.to_vec();
241	        let (last, rest) = list.split_last().unwrap();
242	        return Err(format!("`{}` isn't a parameter of a {}; it takes {} and {}", k, kind, rest.join(", "), last));
243	    }
244	    Ok(())
245	}
246	
247	/// One of a kind's parameters read as its serde type: None when left out or null.
248	pub fn read_struct(params: &Map, key: &str, shape: &de::Shape) -> R<Option<Map>> {
249	    match params.get(key) {
250	        None | Some(Value::Null) => Ok(None),
251	        Some(v) => de::de_struct(v, shape).map(Some).map_err(|e| format!("`{}`: {}", key, e)),
252	    }
253	}
254	
255	fn read_hosts(pr: &Project, params: &Map) -> R<Vec<u64>> {
256	    let host = params.get("host").filter(|v| !v.is_null());
257	    let hosts = params.get("hosts").filter(|v| !v.is_null());
258	    let ids: Vec<u64> = match (host, hosts) {
259	        (Some(_), Some(_)) => return Err(err("give `host` or `hosts`, not both".into())),
260	        (None, None) => return Err(err("`host` (an element) or `hosts` (a list of them) is required".into())),
261	        (Some(v), None) => {
262	            let r = read_ref(v)
263	                .ok_or_else(|| err(format!("`host` must be an element id or GUID, got {}", v.to_compact())))?;
264	            vec![resolve_ref(pr, &r).ok_or_else(|| err(format!("no element {}", r.text())))?]
265	        }
266	        (None, Some(v)) => {
267	            let a = match v.as_arr() {
268	                Some(a) if !a.is_empty() && a.len() <= MAX_HOSTS => a,
269	                _ => return Err(err("`hosts` is a list of 1 to 1000 elements".into())),
270	            };
271	            let mut out = Vec::with_capacity(a.len());
272	            for x in a {
273	                let r: ElemRef =
274	                    read_ref(x).ok_or_else(|| err(format!("{} is not an element id or GUID", x.to_compact())))?;
275	                out.push(resolve_ref(pr, &r).ok_or_else(|| err(format!("no element {}", r.text())))?);
276	            }
277	            out
278	        }
279	    };
280	    let mut seen: Vec<u64> = Vec::with_capacity(ids.len());
281	    for id in ids {
282	        if !seen.contains(&id) {
283	            seen.push(id);
284	        }
285	    }
286	    Ok(seen)
287	}
