362	/// Arms one host: its cover, its kind, and its kind's bars.
363	fn arm(pr: &Project, host: &Host, params: &Map, common: &Common) -> R<Armed> {
364	    let e = pr.el(host.id).ok_or_else(|| format!("no element {}", host.id))?;
365	    let cover = read_cover(pr, e, params)?;
366	    let ctx = Ctx { pr, host, e, params, common, cover };
367	    match host.cat.as_str() {
368	        "beam" => beam::arm(&ctx),
369	        "column" | "structuralcolumn" => column::arm(&ctx),
370	        "footing" => footing::arm(&ctx),
371	        "floor" => floor::arm(&ctx),
372	        other => Err(format!("a {} can't be armed: a beam, a column, a footing or a floor can", other)),
373	    }
374	}
