376	pub fn run(s: &mut Session, cid: &str, p0: &Value) -> R<Value> {
377	    let _ = cid;
378	    let p = crate::structure::types::names_for_guids(&s.project, p0);
379	    let pr = &s.project;
380	    let mut params: Map = p.as_obj().cloned().unwrap_or_default();
381	    // the preset's parameters, those given replacing them key by key
382	    let mut preset: Option<(String, String)> = None;
383	    match get(&p, "preset") {
384	        None => {}
385	        Some(Value::Str(name)) if name.chars().count() <= 256 => {
386	            let e = pr
387	                .section(crate::styles::presets::SECTION)
388	                .and_then(|m| m.get(name))
389	                .ok_or_else(|| err(format!("there's no reinforcement preset `{}`", name)))?;
390	            let kind = e.get("kind").and_then(|k| k.as_str()).unwrap_or("").to_string();
391	            let mut merged = e.get("params").and_then(|x| x.as_obj()).cloned().unwrap_or_default();
392	            for (k, v) in params.items.iter() {
393	                if k != "preset" {
394	                    merged.insert(k, v.clone());
395	                }
396	            }
397	            params = merged;
398	            preset = Some((name.clone(), kind));
399	        }
400	        Some(v) => {
401	            return Err(err(format!("`preset` must be text of at most 256 characters, got {}", v.to_compact())))
402	        }
403	    }
404	    let ids = read_hosts(pr, &params)?;
405	    let mut hosts: Vec<Host> = Vec::with_capacity(ids.len());
406	    for id in &ids {
407	        let e = &pr.elements[id];
408	        let level = rebar::level_of(pr, e).ok_or_else(|| err("that element has no level".into()))?;
409	        let elevation = pr.el(level).and_then(|l| l.get("elevation")).and_then(|x| x.as_f64()).unwrap_or(0.0);
410	        let cat = e.get("category").and_then(|c| c.as_str()).unwrap_or("").to_string();
411	        hosts.push(Host { id: *id, cat, level, elevation });
412	    }
413	    if let Some((name, kind)) = &preset {
414	        for h in &hosts {
415	            if kind_of(&h.cat) != kind.as_str() {
416	                return Err(err(format!("preset `{}` is for a {}, and {} is a {}", name, kind, h.id, h.cat)));
417	            }
418	        }
419	    }
420	    let common = read_common(&params)?;
421	    let check = read_check(&params)?;
422	    let many = hosts.len() > 1;
423	    let mut armed: Vec<Armed> = Vec::with_capacity(hosts.len());
424	    let mut total = 0usize;
425	    for h in &hosts {
426	        let a = arm(pr, h, &params, &common).map_err(|e| {
427	            if many {
428	                err(format!("{} (for the {} {})", e, h.cat, h.id))
429	            } else {
430	                err(e)
431	            }
432	        })?;
433	        total += a.bars.len();
434	        if total > MAX_BARS_ALL {
435	            return Err(err(format!(
436	                "that is more than the {} bars a command makes for all its hosts: widen a spacing or arm fewer hosts",
437	                MAX_BARS_ALL
438	            )));
439	        }
440	        armed.push(a);
441	    }
442	    let mut notes: Vec<Value> = Vec::new();
443	    if let Some(c) = &check {
444	        for (h, a) in hosts.iter().zip(armed.iter()) {
445	            for n in norm::notes(pr, h, &a.info, c) {
446	                notes.push(Value::s(&if many { format!("{} {}: {}", h.cat, h.id, n) } else { n }));
447	            }
448	        }
449	    }
450	    // the bars made before by this command (those on a layer) go
451	    let mut old: Vec<u64> = Vec::new();
452	    for h in &hosts {
453	        let g = pr.guid_of(h.id).unwrap_or_default();
454	        old.extend(rebar::bars_of_host(pr, &g).into_iter().filter(|b| {
455	            pr.el(*b).and_then(|e| e.get("layer")).and_then(|l| l.as_str()).map(|l| !l.is_empty()).unwrap_or(false)
456	        }));
457	    }
458	    let removed = old.len();
459	    for b in old {
460	        s.project.elements.remove(&b);
461	    }
462	    let mut out_ids: Vec<Value> = Vec::new();
463	    let mut weight = 0.0;
464	    for (h, a) in hosts.iter().zip(armed.into_iter()) {
465	        let level_guid = s.project.guid_of(h.level).unwrap_or_default();
466	        let host_guid = s.project.guid_of(h.id).map(|g| crate::structure::members::read::norm_ref(&g));
467	        for b in a.bars {
468	            let path: Vec<[f64; 3]> = b.path.clone();
469	            weight += rebar::weight_kg(b.diameter, rebar::length(&path));
470	            let e = rebar::bar_json(&level_guid, host_guid.as_deref(), &path, b.diameter, &b.grade, Some(&b.layer));
471	            out_ids.push(Value::u(add_element(s, e)));
472	        }
473	    }
474	    let _ = MAX_BARS;
475	    Ok(crate::jobj! {
476	        "count" => out_ids.len(),
477	        "hosts" => hosts.len(),
478	        "ids" => Value::Arr(out_ids),
479	        "notes" => Value::Arr(notes),
480	        "removed" => removed,
481	        "weight_kg" => rebar::round3(weight),
482	    })
483	}
