255	fn read_hosts(pr: &Project, params: &Map) -> R<Vec<u64>> {
256	    let host = params.get("host").filter(|v| !v.is_null());
257	    let hosts = params.get("hosts").filter(|v| !v.is_null());
258	    let ids: Vec<u64> = match (host, hosts) {
259	        (Some(_), Some(_)) => return Err(err("give `host` or `hosts`, not both".into())),
260	        (None, None) => return Err(err("`host` (an element) or `hosts` (a list of them) is required".into())),
261	        (Some(v), None) => {
262	            let r = read_ref(v)
263	                .ok_or_else(|| err(format!("`host` must be an element id or GUID, got {}", v.to_compact())))?;
264	            vec![resolve_ref(pr, &r).ok_or_else(|| err(format!("no element {}", r.text())))?]
265	        }
266	        (None, Some(v)) => {
267	            let a = match v.as_arr() {
268	                Some(a) if !a.is_empty() && a.len() <= MAX_HOSTS => a,
269	                _ => return Err(err("`hosts` is a list of 1 to 1000 elements".into())),
270	            };
271	            let mut out = Vec::with_capacity(a.len());
272	            for x in a {
273	                let r: ElemRef =
274	                    read_ref(x).ok_or_else(|| err(format!("{} is not an element id or GUID", x.to_compact())))?;
275	                out.push(resolve_ref(pr, &r).ok_or_else(|| err(format!("no element {}", r.text())))?);
276	            }
277	            out
278	        }
279	    };
280	    let mut seen: Vec<u64> = Vec::with_capacity(ids.len());
281	    for id in ids {
282	        if !seen.contains(&id) {
283	            seen.push(id);
284	        }
285	    }
286	    Ok(seen)
287	}
