289	fn read_common(params: &Map) -> R<Common> {
290	    let text = |key: &str| -> R<Option<String>> {
291	        match params.get(key) {
292	            None | Some(Value::Null) => Ok(None),
293	            Some(v) => Ok(Some(de::de_str(v).map_err(|e| err(format!("`{}`: {}", key, e)))?)),
294	        }
295	    };
296	    let grade = text("grade")?;
297	    let grade_stirrup = text("grade_stirrup")?;
298	    for g in [&grade, &grade_stirrup].into_iter().flatten() {
299	        if g.trim().is_empty() {
300	            return Err(err("a `grade` can't be blank".into()));
301	        }
302	    }
303	    let grade = grade.unwrap_or_else(|| rebar::DEFAULT_GRADE.to_string());
304	    let grade_stirrup = grade_stirrup.unwrap_or_else(|| grade.clone());
305	    let clearance = match params.get("clearance") {
306	        None | Some(Value::Null) => None,
307	        Some(v) => {
308	            let c = de::de_f64(v).map_err(|e| err(format!("`clearance`: {}", e)))?;
309	            Some(positive("clearance", c).map_err(err)?)
310	        }
311	    };
312	    Ok(Common { grade, grade_stirrup, clearance })
