315	/// Whether a `check` names NBR 6118 (its letters and digits, in any case, begin so).
316	fn is_nbr(s: &str) -> bool {
317	    let t: String = s.chars().filter(|c| c.is_alphanumeric()).flat_map(|c| c.to_lowercase()).collect();
318	    t.starts_with("nbr6118")
319	}
