321	fn read_check(params: &Map) -> R<Option<Check>> {
322	    let field = |key: &str| params.get(key).filter(|v| !v.is_null());
323	    let aggressiveness = match field("aggressiveness") {
324	        None => None,
325	        Some(v) => Some(de::de_u8(v).map_err(|e| err(format!("`aggressiveness`: {}", e)))?),
326	    };
327	    let check = match field("check") {
328	        None => None,
329	        Some(v) => Some(de::de_str(v).map_err(|e| err(format!("`check`: {}", e)))?),
330	    };
331	    let fck = match field("fck") {
332	        None => None,
333	        Some(v) => Some(de::de_f64(v).map_err(|e| err(format!("`fck`: {}", e)))?),
334	    };
335	    if let Some(c) = &check {
336	        if !is_nbr(c) {
337	            return Err(err(format!(
338	                "`check` {} isn't one this knows: it is \"NBR 6118\"",
339	                Value::s(c).to_compact()
340	            )));
341	        }
342	    }
343	    if check.is_none() {
344	        if aggressiveness.is_some() || fck.is_some() {
345	            return Err(err("`aggressiveness` and `fck` go with `check`: give `check` \"NBR 6118\"".into()));
346	        }
347	        return Ok(None);
348	    }
349	    if let Some(a) = aggressiveness {
350	        if !(1..=4).contains(&a) {
351	            return Err(err("`aggressiveness` is the class 1 to 4 (I to IV)".into()));
352	        }
353	    }
354	    if let Some(f) = fck {
355	        if !(10.0..=100.0).contains(&f) {
356	            return Err(err("`fck` is the concrete's strength in MPa, 10 to 100".into()));
357	        }
358	    }
359	    Ok(Some(Check { aggressiveness, fck }))
360	}
