1	//! A beam's bars: `bottom` and `top` rows (hooks; some bottom bars bent up), `stirrup`s (closer
2	//! at the ends, hooked), `skin` bars up each side, `anchor`s past the ends. Laid out in the
3	//! beam's frame: along its centre line from its start, across it (level, to the left), up
4	//! square to both; its section's centre at the origin.
5	
6	use super::de::{self, any, f, sub, u};
7	use super::geom::{gaps, spread, unit, Frame, TOL};
8	use super::shapes::{BEAM_ANCHOR, PITCH, ROW, STIRRUP};
9	use super::{check_keys, count, diameter, norm, not_negative, positive, read_struct, spacing, stir, Armed, Bar, Ctx};
10	use crate::json::{Map, Value};
11	use crate::structure::common::R;
12	use crate::structure::members::geom::run_geom;
13	use crate::structure::rebar::MAX_BARS;
14	
15	/// A row's hooks at the start and at the end, read from `hook`: a length for both, or
16	/// {start, end}.
17	pub fn legs(what: &str, ends: (&str, &str), v: Option<&Value>) -> R<(f64, f64)> {
18	    let bad = || format!("`{}` must be a length in mm, or {{{}, {}}}", what, ends.0, ends.1);
19	    match v {
20	        None | Some(Value::Null) => Ok((0.0, 0.0)),
21	        Some(Value::Num(n)) => {
22	            let x = not_negative(what, n.as_f64())?;
23	            Ok((x, x))
24	        }
25	        Some(Value::Obj(m)) => {
26	            let mut a = 0.0;
27	            let mut b = 0.0;
28	            for (k, x) in m.iter() {
29	                let val = match x {
30	                    Value::Null => 0.0,
31	                    Value::Num(n) => n.as_f64(),
32	                    _ => return Err(bad()),
33	                };
34	                if k == ends.0 {
35	                    a = val;
36	                } else if k == ends.1 {
37	                    b = val;
38	                } else {
39	                    return Err(bad());
40	                }
41	            }
42	            let a = not_negative(&format!("{} {}", what, ends.0), a)?;
43	            let b = not_negative(&format!("{} {}", what, ends.1), b)?;
44	            Ok((a, b))
45	        }
46	        Some(_) => Err(bad()),
47	    }
48	}
