50	/// The bars a row's `bent` takes: `k` of the `m` inner ones, evenly (indices into the inner).
51	pub fn picks(m: usize, k: usize) -> Vec<usize> {
52	    if k == 0 || m == 0 {
53	        return Vec::new();
54	    }
55	    if k == 1 {
56	        return vec![(m - 1) / 2];
57	    }
58	    (0..k).map(|i| ((i as f64) * ((m - 1) as f64) / ((k - 1) as f64)).round() as usize).collect()
59	}
