74	pub fn arm(ctx: &Ctx) -> R<Armed> {
75	    let pr = ctx.pr;
76	    let g = run_geom(pr, ctx.e).ok_or_else(|| "the beam has no section".to_string())?;
77	    if g.section.round {
78	        return Err("a round beam isn't reinforced yet; a rectangular one is".into());
79	    }
80	    let params = ctx.params;
81	    let bottom = read_struct(params, "bottom", &ROW)?;
82	    let top = read_struct(params, "top", &ROW)?;
83	    let stirrup = read_struct(params, "stirrup", &STIRRUP)?;
84	    let skin = read_struct(params, "skin", &PITCH)?;
85	    let anchor = read_struct(params, "anchor", &BEAM_ANCHOR)?;
86	    check_keys(params, "beam")?;
87	    if bottom.is_none() && top.is_none() && stirrup.is_none() {
88	        return Err("nothing to reinforce with: give `bottom` or `top` bars, or a `stirrup`".into());
89	    }
90	    let cv = ctx.cover;
91	    let ds = match &stirrup {
92	        Some(m) => diameter("stirrup", f(m, "diameter").unwrap_or(0.0))?,
93	        None => 0.0,
94	    };
95	    let w = g.section.width;
96	    let h = g.section.depth;
97	    let hw = w / 2.0;
98	    let hh = h / 2.0;
99	    let inner_w = w - 2.0 * cv.sides - 2.0 * ds;
100	    let inner_h = h - cv.top - cv.bottom - 2.0 * ds;
101	    if inner_w <= 0.0 || inner_h <= 0.0 {
102	        return Err("the section is too narrow or too shallow for that cover and stirrup".into());
103	    }
104	    // the box inside the stirrup: across its sides, up to its top and down to its bottom
105	    let a_in = hw - cv.sides - ds;
106	    let top_in = hh - cv.top - ds;
107	    let bot_in = -(hh - cv.bottom - ds);
108	    // the frame: along the centre line, across it level, up square to both
109	    let a0 = g.axis[0];
110	    let a1 = g.axis[1];
111	    let dv = [a1[0] - a0[0], a1[1] - a0[1], a1[2] - a0[2]];
112	    let len = (dv[0] * dv[0] + dv[1] * dv[1] + dv[2] * dv[2]).sqrt();
113	    let along = unit(dv);
114	    let across = unit([-along[1], along[0], 0.0]);
115	    let up = super::geom::cross(along, across);
116	    // the origin over the beam's level
117	    let fr = Frame { o: [a0[0], a0[1], a0[2] - ctx.host.elevation], along, across, up };
118	    // how far the bars run: past the ends by the anchors, else a cover short of them
119	    let (t0, t1) = {
120	        let st = anchor.as_ref().and_then(|m| f(m, "start"));
121	        let en = anchor.as_ref().and_then(|m| f(m, "end"));
122	        let t0 = match st {
123	            Some(x) => -not_negative("anchor start", x)?,
124	            None => cv.sides,
125	        };
126	        let t1 = match en {
127	            Some(x) => len + not_negative("anchor end", x)?,
128	            None => len - cv.sides,
129	        };
130	        (t0, t1)
131	    };
132	    let clear = |ds_: &[f64]| ctx.common.clearance_for(ds_);
133	    // the rows
134	    let read_row = |m: &Map, name: &str, is_top: bool| -> R<Row> {
135	        let d = diameter(name, f(m, "diameter").unwrap_or(0.0))?;
136	        let n = count(name, u(m, "count").unwrap_or(0))?;
137	        let a = a_in - d / 2.0;
138	        if a < 0.0 {
139	            return Err(format!(
140	                "the section is too narrow for the {} bars of {} mm with that cover and stirrup",
141	                name, d
142	            ));
143	        }
144	        if inner_h < d {
145	            return Err(format!("a {} mm {} bar doesn't fit inside the stirrup, {:.1} mm deep", d, name, inner_h));
146	        }
147	        let hooks = legs(&format!("{} hook", name), ("start", "end"), any(m, "hook"))?;
148	        for hk in [hooks.0, hooks.1] {
149	            if hk > inner_h - d / 2.0 + TOL {
150	                return Err(format!(
151	                    "a {} hook of {} mm doesn't fit inside the stirrup, which is {:.1} mm deep from the bars",
152	                    name, hk, inner_h
153	                ));
154	            }
155	        }
156	        let u_row = if is_top { top_in - d / 2.0 } else { bot_in + d / 2.0 };
157	        let mut bent = None;
158	        if let Some(b) = sub(m, "bent") {
159	            if is_top {
160	                return Err("only bottom bars are bent up: put `bent` in `bottom`".into());
161	            }
162	            let k = u(b, "count").unwrap_or(0);
163	            let most = n as i64 - 2;
164	            if k < 1 || k as i64 > most {
165	                return Err(format!(
166	                    "`bent` count {} must be 1 to {}: the two bars at the corners stay straight to hold the stirrups, and the bottom row has {}",
167	                    k, most, n
168	                ));
169	            }
170	            let angle = f(b, "angle").unwrap_or(45.0);
171	            if !(15.0..=75.0).contains(&angle) {
172	                return Err(format!("`bent` angle {} degrees isn't between 15 and 75", angle));
173	            }
174	            let tp = match f(b, "top") {
175	                Some(x) => positive("bent top", x)?,
176	                None => (t1 - t0) / 5.0,
177	            };
178	            let zt = top_in - d / 2.0;
179	            let rise = zt - u_row;
180	            if rise <= TOL {
181	                return Err(format!(
182	                    "there's no room to bend a bar of {} mm up: it can't rise from the bottom to the top inside the stirrup",
183	                    d
184	                ));
185	            }
186	            let run = rise / angle.to_radians().tan();
187	            let each = tp + run;
188	            if 2.0 * each > t1 - t0 {
189	                return Err(format!(
190	                    "the bent bars meet in the middle: each end takes {:.0} mm of the {:.0} mm: give a shorter `top` or a steeper `angle`",
191	                    each,
192	                    t1 - t0
193	                ));
194	            }
195	            bent = Some((k as usize, angle, tp));
196	        }
197	        let at = spread(-a, a, n);
198	        if n > 1 {
199	            let gap = 2.0 * a / (n - 1) as f64 - d;
200	            let c = clear(&[d]);
201	            if gap < c - TOL {
202	                return Err(format!(
203	                    "{} {} bars of {} mm leave {:.1} mm between them, less than the {} mm clearance: use fewer or thinner bars",
204	                    n, name, d, gap, c
205	                ));
206	            }
207	        }
208	        Ok(Row { n, d, hooks, bent, at, u: u_row })
209	    };
210	    let brow = match &bottom {
211	        Some(m) => Some(read_row(m, "bottom", false)?),
212	        None => None,
213	    };
214	    let trow = match &top {
215	        Some(m) => Some(read_row(m, "top", true)?),
216	        None => None,
217	    };
218	    // a bent-up bar running along the top must keep clear of the top bars
219	    if let (Some(b), Some(t)) = (&brow, &trow) {
220	        if let Some((k, _, _)) = b.bent {
221	            let zt = top_in - b.d / 2.0;
222	            let inner: Vec<usize> = (1..b.n - 1).collect();
223	            let c = clear(&[b.d, t.d]);
224	            for j in picks(inner.len(), k) {
225	                let ab = b.at[inner[j]];
226	                for at in &t.at {
227	                    let da = ab - at;
228	                    let du = zt - t.u;
229	                    let gap = (da * da + du * du).sqrt() - (b.d + t.d) / 2.0;
230	                    if gap < c - TOL {
231	                        return Err(format!(
232	                            "a bent-up bar meets a top bar: {:.1} mm between them, less than the {} mm clearance: bend up other bars or use fewer top bars",
233	                            gap, c
234	                        ));
235	                    }
236	                }
237	            }
238	        }
239	    }
240	    // skin bars up each side, between the rows
241	    let skin_rows = match &skin {
242	        Some(m) => {
243	            let dk = diameter("skin", f(m, "diameter").unwrap_or(0.0))?;
244	            let sp = spacing("skin", f(m, "spacing").unwrap_or(0.0), dk)?;
245	            let ub = match &brow {
246	                Some(r) => r.u,
247	                None => bot_in,
248	            };
249	            let ut = match &trow {
250	                Some(r) => r.u,
251	                None => top_in,
252	            };
253	            let n = gaps(ut - ub, sp);
254	            let ak = a_in - dk / 2.0;
255	            let us: Vec<f64> = (1..n).map(|i| ub + (ut - ub) * i as f64 / n as f64).collect();
256	            Some((dk, ak, us))
257	        }
258	        None => None,
259	    };
260	    // the stirrups
261	    let mut st_stations: Vec<f64> = Vec::new();
262	    let mut st_hook = 0.0;
263	    if let Some(m) = &stirrup {
264	        let st = stir::read_rest(m, ds)?;
265	        st_hook = st.hook;
266	        let s0 = cv.sides + ds / 2.0;
267	        let s1 = len - (cv.sides + ds / 2.0);
268	        let zs = stir::zones(s0, s1, &st);
269	        let others = brow.as_ref().map(|r| r.n).unwrap_or(0)
270	            + trow.as_ref().map(|r| r.n).unwrap_or(0)
271	            + skin_rows.as_ref().map(|s| 2 * s.2.len()).unwrap_or(0);
272	        if stir::count(&zs) + others as f64 > MAX_BARS as f64 {
273	            return Err(format!(
274	                "that is more than the {} bars a command makes: widen a spacing or use fewer bars",
275	                MAX_BARS
276	            ));
277	        }
278	        st_stations = stir::places(&zs);
279	    }
280	    // the bars
281	    let gb = ctx.common.grade.clone();
282	    let gs = ctx.common.grade_stirrup.clone();
283	    let mut bars: Vec<Bar> = Vec::new();
284	    let straight = |r: &Row, a: f64, up_sign: f64| -> Vec<[f64; 3]> {
285	        let mut p = Vec::with_capacity(4);
286	        if r.hooks.0 > TOL {
287	            p.push(fr.at(t0, a, r.u + up_sign * r.hooks.0));
288	        }
289	        p.push(fr.at(t0, a, r.u));
290	        p.push(fr.at(t1, a, r.u));
291	        if r.hooks.1 > TOL {
292	            p.push(fr.at(t1, a, r.u + up_sign * r.hooks.1));
293	        }
294	        p
295	    };
296	    if let Some(r) = &brow {
297	        let chosen: Vec<usize> = match r.bent {
298	            Some((k, _, _)) => picks(r.n - 2, k).into_iter().map(|j| j + 1).collect(),
299	            None => Vec::new(),
300	        };
301	        for (i, a) in r.at.iter().enumerate() {
302	            if chosen.contains(&i) {
303	                let (_, angle, tp) = r.bent.unwrap();
304	                let zt = top_in - r.d / 2.0;
305	                let run = (zt - r.u) / angle.to_radians().tan();
306	                let path = vec![
307	                    fr.at(t0, *a, zt),
308	                    fr.at(t0 + tp, *a, zt),
309	                    fr.at(t0 + tp + run, *a, r.u),
310	                    fr.at(t1 - tp - run, *a, r.u),
311	                    fr.at(t1 - tp, *a, zt),
312	                    fr.at(t1, *a, zt),
313	                ];
314	                bars.push(Bar { path, diameter: r.d, grade: gb.clone(), layer: "bent".into() });
315	            } else {
316	                bars.push(Bar { path: straight(r, *a, 1.0), diameter: r.d, grade: gb.clone(), layer: "bottom".into() });
317	            }
318	        }
319	    }
320	    if let Some(r) = &trow {
321	        for a in &r.at {
322	            bars.push(Bar { path: straight(r, *a, -1.0), diameter: r.d, grade: gb.clone(), layer: "top".into() });
323	        }
324	    }
325	    if let Some((dk, ak, us)) = &skin_rows {
326	        for uu in us {
327	            for a in [-*ak, *ak] {
328	                let path = vec![fr.at(t0, a, *uu), fr.at(t1, a, *uu)];
329	                bars.push(Bar { path, diameter: *dk, grade: gb.clone(), layer: "skin".into() });
330	            }
331	        }
332	    }
333	    if stirrup.is_some() {
334	        let sa = hw - cv.sides - ds / 2.0;
335	        let su = top_in + ds / 2.0;
336	        let sb = bot_in - ds / 2.0;
337	        for t in &st_stations {
338	            let c0 = fr.at(*t, -sa, su);
339	            let c1 = fr.at(*t, sa, su);
340	            let c2 = fr.at(*t, sa, sb);
341	            let c3 = fr.at(*t, -sa, sb);
342	            let path = stir::hooked(vec![c0, c1, c2, c3, c0], st_hook);
343	            bars.push(Bar { path, diameter: ds, grade: gs.clone(), layer: "stirrup".into() });
344	        }
345	    }
346	    if bars.len() > MAX_BARS {
347	        return Err(format!(
348	            "that is more than the {} bars a command makes: widen a spacing or use fewer bars",
349	            MAX_BARS
350	        ));
351	    }
352	    let _ = de::s;
353	    let info = norm::Info::default();
354	    Ok(Armed { bars, info })
355	}
