#!/usr/bin/env python3
"""List a project's elements (not levels) briefly: id, category, type and a few fields."""
import json, sys
for fn in sys.argv[1:]:
    print('==', fn)
    j = json.load(open(fn))
    for k, v in j['elements'].items():
        if v.get('category') == 'level':
            continue
        extra = {x: v[x] for x in v if x in ('angle', 'height', 'top', 'base', 'offset', 'points', 'at', 'outline')}
        print(' ', k, v.get('category'), v.get('type'), json.dumps(extra)[:200])

