2	//! section (`x` across its width, `y` across its depth, corners counted) or `count` round a
3	//! round one, legs turned into the section at the foot and the top (`hook`), a step toward the
4	//! axis near the top (`jog`); `stirrup`s (a round column's a polygon of 24 sides), `ties`
5	//! across a rectangular section, `anchor`s past the ends. Laid out in the column's frame: up
6	//! along its axis from its base, across along its width (its angle), and along its depth.
7	
8	use super::beam::legs;
9	use super::de::{any, f, sub, u};
10	use super::geom::{add as vadd, spread, sub as vsub, unit, Frame, V3, TOL};
11	use super::shapes::{COLUMN_ANCHOR, COLUMN_BARS, STIRRUP, TIES};
12	use super::{check_keys, diameter, norm, not_negative, positive, read_struct, stir, Armed, Bar, Ctx, MAX_COUNT};
13	use crate::json::Value;
14	use crate::structure::common::R;
15	use crate::structure::members::geom::column_geom;
16	use crate::structure::rebar::MAX_BARS;
17	
18	/// The sides of a round column's stirrups.
19	pub const ROUND_SIDES: usize = 24;
20	
21	/// A bar of a rectangular column: where it is and which way its legs and its jog go.
22	#[derive(Clone, Copy)]
23	struct Place {
24	    a: f64,
25	    b: f64,
26	    /// A round column's bar: its radius and the cosine and sine of its angle.
27	    r: f64,
28	    pc: f64,
29	    ps: f64,
30	    /// The way into the section along across and along the depth (a corner bar's legs go
31	    /// along the depth; its jog both ways).
32	    leg: (f64, f64),
33	    jog: (f64, f64),
34	}
35	
36	pub fn arm(ctx: &Ctx) -> R<Armed> {
