316	        let zs = stir::zones(s0, s1, &st);
317	        let per = 1 + if tie.is_some() { x_inner.len() + y_inner.len() } else { 0 };
318	        if stir::count(&zs) * per as f64 + out.len() as f64 > MAX_BARS as f64 {
