330	                let rs = hw - cv.sides - ds / 2.0;
331	                let mut v: Vec<V3> = (0..ROUND_SIDES)
332	                    .map(|k| {
333	                        let phi = 2.0 * std::f64::consts::PI * k as f64 / ROUND_SIDES as f64;
334	                        let (ps, pc) = phi.sin_cos();
335	                        fr.at(t, rs * pc, rs * ps)
336	                    })
