116	pub fn arm(ctx: &Ctx) -> R<Armed> {
117	    let pr = ctx.pr;
118	    let slab = read_slab(pr, ctx.e);
119	    let params = ctx.params;
120	    let bottom = read_struct(params, "bottom", &GRID)?;
121	    let top = read_struct(params, "top", &GRID)?;
122	    check_keys(params, "floor")?;
123	    let has = |m: &Option<Map>| m.as_ref().map(|m| m.contains("x") || m.contains("y")).unwrap_or(false);
124	    if !has(&bottom) && !has(&top) {
125	        return Err("nothing to reinforce with: give a `bottom` or a `top` mesh with `x` or `y` bars".into());
126	    }
127	    let cv = ctx.cover;
128	    // the meshes' hooks and diameters
129	    let mut meshes: Vec<(&'static str, &Map, f64)> = Vec::new();
130	    for (name, m) in [("bottom", &bottom), ("top", &top)] {
131	        let m = match m {
132	            Some(m) if m.contains("x") || m.contains("y") => m,
133	            _ => continue,
134	        };
135	        let hook = match f(m, "hook") {
136	            Some(h) => not_negative("hook", h)?,
137	            None => 0.0,
138	        };
139	        for k in ["x", "y"] {
140	            if let Some(l) = sub(m, k) {
141	                diameter(name, f(l, "diameter").unwrap_or(0.0))?;
142	            }
143	        }
144	        meshes.push((name, m, hook));
145	    }
146	    let th = slab.thickness;
147	    let room = th - cv.top - cv.bottom;
148	    let mesh_thick = |m: &Map| -> f64 {
149	        ["x", "y"].iter().filter_map(|k| sub(m, k)).map(|l| f(l, "diameter").unwrap_or(0.0)).sum()
150	    };
151	    let all_d: Vec<f64> = meshes
152	        .iter()
153	        .flat_map(|(_, m, _)| ["x", "y"].iter().filter_map(|k| sub(m, k)).map(|l| f(l, "diameter").unwrap_or(0.0)).collect::<Vec<_>>())
154	        .collect();
155	    if meshes.len() == 2 {
156	        let gap = room - mesh_thick(meshes[0].1) - mesh_thick(meshes[1].1);
157	        let c = ctx.common.clearance_for(&all_d);
158	        if gap < c - TOL {
159	            return Err(format!(
160	                "the meshes at the top and the bottom meet: {:.1} mm between them, less than the {} mm clearance",
161	                gap, c
162	            ));
163	        }
164	    } else if mesh_thick(meshes[0].1) > room {
165	        return Err(format!("the mesh doesn't fit the floor's {} mm thickness between the covers", th));
166	    }
167	    // the layers, each its depth below the top
168	    let mut layers: Vec<Layer> = Vec::new();
169	    for (name, m, hook) in &meshes {
170	        let bottom_mesh = *name == "bottom";
171	        // what lies between the face and the layer: the cover and the layers before it
172	        let mut below = if bottom_mesh { cv.bottom } else { cv.top };
173	        for (k, along_x) in [("x", true), ("y", false)] {
174	            let l = match sub(m, k) {
175	                Some(l) => l,
176	                None => continue,
177	            };
178	            let d = f(l, "diameter").unwrap_or(0.0);
179	            let lname: &'static str = match (bottom_mesh, along_x) {
180	                (true, true) => "bottom x",
181	                (true, false) => "bottom y",
182	                (false, true) => "top x",
183	                (false, false) => "top y",
184	            };
185	            let sp = f(l, "spacing").unwrap_or(0.0);
186	            let off = if bottom_mesh { th - below - d / 2.0 } else { below + d / 2.0 };
187	            below += d;
188	            layers.push(Layer {
189	                name: lname,
190	                along_x,
191	                d,
192	                spacing: sp,
193	                off,
194	                hook_dir: if bottom_mesh { 1.0 } else { -1.0 },
195	                hook: *hook,
196	            });
197	        }
198	    }
199	    // the outline's extent
200	    let (mut x0, mut y0, mut x1, mut y1) = (f64::INFINITY, f64::INFINITY, f64::NEG_INFINITY, f64::NEG_INFINITY);
201	    for p in &slab.outline {
202	        x0 = x0.min(p[0]);
203	        y0 = y0.min(p[1]);
204	        x1 = x1.max(p[0]);
205	        y1 = y1.max(p[1]);
206	    }
207	    let mut rings: Vec<&[[f64; 2]]> = vec![&slab.outline];
208	    for o in &slab.openings {
209	        rings.push(o);
210	    }
211	    // the top: its height at a point (over the level) and the way square to it
212	    let elev = ctx.host.elevation;
213	    let z0 = elev + slab.offset;
214	    // the top's plane: z = a x + b y + c, rising `slope` degrees along the arrow from its tail
215	    let (pa, pb, pc, sec, normal) = match slab.slope {
216	        Some((s, tail, head)) => {
217	            let r = s.to_radians();
218	            let dx = head[0] - tail[0];
219	            let dy = head[1] - tail[1];
220	            let k = 1.0 / (dx * dx + dy * dy).sqrt();
221	            let u = [dx * k, dy * k];
222	            let tan = r.tan();
223	            let a = u[0] * tan;
224	            let b = u[1] * tan;
225	            let (sn, cs) = r.sin_cos();
226	            (a, b, z0 - a * tail[0] - b * tail[1], 1.0 / cs, [-sn * u[0], -sn * u[1], cs])
227	        }
228	        None => (0.0, 0.0, z0, 1.0, [0.0, 0.0, 1.0]),
229	    };
230	    let sloped = slab.slope.is_some();
231	    // a layer's height over the level at a point
232	    let height = |x: f64, y: f64, off: f64| -> f64 {
233	        if sloped {
234	            ((pa * x + pb * y + pc) - elev) - off * sec
235	        } else {
236	            (z0 - elev) - off
237	        }
238	    };
239	    let gb = ctx.common.grade.clone();
240	    let mut out: Vec<Bar> = Vec::new();
241	    for l in &layers {
242	        spacing(l.name, l.spacing, l.d)?;
243	        let (lo, hi) = if l.along_x { (y0, y1) } else { (x0, x1) };
244	        let a = lo + cv.sides + l.d / 2.0;
245	        let b = hi - cv.sides - l.d / 2.0;
246	        if b < a {
247	            return Err(format!("the {} bars don't fit inside that cover", l.name));
248	        }
249	        let span = b - a;
250	        if span > 0.0 {
251	            let n = gaps(span, l.spacing);
252	            let step = span / n as f64;
253	            let gap = step - l.d;
254	            let c = ctx.common.clearance_for(&[l.d]);
255	            if gap < c - TOL {
256	                return Err(format!(
257	                    "{} bars of {} mm each {:.1} mm leave {:.1} mm between them, less than the {} mm clearance: widen the spacing",
258	                    l.name, l.d, step, gap, c
259	                ));
260	            }
261	        }
262	        // a leg from one face to the cover on the other
263	        let reach = th - cv.top - cv.bottom - l.d
264	            - if l.hook_dir > 0.0 { (th - cv.bottom - l.d / 2.0) - l.off } else { l.off - l.d / 2.0 - cv.top };
265	        if l.hook > TOL && l.hook > reach + TOL {
266	            return Err(format!(
267	                "a hook of {} mm doesn't fit the {} bars, which have {:.1} mm to the cover on the other face",
268	                l.hook, l.name, reach
269	            ));
270	        }
271	        if station_count(a, b, l.spacing) > (MAX_BARS + 1) as f64 {
272	            return Err(format!(
273	                "that is more than the {} bars a command makes: widen a spacing or use fewer bars",
274	                MAX_BARS
275	            ));
276	        }
277	        let lines = if span > 0.0 { stations(a, b, l.spacing) } else { vec![a] };
278	        for c in lines {
279	            for (u0, u1) in chords(&rings, c, l.along_x) {
280	                let s0 = u0 + cv.sides;
281	                let s1 = u1 - cv.sides;
282	                if s1 - s0 <= TOL {
283	                    continue;
284	                }
285	                let point = |u: f64| -> V3 {
286	                    let (x, y) = if l.along_x { (u, c) } else { (c, u) };
287	                    [x, y, height(x, y, l.off)]
288	                };
289	                let p0 = point(s0);
290	                let p1 = point(s1);
291	                let leg = |p: V3| -> V3 {
292	                    let h = l.hook * l.hook_dir;
293	                    [p[0] + normal[0] * h, p[1] + normal[1] * h, p[2] + normal[2] * h]
294	                };
295	                let mut path = Vec::with_capacity(4);
296	                if l.hook > TOL {
297	                    path.push(leg(p0));
298	                }
299	                path.push(p0);
300	                path.push(p1);
301	                if l.hook > TOL {
302	                    path.push(leg(p1));
303	                }
304	                out.push(Bar { path, diameter: l.d, grade: gb.clone(), layer: l.name.into() });
305	                if out.len() > MAX_BARS {
306	                    return Err(format!(
307	                        "that is more than the {} bars a command makes: widen a spacing or use fewer bars",
308	                        MAX_BARS
309	                    ));
310	                }
311	            }
312	        }
313	    }
314	    Ok(Armed { bars: out, info: norm::Info::default() })
315	}
