    let (ps, pc) = phi.sin_cos();
    let (a, b) = (r * pc, r * ps);
    // toward the axis: the bar's place, reversed and made a unit
    let k = 1.0 / (a * a + b * b).sqrt();
    let toward = (-a * k, -b * k);
    places.push(Place { a, b, r, pc, ps, leg: toward, jog: toward });
}

