import json, math, pickle, sys, itertools
results = pickle.load(open('/tmp/rebar-agent/fl_rand.pkl', 'rb'))
CACHE = {}
def load(f):
    if f not in CACHE: CACHE[f] = json.load(open(f))
    return CACHE[f]
score = {}
for f, line, res in results:
    if res['stderr'] or 'bars' not in res: continue
    p = json.loads(line.split(' ', 1)[1])
    j0 = load(f); e = j0['elements'][str(p['host'])]
    sl = e.get('slope'); ar = e.get('arrow')
    if not sl: continue
    elev = [v for v in j0['elements'].values() if v['guid'] == e['level']][0]['elevation']
    tname = [v['name'] for v in j0['library'].values() if v['guid'] == e['type']][0]
    th = j0['types']['floor'][tname]['thickness']
    off = e.get('offset', 0.0)
    cv = p['cover']; ct, cb, cs = (cv['top'], cv['bottom'], cv['sides']) if isinstance(cv, dict) else (cv, cv, cv)
    r = sl * (math.pi / 180.0)
    tx, ty = ar[0]; hx, hy = ar[1]; dx = hx - tx; dy = hy - ty; L = math.sqrt(dx * dx + dy * dy)
    ux, uy = dx * (1 / L), dy * (1 / L)
    tn = math.tan(r)
    a_ = ux * tn; b_ = uy * tn
    secs = {'sec': 1 / math.cos(r), 'cos': None}
    for b in res['bars']:
        lay = b['layer']; mesh, axis = lay.split(); m = p[mesh]; d = m[axis]['diameter']
        dxx = m['x']['diameter'] if (axis == 'y' and 'x' in m) else 0.0
        o_ = th - (cb + dxx) - d / 2 if mesh == 'bottom' else (ct + dxx) + d / 2
        hk = m.get('hook') or 0.0
        pts = b['path'][1:3] if hk > 1.0 else b['path'][0:2]
        for P in pts:
            x, y, z = P
            cands = {}
            for z0n, z0 in (('abs', elev + off), ('rel', off), ('elev_then', elev)):
                for cn, cc in (('c0', z0 - a_ * tx - b_ * ty), ('c1', z0 - (a_ * tx + b_ * ty)), ('c2', z0 + (-a_ * tx - b_ * ty))):
                    zs = {'(ax+by)+c': (a_ * x + b_ * y) + cc, 'ax+(by+c)': a_ * x + (b_ * y + cc), '(ax+c)+by': (a_ * x + cc) + b_ * y, 'c+ax+by': (cc + a_ * x) + b_ * y}
                    for zn, zt in zs.items():
                        if z0n == 'abs':
                            fin = {'e1': (zt - elev) - o_ / math.cos(r), 'e1s': (zt - elev) - o_ * (1 / math.cos(r)), 'e2': (zt - o_ / math.cos(r)) - elev, 'e2s': (zt - o_ * (1 / math.cos(r))) - elev}
                        elif z0n == 'rel':
                            fin = {'r': zt - o_ / math.cos(r), 'rs': zt - o_ * (1 / math.cos(r))}
                        else:
                            # top = elev + (plane + off)
                            fin = {'x1': ((zt + off) - elev) - o_ / math.cos(r), 'x2': ((zt + off) - elev) - o_ * (1 / math.cos(r))}
                        for fn, v in fin.items():
                            cands[(z0n, cn, zn, fn)] = v
            sec = 1 / math.cos(r); cosr = math.cos(r)
            for z0n, z0 in (('abs', elev + off), ('rel', off)):
                for cn, cc in (('c0', z0 - a_ * tx - b_ * ty), ('c1', z0 - (a_ * tx + b_ * ty))):
                    for ln, cl in (('sec', cc - o_ * sec), ('cos', cc - o_ / cosr)):
                        if z0n == 'abs':
                            for en, ce in (('pre', cl - elev),):
                                cands[('L', z0n, cn, ln, en, 'a')] = (a_ * x + b_ * y) + ce
                                cands[('L', z0n, cn, ln, en, 'b')] = a_ * x + (b_ * y + ce)
                            cands[('L', z0n, cn, ln, 'post', 'a')] = ((a_ * x + b_ * y) + cl) - elev
                            cl2 = (cc - elev) - o_ * sec
                            cands[('L2', z0n, cn, ln, 'mid', 'a')] = (a_ * x + b_ * y) + cl2
                        else:
                            cands[('L', z0n, cn, ln, '-', 'a')] = (a_ * x + b_ * y) + cl
            for k, v in cands.items():
                sc_ = score.setdefault(k, [0, 0]); sc_[1] += 1; sc_[0] += (v == z)
