#!/usr/bin/env python3
"""Random floor projects (built with the original) and reinforce cases.
usage: gen_floors.py SEED NCASES -> /tmp/rebar-agent/gl_SEED.bimcraft and gl_SEED.txt"""
import sys, json, random, subprocess, os, tempfile, shutil, math
seed = int(sys.argv[1]); ncases = int(sys.argv[2])
R = random.Random(seed)
def rnd(a, b, nd=None):
    x = R.uniform(a, b)
    if nd is None: nd = R.choice([0, 0, 1, 2, 3])
    return round(x, nd)
cmds = ['level {"name":"LA","elevation":%s}' % rnd(-3000, 9000)]
tnames = []
for i in range(3):
    t = rnd(120, 400); n = 'S%d %s' % (i, t); tnames.append(n)
    cmds.append('type ' + json.dumps({"category": "floor", "name": n, "thickness": t}))
def poly(cx, cy):
    k = R.choice(['rect', 'rect', 'quad', 'L', 'tri', 'hex'])
    if k == 'rect':
        w = rnd(1500, 7000); h = rnd(1500, 7000)
        return [[cx, cy], [cx + w, cy], [cx + w, cy + h], [cx, cy + h]], (w, h, True)
    if k == 'quad':
        w = rnd(2000, 6000); h = rnd(2000, 6000)
        return [[cx, cy], [cx + w, cy + rnd(-800, 800)], [cx + w + rnd(-800, 800), cy + h], [cx + rnd(-800, 800), cy + h + rnd(-500, 500)]], (w, h, False)
    if k == 'L':
        w = rnd(3000, 7000); h = rnd(3000, 7000); a = rnd(0.3, 0.7, 2); b = rnd(0.3, 0.7, 2)
        return [[cx, cy], [cx + w, cy], [cx + w, cy + h * b], [cx + w * a, cy + h * b], [cx + w * a, cy + h], [cx, cy + h]], (w, h, False)
    if k == 'tri':
        w = rnd(2000, 6000); h = rnd(2000, 6000)
        return [[cx, cy], [cx + w, cy], [cx + w * rnd(0.2, 0.8, 2), cy + h]], (w, h, False)
    r = rnd(1500, 3500)
    return [[round(cx + r + r * math.cos(i * math.pi / 3), 1), round(cy + r + r * math.sin(i * math.pi / 3), 1)] for i in range(6)], (2 * r, 2 * r, False)
for i in range(7):
    cx = rnd(-20000, 20000); cy = rnd(-20000, 20000)
    b, (w, h, isrect) = poly(cx, cy)
    f = {"boundary": b, "type": R.choice(tnames + ["Generic - 200mm"]), "level": R.choice(["Level 1", "Level 2", "LA"])}
    if isrect and R.random() < 0.6 and w > 2500 and h > 2500:
        ox = cx + w * rnd(0.3, 0.5, 2); oy = cy + h * rnd(0.3, 0.5, 2); ow = rnd(300, 900); oh = rnd(300, 900)
        f["openings"] = [[[ox, oy], [ox + ow, oy], [ox + ow, oy + oh], [ox, oy + oh]]]
    if R.random() < 0.4: f["offset"] = rnd(-300, 300)
    if R.random() < 0.4:
        f["slope"] = rnd(-8, 8)
        ang = R.uniform(0, 6.283)
        tx, ty = b[0]
        f["arrow"] = [[tx, ty], [round(tx + 1000 * math.cos(ang), 1), round(ty + 1000 * math.sin(ang), 1)]]
    cmds.append('floor ' + json.dumps(f))
d = tempfile.mkdtemp()
cl = ['/workspace/executable', 'run']
for c in cmds: cl += ['--cmd', c]
cl += ['--save', 'in.bimcraft']
p = subprocess.run(cl, cwd=d, capture_output=True, text=True)
if p.returncode != 0:
    print('build failed', p.stderr[:300]); sys.exit(1)
out = '/tmp/rebar-agent/gl_%d.bimcraft' % seed
shutil.copy(os.path.join(d, 'in.bimcraft'), out); shutil.rmtree(d)
j = json.load(open(out))
fls = [int(k) for k, v in j['elements'].items() if v['category'] == 'floor']
cases = []
for i in range(ncases):
    p = {"host": R.choice(fls)}
    if R.random() < 0.6: p["cover"] = R.choice([15, 20, 25, 30, rnd(10, 40)])
    else: p["cover"] = {"top": rnd(10, 40), "bottom": rnd(10, 40), "sides": rnd(10, 60)}
    for mn in ("bottom", "top"):
        if R.random() < 0.7:
            m = {}
            if R.random() < 0.8: m["x"] = {"diameter": R.choice([6.3, 8, 10, 12.5, rnd(5, 16)]), "spacing": R.choice([150, 200, 250, rnd(100, 600)])}
            if R.random() < 0.6: m["y"] = {"diameter": R.choice([6.3, 8, 10, 12.5, rnd(5, 16)]), "spacing": R.choice([150, 200, 250, rnd(100, 600)])}
            if R.random() < 0.3: m["hook"] = rnd(0, 120)
            p[mn] = m
    if R.random() < 0.1: p["clearance"] = rnd(5, 30)
    cases.append('reinforce ' + json.dumps(p))
open('/tmp/rebar-agent/gl_%d.txt' % seed, 'w').write('@file %s\n' % out + '\n'.join(cases) + '\n')
print('ok', out, len(cases))

