"""My current best model of the original's beam frame, for diagnosis."""
import math
def length(v):
    return math.sqrt(v[0]*v[0]+v[1]*v[1]+v[2]*v[2])
def normalize(v):
    r = 1.0 / length(v)
    return [v[0]*r, v[1]*r, v[2]*r]
def cross(a, b):
    return [a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0]]
def frame(e, elev, t, V=None):
    V = V or {}
    w, h = t['width'], t['depth']
    s, en = e['start'], e['end']; off = e.get('offset', 0.0); eoff = e.get('end_offset', off); just = e.get('justify', 'top')
    dx = en[0]-s[0]; dy = en[1]-s[1]
    plan = math.sqrt(dx*dx+dy*dy); rz = eoff-off; ln = math.sqrt(dx*dx+dy*dy+rz*rz)
    hm = V.get('half', 'a')
    if hm == 'a': half = h/2.0*(ln/plan)
    elif hm == 'b': half = h/2.0*ln/plan
    elif hm == 'c': half = h*ln/plan/2.0
    elif hm == 'd': half = h/2.0/(plan/ln)
    elif hm == 'e': half = h/2.0/math.cos(math.atan2(abs(rz), plan))
    elif hm == 'f': half = h/2.0*math.hypot(plan, rz)/plan
    ch = lambda z: z - half if just == 'top' else (z if just == 'centre' else z + half)
    z0 = ch(elev+off); z1 = ch(elev+eoff)
    dv = [dx, dy, z1-z0]
    L = length(dv) if V.get('L', 'axis') == 'axis' else (ln if V.get('L') == 'line' else None)
    al0 = normalize(dv)
    if L is None: L = al0[0]*dv[0] + al0[1]*dv[1] + al0[2]*dv[2]
    al = normalize(dv)
    ac = normalize([-al[1], al[0], 0.0])
    up = cross(al, ac)
    o = [s[0], s[1], z0 - elev]
    return dict(o=o, al=al, ac=ac, up=up, L=L, w=w, h=h, half=half)
def at(F, tt, a, u):
    o, al, ac, up = F['o'], F['al'], F['ac'], F['up']
    return [o[i] + al[i]*tt + ac[i]*a + up[i]*u for i in range(3)]

