/// The length of a path: the sum of its straight pieces.
pub fn length(path: &[[f64; 3]]) -> f64 {
    let mut l = 0.0;
    for w in path.windows(2) {
        let dx = w[1][0] - w[0][0];
        let dy = w[1][1] - w[0][1];
        let dz = w[1][2] - w[0][2];
        l += (dx * dx + dy * dy + dz * dz).sqrt();
    }
    l
}

